INSERT INTO `activites` (`id`, `title_en`, `title_fr`, `description_en`, `description_fr`, `slug`, `image`, `categorie_activity_slug`, `created_at`, `updated_at`) VALUES
(1, 'Canada in celebration', 'Canada en fête', '<p>Sofifran received an $ 12,000 from the Canadian Party Celebration Celebration Celebration Program. The event which will consist of a large free multicultural buffet will take place on July 1 at the Welland Farmer\'s Market.<br></p>', '<p>&nbsp;Sofifran a reçu un octroi de 12,000 $ du programme de célébrations et commémorations de Patrimoine Canadien du volet le Canada en fête. L’événement qui consistera en un grand buffet multiculturel gratuit aura lieu le 1er juillet au Welland Farmer\'s Market.&nbsp;<br></p>', 'canada-en-fete', '1653304860.jpg', 'culturel', '2022-05-23 11:53:09', '2022-05-23 11:53:09'),
(2, 'UNDERTAKES', 'ENTREPREND', '<p>Starting a business is a dream for many of us! Yes but how ? Fears, procedures, funding can be very intimidating from the outside.&nbsp;<span style=\"font-size: 1rem;\">This is why Sofifran has set up the “EntrePrend” project which prepares and supports participants to launch and succeed in the life of an entrepreneur.</span></p><p>This project, alongside 3 active partners: SÉO, SADDEC, and YPMD Consulting, is divided into workshops until March 2020, in order to train, help and support any French-speaking woman wishing to settle in its account. Our Partners run workshops that each address an important angle of the entrepreneurial process and prepare participants for the reality of business life.</p><ul><li>YPMD Consulting: presentation of the workshop on “Entrepreneurial culture in Canada vs. country of origin”. Objective: to understand and assimilate the differences between the two practices and the need to consider entrepreneurship in Canada differently.</li><li>The SÉO: a series of workshops comprising six sessions, the first of which is entitled “Launch your business”. Objective: to provide participants with the tools and coaching essential to the success of their business.</li><li>La SADDEC: workshop “Take the leap in confidence and take up the entrepreneurial challenge” model of success, sharing of experiences and entrepreneurial know-how.</li></ul><p>Register by email by clicking or by phone at&nbsp;<span style=\"font-weight: bolder;\">905-714-7333</span></p>', '<p>Monter son entreprise, le rêve pour beaucoup d’entre nous ! Oui, mais comment ? Les craintes, les démarches, les financements peuvent être bien intimidants vue de l’extérieur.&nbsp;<span style=\"font-size: 1rem;\">C’est pourquoi Sofifran a mis en place le projet ”EntrePrend” qui prépare et accompagne les participantes à lancer et à réussir la vie d’entrepreneure.</span></p><p>Ce projet, aux côtés de 3 partenaires actifs : SÉO, SADDEC, et YPMD Consulting, est réparti en ateliers jusqu’au mois de Mars 2020, afin de former, d’aider et d’accompagner toute femme francophone désireuse de s’établir à son compte. Nos Partenaires prennent en charge des ateliers qui abordent chacun un angle important du processus entrepreneurial et préparent les participantes à la réalité de la vie d’affaires.</p><ul><li>YPMD Consulting : présentation de l’atelier sur « La culture entrepreneuriale au Canada vs pays d’origine ». Objectif : comprendre et assimiler les différences entre les deux pratiques et la nécessité d’envisager autrement l’entrepreneuriat au Canada.</li><li>La SÉO : une série d’ateliers comprenant six sessions dont le premier a pour titre « Lance ton affaire ». Objectif : fournir aux participantes les outils et le coaching indispensables à l’aboutissement et à la réussite de son entreprise.</li><li>La SADDEC : atelier « Fais le grand saut en confiance et relève le défi entrepreneurial » modèle de réussite, partage d’expériences et de savoir-faire entrepreneuriaux.</li></ul><p>Inscrivez-vous par courriel en cliquant ou par téléphone au&nbsp;<span style=\"font-weight: bolder;\">905-714-7333</span></p>', 'entreprend', '1652713409.jpg', 'economique', '2022-05-25 17:39:22', '2022-05-25 15:39:22'),
(3, 'Ontario Trillium Foundation - Program of the Fund for Resilient Communities', 'Fondation Trillium de l’Ontario - Programme du fonds pour les communautés résilientes', '<p>This project, which is funded by the Ontario Trillium Foundation in the amount of $ 50,600, allows Sofifran: to acquire film technical equipment; develop content, tools and resources accessible online; to create a digital development unit; to provide training to employees on new technologies and software; to defray the costs of expert advice technicians as well as to provide staff and volunteers.<br></p>', '<p>Ce projet qui est financé par la Fondation Trillium de l\'Ontario au montant de 50,600 $ permet à Sofifran: d\'acquérir des équipements techniques filmiques ; de développer des contenus, des outils et des ressources accessibles en ligne ; de créer une unité de développement numérique ; d’offrir une formation aux employés sur les nouvelles technologies et logiciels ; de défrayer les coûts de techniciens experts conseils ainsi que d’assurer la formation du personnel et des bénévoles.<br></p>', 'fondation-trillium-de-lontario-programme-du-fonds-pour-les-communautes-resilientes-1', '1653304807.jpg', 'educatif', '2022-05-27 21:12:36', '2022-05-27 21:12:36'),
(5, 'Community of entrepreneurship for black communities', 'Communaute de pratique en entrepreneuriat  pour les communautés noires', '<p>The project is the development and implementation of a community of practice allowing young black entrepreneurs to develop their organizational capacity and to access advice services in order to increase their performance. They will pool their difficulties, their experiences in a particular field.</p><p><span id=\"docs-internal-guid-e0001e4c-7fff-bc37-7021-4021aad5bea2\"><a href=\"https://form.jotform.com/220824268786062\">https://form.jotform.com/220824268786062</p>', '<p>Le projet consiste le développement et la mise en place une communauté de pratique permettant aux jeunes entrepreneurs noirs de développer leur capacité organisationnelle et d’accéder à des services de conseils afin d\'accroître leur rendement. Ils vont mettre en commun leurs difficultés, leurs expériences dans un domaine particulier.</p><p><a href=\"https://form.jotform.com/220824268786062\">https://form.jotform.com/220824268786062</a>', 'communaute-de-pratique-en-entrepreneuriat-pour-les-communautes-noires', '1653308090.jpg', 'economique', '2022-05-25 17:39:53', '2022-05-25 15:39:53'),
(6, '2022 Mothers\'Day', 'Fête des mères 2022', '<p>On Sunday, May 8, Sofifran celebrated Niagara\'s French-speaking immigrant moms with gifts and a potluck that brought together over 60 adults and children.<br></p>', '<p>Le dimanche 8 mai Sofifran a célébré les mamans immigrantes francophones du Niagara avec des cadeaux et un potluck qui a rassemblé plus de 60 adultes et enfants.</p>', 'fete-mere', '1653684880.JPG', 'social', '2022-05-27 21:12:58', '2022-05-27 21:12:58'),
(7, 'Partenariat Vice Versa - Conseil scolaire Viamonde', 'Partenariat Vice Versa - Conseil scolaire Viamonde', '<p>Nous tenons à remercier spécialement Vice Versa d’avoir donné l’opportunité à SOFIFRAN de créer ces moments de joie inoubliables en juin dernier et septembre 2022, et ce, en collaboration avec toutes les écoles du Conseil scolaire Viamonde de la région du Niagara, l’É.É. L’Héritage, É.É. LaMarsh, É.É. Franco-Niagara, É.É. Nouvel Horizon ainsi que l’É.S. Franco-Niagara !</p><p><img src=\"data:image/png;base64,\" style=\"width: 235px;\" data-filename=\"unnamed.png\">&nbsp; &nbsp;<img src=\"data:image/jpeg;base64,\" style=\"width: 259.477px; height: 172.984px;\" data-filename=\"1652816000.jpg\"><br></p>', '<p>Nous tenons à remercier spécialement Vice Versa d’avoir donné l’opportunité à SOFIFRAN de créer ces moments de joie inoubliables en juin dernier et septembre 2022, et ce, en collaboration avec toutes les écoles du Conseil scolaire Viamonde de la région du Niagara, l’É.É. L’Héritage, É.É. LaMarsh, É.É. Franco-Niagara, É.É. Nouvel Horizon ainsi que l’É.S. Franco-Niagara !</p><p><img src=\"data:image/png;base64,\" style=\"width: 235px;\" data-filename=\"unnamed.png\">&nbsp;&nbsp;<img src=\"data:image/jpeg;base64,\" style=\"width: 230.094px; height: 153.396px;\" data-filename=\"1652816000.jpg\"><br></p>', 'partenariat-vice-versa-conseil-scolaire-viamonde', '1667857051.jpg', 'culturel', '2022-11-08 00:42:27', '2022-11-07 23:42:27'),
(8, 'Mother\'s Day Celebration', 'Célébration  fête des mères', '<p>Sunday, May 8 from 3 p.m. to 6 p.m. at Welland City Hall. A beautiful celebration in honour of Niagara\'s immigrant moms. Poetry, songs, games, gifts and a great meal to share! Everyone is welcome!<br></p>', '<p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(97, 97, 97); font-family: Inter, sans-serif;\"><span style=\"font-size: 1rem;\">Le dimanche 8 mai de 15h (3 p.m.) à 18h (6 p.m.) à l\'hôtel de ville de Welland. Une belle&nbsp;</span><span style=\"font-size: 1rem; margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\">célébration en l’honneur des mamans immigrantes du Niagara. De la poésie, des chants,&nbsp;</span><span style=\"font-size: 1rem; margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\">des jeux, des cadeaux et un bon repas à partager ensemble! Bienvenue à toutes et à&nbsp;</span><span style=\"font-size: 1rem; margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\">tous !</span><br></p>', 'celebration-fete-des-meres', '1675202779.jpeg', 'social', '2023-01-31 21:06:19', '2023-01-31 21:06:19'),
(9, 'Story Teller', 'Au coin du feu', '<p>A cultural, artistic and socially entertaining event not to be missed this Thursday, May 12th at 7pm. Come and sit around our virtual fire and let Mr. Aimé Avolonto carry you away in one of his beautiful African tales.<br></p>', '<h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; font-weight: 700; position: relative; font-family: Roboto, sans-serif;\"><span style=\"color: rgb(97, 97, 97); font-family: var(--secondary_font); font-size: 1rem; font-weight: 400;\">Un rendez-vous culturel, artistique et socialement divertissant à ne pas rater ce jeudi 12 mai à 19h. Venez-vous asseoir autour de notre feu virtuel et laissez M. Aimé Avolonto vous emporter dans l\'un de ses beaux contes africains.&nbsp;</span><br></h5>', 'au-coin-du-feu', '1675203007.jpeg', 'culturel', '2023-01-31 21:10:07', '2023-01-31 21:10:07'),
(10, 'Our culture in our dishes', 'Notre culture dans nos mets', '<p>Do you know Widjila? Come discover this dish from northern Mali and the history behind it on Friday, May 20 at 7pm. Presentation in virtual mode by Kina Macinanké.<br></p>', '<p>Connaissez-vous le Widjila? Venez découvrir ce plat originaire du nord du Mali et l’histoire qui en découle vendredi 20 mai à 19h (7pm). Présentation en mode virtuel par Kina Macinanké.<br></p>', 'notre-culture-dans-nos-mets', '1675203203.jpeg', 'culturel', '2023-01-31 21:13:23', '2023-01-31 21:13:23'),
(12, 'Niagara Folk Arts Festival', 'Niagara Folk Arts Festival', '<h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; position: relative;\"><font color=\"#616161\" face=\"Roboto, sans-serif\"><span style=\"font-size: 16px;\">Open House. Saturday, June 11 at 4 p.m. at Immaculate Conception Parish Hall, 99 Garnet Street, St. Catharines.&nbsp;</span></font></h5><h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; position: relative;\"><font color=\"#616161\" face=\"Roboto, sans-serif\"><span style=\"font-size: 16px;\">Exotic cuisine by Yorly Balu</span></font></h5><h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; position: relative;\"><font color=\"#616161\" face=\"Roboto, sans-serif\"><span style=\"font-size: 16px;\">Folkloric animation: Justine Gogoua and Amadou Kienou</span></font></h5>', '<h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; position: relative;\"><font color=\"#616161\" face=\"Roboto, sans-serif\"><span style=\"font-size: 16px;\">Porte ouverte. Samedi 11 juin à 16h (4p.m.) à la salle paroissiale Immaculée Conception, 99, Garnet Street, St. Catharines.&nbsp;</span></font></h5><h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; position: relative;\"><font color=\"#616161\" face=\"Roboto, sans-serif\"><span style=\"font-size: 16px;\">Cuisine exotique de Yorly Balu</span></font></h5><h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; position: relative;\"><font color=\"#616161\" face=\"Roboto, sans-serif\"><span style=\"font-size: 16px;\">Animation folklorique :&nbsp; Justine Gogoua et Amadou Kienou</span></font></h5>', 'niagara-folk-arts-festival', '1675203677.jpeg', 'culturel', '2023-01-31 21:21:17', '2023-01-31 21:21:17'),
(13, 'Celebrate Canada Day', 'Le Canada en fête', '<p>On Friday, July 1st, Sofifran will celebrate Canada Day / Le Canada en fête&nbsp;<span style=\"font-size: 1rem;\">is organizing a large multicultural buffet that will take place at the Welland&nbsp;</span><span style=\"font-size: 1rem;\">Farmers #39;Market, address: 70 Young St, Welland, ON L3B 4C5, time at 3pm.</span></p>', '<p><span style=\"font-size: 1rem;\">Vendredi 1 er juillet célébrons Le Canada en fête / Canada day, pour l’occasion Sofifran&nbsp;</span><span style=\"font-size: 1rem;\">organise un grand buffet multiculturel qui aura lieu sur la place Welland&nbsp;</span><span style=\"font-size: 1rem;\">Farmers #39;Market, adresse : 70 Young St, Welland, ON L3B 4C5, heure à 15h (3pm).</span><br></p>', 'le-canada-en-fete', '1675204030.jpeg', 'culturel', '2023-01-31 21:27:10', '2023-01-31 21:27:10'),
(14, 'Multi\'arts summer camp 2022', 'Camp d\'été Multi\'arts 2022', '<p><span style=\"font-size: 1rem;\">The Multi\'arts summer camp is back, hurry up because places are limited!</span><br></p><p>Register your children at the following email address: info@sofifran.org</p>', '<p><span style=\"font-size: 1rem;\">Le camp d\'été Multi\'arts est de retour, hâtez-vous car les places sont limitées!!</span><br></p><p>Inscrivez vos enfants à l\'adresse courriel suivante : info@sofifran.org</p>', 'camp-dete-multiarts-2022', '1675204337.jpeg', 'culturel', '2023-01-31 21:32:18', '2023-01-31 21:32:18');
INSERT INTO `activites` (`id`, `title_en`, `title_fr`, `description_en`, `description_fr`, `slug`, `image`, `categorie_activity_slug`, `created_at`, `updated_at`) VALUES
(15, 'Sofifran\'s games', 'Les jeux de Sofifran', '<p>Let\'s start the month of August with a bang and have fun together!</p><p><span style=\"font-size: 1rem;\">Sofifran is organizing 2 great activities on August 1st:</span><br></p><p><span style=\"font-size: 1rem;\">* SOFIFRAN games for kids</span><br></p><p><span style=\"font-size: 1rem;\">* The annual BBQ and community potluck.</span><br></p><p><span style=\"font-size: 1rem;\">Come and join us!</span><br></p><p><span style=\"font-size: 1rem;\">When: Monday August 1st 2022</span><br></p><p><span style=\"font-size: 1rem;\">Where: Chippawa Park, 128 Fitch St, Welland, ON L3C 4V3</span><br></p><p>Time: 12pm</p><p><span style=\"font-size: 1rem;\">Everyone is welcome!</span></p>', '<h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; font-weight: 700; position: relative; font-family: Roboto, sans-serif;\"><span style=\"font-family: &quot;Times New Roman&quot;, serif; font-size: 16pt; color: rgb(97, 97, 97); font-weight: 400;\">Débutons le mois d’août en beauté et amusons-nous tous ensemble !</span><br></h5><div class=\"text\" style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: 32px; font-family: var(--secondary_font); color: rgb(97, 97, 97); position: relative;\"><p class=\"MsoNormal\" style=\"margin-right: 0px; margin-bottom: 0cm; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 16pt; line-height: inherit; font-family: &quot;Times New Roman&quot;, serif;\">Pour vous Sofifran organise 2 grandes activités le 1<span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 0.75em; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;\">er</span>&nbsp;août prochain&nbsp;:</span><span style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(34, 34, 34);\"><o:p style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></o:p></span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin-right: 0px; margin-bottom: 0cm; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit; text-indent: -18pt;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 16pt; line-height: inherit; font-family: &quot;Times New Roman&quot;, serif;\">*&nbsp; Les jeux de SOFIFRAN pour les jeunes</span><span style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(34, 34, 34);\"><o:p style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></o:p></span></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin-right: 0px; margin-bottom: 0cm; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit; text-indent: -18pt;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 16pt; line-height: inherit; font-family: &quot;Times New Roman&quot;, serif;\">*&nbsp; Le BBQ annuel et le potluck de la communauté.</span><span style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(34, 34, 34);\"><o:p style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></o:p></span></p><p class=\"MsoNormal\" style=\"margin-right: 0px; margin-bottom: 0cm; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 16pt; line-height: inherit; font-family: &quot;Times New Roman&quot;, serif;\">Venez nombreux !!</span><span style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(34, 34, 34);\"><o:p style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></o:p></span></p><p class=\"MsoNormal\" style=\"margin-right: 0px; margin-bottom: 0cm; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 16pt; line-height: inherit; font-family: &quot;Times New Roman&quot;, serif;\">Quand: lundi 1<span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 0.75em; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;\">er</span>&nbsp;août 2022</span><span style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(34, 34, 34);\"><o:p style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></o:p></span></p><p class=\"MsoNormal\" style=\"margin-right: 0px; margin-bottom: 0cm; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"><span lang=\"EN-CA\" style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 16pt; line-height: inherit; font-family: &quot;Times New Roman&quot;, serif;\">Lieu: Chippawa parc, 128 Fitch St, Welland, ON L3C 4V3</span><span lang=\"EN-CA\" style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(34, 34, 34);\"><o:p style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></o:p></span></p><p class=\"MsoNormal\" style=\"margin-right: 0px; margin-bottom: 0cm; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 16pt; line-height: inherit; font-family: &quot;Times New Roman&quot;, serif;\">Heure: à 12h</span><span style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(34, 34, 34);\"><o:p style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></o:p></span></p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></p><p class=\"MsoNormal\" style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 16pt; line-height: 22.8267px;\">Bienvenue à tous!</span></p></div>', 'les-jeux-de-sofifran', '1675204550.jpeg', 'social', '2023-01-31 21:35:50', '2023-01-31 21:35:50'),
(16, 'Our culture in our dishes', 'Notre culture dans nos mets', '<p>Why not accompany us virtually to Senegal, in Zeina Tall\'s kitchen on Thursday, October 27 at 7pm?&nbsp;</p><p><span style=\"font-size: 1rem;\">Together we will learn how to prepare, from Tchep to fish and discover its origin.</span><br></p>', '<div class=\"text\" style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: 32px; font-family: var(--secondary_font); color: rgb(97, 97, 97); position: relative;\"><p class=\"MsoNormal\" style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 18pt; padding: 0px; border: none; outline: none; line-height: inherit;\"><font color=\"#222222\" face=\"Bell MT, serif\" style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 21.3333px; line-height: inherit;\">Et si vous nous accompagniez virtuellement au Sénégal, dans la cuisine de Zeina Tall jeudi 27 octobre à 19h00 (7pm)?&nbsp;</span></font></p><p class=\"MsoNormal\" style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 18pt; padding: 0px; border: none; outline: none; line-height: inherit;\"><font color=\"#222222\" face=\"Bell MT, serif\" style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 21.3333px; line-height: inherit;\">Ensemble nous apprendrons à préparer, du Tchep au poisson et découvrirons son origine.&nbsp;</span></font></p></div>', 'notre-culture-dans-nos-mets', '1675204713.jpeg', 'culturel', '2023-01-31 21:38:33', '2023-01-31 21:38:33'),
(17, 'Our culture in our dishes', 'Notre culture dans nos mets', '<p><span style=\"font-size: 1rem;\">Let\'s meet on Sunday, January 29 at Holy Trinity Chuch in Welland to learn about the culture and traditional foods of the DRC at 2:00 pm.</span><br></p>', '<h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; font-weight: 700; position: relative; font-family: Roboto, sans-serif;\"><span style=\"color: rgb(97, 97, 97); font-family: var(--secondary_font); font-size: 1rem; font-weight: 400;\">Retrouvons-nous dimanche 29 janvier à Holy Trinity Chuch de Welland afin d\'apprendre la culture et les mets traditionnels du Congo RDC à 14h00.&nbsp;</span><br></h5>', 'notre-culture-dans-nos-mets', '1675204941.jpeg', 'culturel', '2023-01-31 21:42:21', '2023-01-31 21:42:21'),
(18, 'Festival Féstiv\'Ébène 16th edition!', 'Festival Féstiv\'Ébène 16e édition!!', '<p><span style=\"font-size: 1rem;\">The Féstiv\'Ébène Festival is back in person. Don\'t miss the 16th edition full of surprises!</span><br></p>', '<p><span style=\"font-size: 1rem;\">Le Festival Féstiv\'Ébène fait son grand retour en présentiel. Ne manquez pas la 16e édition pleine de surprises!!</span><br></p>', 'festival-festivebene-16e-edition', '1675205051.jpeg', 'culturel', '2023-01-31 21:44:11', '2023-01-31 21:44:11'),
(19, 'Féstiv\'Ébène Festival 16th edition!', 'Festival Féstiv\'Ébène 16e édition!!', '<p><span style=\"font-size: 1rem;\">The Festiv\'Ébène festival is back in person in Welland and you are all welcome!</span><br></p>', '<h5 style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; font-weight: 700; position: relative; font-family: Roboto, sans-serif;\"><span style=\"color: rgb(97, 97, 97); font-family: var(--secondary_font); font-size: 1rem; font-weight: 400;\">Le festival Festiv\'Ébène fait son grand retour en présentiel à Welland et vous êtes tous les bienvenus!!</span><br></h5>', 'festival-festivebene-16e-edition', '1675205241.jpeg', 'culturel', '2023-01-31 21:47:22', '2023-01-31 21:47:22'),
(20, 'PHOTOS VERNISSAGE / SPIRIT OF MALI', 'PHOTOS VERNISSAGE / SPIRIT OF MALI', 'On Saturday, February 4, Sofifran launched the first activity of the Festiv\'Ébène 2023 Festival with the opening of the exhibition \"Spirit of Mali\" by artist Stève Viès.<p></p><p>The event took place at the FirstOntario PAC facility in St. Catharines. This opening was the result of an excellent collaboration between Sofifran, the University and FirstOntario PAC.Sofifran would like to thank the Ontario Arts Council, Canadian Heritage, Le Centre communautaire le Griffon and its financial and community partners for making this event possible.</p>', '<div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><div>Le samedi 4 février dernier, Sofifran a lancé la première activité du Festival Festiv\'Ébène 2023 par le vernissage de l\'exposition \"Spirit of Mali\" de l\'artiste Stève Viès.L\'événement a eu lieu dans les installations du FirstOntario PAC à St. Catharines. Ce vernissage est le fruit d\'une excellente collaboration entre Sofifran, l\'Université et le FirstOntario PAC.Sofifran le Conseil des arts de l\'Ontario, Patrimoine Canadien, Le Centre communautaire le Griffon ainsi que ses partenaires financiers et communautaires grâce à qui cet événement a pu avoir lieu.</div></div>', 'photos-vernissage-spirit-of-mali', '1675886810.jpg', 'culturel', '2023-02-08 20:29:57', '2023-02-08 19:29:57'),
(21, 'Soirée Festiv\'Ebène', 'Soirée Festiv\'Ebène', '<p>Event Sofifran - 25 Fevrier 2023<br></p>', '<p>Événement Sofifran - 25 Fevrier 2023<br></p>', 'soiree-festivebene', '1677605980.jpg', 'culturel', '2023-03-01 20:07:42', '2023-03-01 19:07:42'),
(22, 'Learning project', 'Projet apprentissage', '<p>As part of our Appren\'TISSAGE project in collaboration with SOFIFRAN and the Viamonde School Board, we have experienced several activities that bring our schools together in order to create a sense of belonging to our diverse community. We hosted DJing workshops at École l\'Héritage, LaMarsh and Franco-Niagara Secondary and had our little ones dance at Franco-Niagara Elementary. Then, we organized several projects for Black History Month such as a multicultural meal, a traditional dress parade, an African storytelling animated by Fété Kimpiobi from SOFIFRAN, the participation of the Franco-Niagara High School Music Band at the annual Festiv\'Ébène organized by SOFIFRAN.</p><p><br></p><p>In addition, as part of Autism Awareness Month, we received a performance by the artist Vincent Bishop from Franco-Niagara Elementary and Nouvel Horizon schools. Vincent spoke about his challenges as an Asperger\'s person and showed us his talents as a multi-instrumentalist. Not to mention the grade 10 students who were invited to a French competition at Brock University in St. Catharines in order to create links with other schools in the region. We would like to thank the Vice Versa micro grant for allowing us to experience all these incredible gatherings as part of our project.</p>', '<p>Dans le cadre de notre projet Appren’TISSAGE en collaboration avec l’organisme SOFIFRAN et le Conseil scolaire Viamonde, nous avons vécu plusieurs activités regroupant nos écoles dans le but de créer des liens et un sentiment d’appartenance à notre communauté diversifiée. Nous avons reçu des ateliers de DJing à l’école l’Héritage, LaMarsh et Franco-Niagara secondaire et avons fait danser nos petits du côté Franco-Niagara Élémentaire. Ensuite, nous avons organisé plusieurs projets dans le cadre du mois de l’histoire des noirs comme un repas multiculturel, une parade d’habits traditionnels, un conte africain animé par Fété Kimpiobi de SOFIFRAN, la participation du Band de musique de l’école secondaire Franco-Niagara au Festiv’Ébène organisé annuellement par SOFIFRAN.</p><p><br></p><p>De plus, dans le cadre du mois de la sensibilisation au Trouble du Spectre de l’Autisme, nous avons reçu un pour l’école Franco-Niagara élémentaire et l’école Nouvel Horizon un spectacle de l’artiste Vincent Bishop qui nous a parlé de ses défis en tant qu’Asperger et nous a montré ses talents de multi-instrumentiste. Sans oublier les élèves de 10e année qui ont été invité à un concours de Français à l’université de Brock à St. Catharines dans le but de créer des liens avec les autres écoles de la région. On remercie la micro-subvention Vice Versa de nous avoir permis de vivre tous ces rassemblements incroyables dans le cadre de notre projet.</p>', 'projet-apprentissage', '1683657483.jpg', 'culturel', '2023-05-09 18:38:03', '2023-05-09 16:38:03'),
(23, 'Project ART\'ificie - Micro-subvention Passep\'ART', 'Projet ART\'ificie - Micro-subvention Passep\'ART', '<p>As part of our \"ART\'ifice\" project, in collaboration with SOFIFRAN and the Viamonde School Board, we enjoyed a number of activities that brought our schools together to create links and a sense of belonging to our diverse community. We hosted street dance workshops at Nouvel Horizon, LaMarsh and Franco-Niagara elementary and secondary schools. In addition, our young people from LaMarsh Elementary and Franco-Niagara Secondary participated in the \"MONDE LE SON! We also organized a number of projects as part of the \"MONDE LE SON!</p><p><br></p><p>And as part of the project, we organized a day-long gathering to celebrate all our efforts, inviting Bill Bestiole - Les créatures du Jurassique to perform. And let\'s not forget the students from grades 1 to 8 who were invited to help organize this country fair on June 1 from the following schools É.É. LaMarsh, É.É. L\'Héritage, É.É. Nouvel Horizon, É.É. Franco-Niagara and É.S. Franco-Niagara. We\'d like to thank the Passep\'ART microgrant for making it possible for us to experience all these incredible gatherings as part of our ART\'ifice project.</p>', '<p>Dans le cadre de notre projet « ART’ifice » en collaboration avec l’organisme SOFIFRAN et le Conseil scolaire Viamonde, nous avons vécu plusieurs activités regroupant nos écoles dans le but de créer des liens et un sentiment d’appartenance à notre communauté diversifiée. Nous avons reçu des ateliers de danse de rue à l’école Nouvel Horizon, LaMarsh et Franco-Niagara élémentaire et secondaire. De plus, nous avons fait participer nos jeunes de l’école élémentaire LaMarsh et Franco-Niagara secondaire au festival de musique « MONDE LE SON! ». Ensuite, nous avons organisé plusieurs projets dans le cadre</p><p>De plus, dans le cadre du projet, nous avons organisé une journée de rassemblement pour célébrer tous nos efforts en y invitant le spectacle de Bill Bestiole – Les créatures du Jurassique . Sans oublier les élèves de 1ère&nbsp; à 8e année qui ont été invité à aider à l’organisation de cette fête champêtre le 1 juin dernier des écoles suivantes É.É. LaMarsh, É.É. L’Héritage, É.É. Nouvel Horizon, É.É. Franco-Niagara et É.S. Franco-Niagara. On remercie la micro-subvention Passep’ART de nous avoir permis de vivre toutes ces rassemblements incroyables dans le cadre de notre projet ART’ifice.</p>', 'projet-artificie-micro-subvention-passepart', '1686069376.jpg', 'educatif', '2023-06-06 14:36:16', '2023-06-06 14:36:16'),
(26, 'Canada Day', 'Journée du Canada', '<p>Canada Day</p>', 'La journée du Canada', 'journee-du-canada', '1688662098.png', 'culturel', '2023-07-06 14:48:19', '2023-07-06 14:48:19'),
(29, 'african doughnut recipe demonstration', 'Démonstration de recettes du beignet Africain', '<p>We\'re delighted to announce our first hands-on African doughnut recipe session with registered participants. The event will take place on Saturday March 16 at 3pm in the Holy Trinity Church kitchens, located at 77 Division Street, Welland.</p><p><span style=\"font-size: 1rem;\">We look forward to sharing this experience and tasting African doughnuts of various origins with you.</span><br></p>', '<p>Nous avons le plaisir de vous annoncer notre première séance pratique de recettes du beignet Africain avec les participantes inscrites. l\'événement aura lieu le samedi 16 mars à 15h dans les cuisines Holy Trinity Church, situé au 77 Division Street, Welland.</p><p>Nous sommes impatients de partager cette expérience&nbsp; et déguster&nbsp; les beignets Africains de diverses origines avec vous.</p>', 'demonstration-de-recettes-du-beignet-africain', '1712326777.jpg', 'culturel', '2024-04-05 14:19:37', '2024-04-05 12:19:37'),
(30, 'Festiv\'Ébène 2024 evening', 'Soirée Festiv\'Ébène 2024', '<p>Festiv\'Ébène 2024 evening<br></p>', '<p>Soirée Festiv\'Ébène 2024<br></p>', 'soiree-festivebene-2024', '1712595971.jpg', 'culturel', '2024-04-08 15:06:13', '2024-04-08 15:06:13'),
(31, 'A look back at the Niagara Folk Arts Festival', 'Retour sur le Festival des arts folkloriques du Niagara', '<p>The 56th edition of the Niagara Folk Arts Festival took place from May 2 to 26 in the region\'s various cultural clubs. As tradition demands, the first activity before the multicultural open house was the Ambassadors\' Ball, hosted this year by Club Italia.</p><p><br></p><p>This was an opportunity for visitors to sample the culinary riches of each community, as well as enjoy a variety of performances. The mistress of ceremonies was Melinda Chartrand, vice-president of the Folk Arts multicultural center.</p><p><br></p><p>For Niagara\'s francophones, two open houses were planned. First, on May 18, at Immaculée-Conception parish in St. Catharines, Sofifran welcomed the community to a celebration of Afro-Canadian culture, featuring Senegalese, Congolese and Caribbean cuisine, set to the frenzied rhythms of Amadou Kiénou\'s djembes.</p><p><br></p><p>\"Representatives of various cultures visited Sofifran\'s representative, Amour Samanga, from the Democratic Republic of Congo. There were a few fewer ambassadors this year, fewer cultural clubs, but we\'re very pleased with the public turnout. Over 150 people came and all the food went. A great success!” exclaims Sofifran founder and general manager Fété Ngira-Batware Kimpiobi.</p><p><br></p><p>The food was prepared by Congolese chefs Élodie Kionguisa and Grace Nyamzaka. There was also Senegalese cuisine</p><p><br></p><p>Translated with DeepL.com (free version)</p>', '<p>La 56e édition du Festival des arts folkloriques du Niagara s’est déroulée du 2 au 26 mai dans les différents clubs culturels de la région. Comme la tradition l’exige, la première activité avant les portes ouvertes multiculturelles est le Bal des ambassadeurs dont l’hôte cette année était le Club Italia.</p><p><br></p><p>C’était l’occasion pour les visiteurs de déguster les richesses culinaires de chaque communauté en plus d’assister à divers spectacles. La maîtresse de cérémonie était Melinda Chartrand vice-présidente du centre multiculturel Folk Arts.</p><p><br></p><p>Pour les francophones du Niagara, deux portes ouvertes étaient prévues. D’abord le 18 mai, à la paroisse Immaculée-Conception de St. Catharines Sofifran accueillait la communauté pour une célébration de la culture afro-canadienne avec de la cuisine sénégalaise, congolaise et caribéenne sur les rythmes endiablés des djembés de l’artiste Amadou Kiénou.</p><p><br></p><p>« Les représentants des diverses cultures ont rendu visite à la représentante de Sofifran, Amour Samanga, originaire de la République démocratique du Congo. Il y avait un peu moins d’ambassadeurs cette année, moins de clubs culturels mais nous sommes très contents de la participation du public. Plus de 150 personnes sont venues et toute la nourriture est partie. Un vif succès! », s’exclame la fondatrice et directrice générale de Sofifran, Fété Ngira-Batware Kimpiobi.</p><p><br></p><p>Les mets offerts étaient cuisinés par les Congolaises Élodie Kionguisa et Grace Nyamzaka. Il y avait également la cuisine sénégalaise de Khadi Diop.</p><p><br></p><p>« Pour cet événement, Le Griffon qui a fourni le système de son et la technique. Nous avons eu comme d’habitude une vente d’objets d’art africains et un décor. Les visiteurs ont testé deux courants de saveurs africaines avec des épices totalement différentes. Les plats sont similaires mais les recettes ne le sont pas. Au contraire, les visiteurs ont adoré! », conclut Mme Kimpiobi.</p><p><br></p><p>L’autre événement francophone a eu lieu au Club LaSalle de St. Catharines pour une soirée festive en français. Au menu : repas traditionnel canadien-français avec fèves au lard, tourtières et boulettes de viande, danses traditionnelles et sets carrés avec Denis Simoneau et Simon Hauber au violon, ainsi que l’orchestre de Gilles Groleau et ses invités, Carole Anderson, Micheline Hauber, Enrico M. Schirru à la basse et Jim Hobarts à la batterie.</p><p><br></p><p>Les ambassadeurs des clubs philippin, allemand, slovaque, arménien et polonais ont rendu visite à l’ambassadrice du Club LaSalle et hôtesse de cette soirée, Gabriella Foster. En plus de déguster des mets canadiens-français, ils ont joué de la cuillère et fait danser des petits « gigueux » en bois avec la complicité de Denis Simoneau. Une expérience qu’ils ont grandement appréciée.</p><p><br></p><p>Plus de 240 personnes ont participé à cette traditionnelle soirée où la francophonie partage sa culture. Un franc succès!</p><p><br></p><p>Photo : Amadou Kiénou et ses musiciens ont fait danser les visiteurs à la porte ouverte de Sofifran.</p>', 'retour-sur-le-festival-des-arts-folkloriques-du-niagara', '1717691603.jpeg', 'culturel', '2024-06-06 14:33:24', '2024-06-06 14:33:24'),
(32, 'Final report of project Vice Versa / D52541 École élémentaire LaMarsh', 'Rapport final de projet Vice Versa / D52541 École élémentaire LaMarsh', '<p><span style=\"font-size: 1rem;\">To promote student leadership, the students created a long-term project on general wellness and social justice. The school welcomed experts in the field of mental health, anti-racism awareness offered in French by The Get Real Movement inc. This workshop gave students the chance to increase their ability to identify, unlearn and combat racial prejudice and discrimination through dance and conversations that were encouraged by the artist.&nbsp; In addition, students had the chance to talk about topics such as bullying, the LGBTQAI2+S community and develop their knowledge on various subjects.</span></p><p>This project was created in collaboration with the SOFIFRAN organization, the Viamonde school board and thanks to the Vice Versa grant.</p><p>Translated with DeepL.com (free version)</p>', '<p><span style=\"font-size: 1rem;\">Dans le but de promouvoir le leadership des élèves, les élèves ont créé un projet à long terme sur le mieux-être général en lien avec la justice social. L\'école a reçu des experts dans le domaine de la santé mentale, de sensibilisation contre le racisme offert en français de The Get Real Movement inc. Cet atelier a donné la chance aux élèves d’augmenter leur capacité à identifier, désapprendre et combattre les préjugés raciaux et la discrimination au travers de la danse et des conversations qui ont été encourues par l’artiste.&nbsp; De plus, les élèves ont eu la chance de parler des sujets comme l\'intimidation, la communauté LGBTQAI2+S et développer leurs connaissances sur divers sujets.</span></p><p>Ce projet a été créé en collaboration avec l’organisme SOFIFRAN, le conseil scolaire Viamonde et grâce à la subvention Vice Versa.</p>', 'rapport-final-de-projet-vice-versa-d52541-ecole-elementaire-lamarsh', '1718106110.jpg', 'educatif', '2024-06-11 12:18:39', '2024-06-11 10:18:39'),
(33, 'Félicitations aux diplômés de l\'école Sacré-Cœur de Welland', 'Félicitations aux diplômés de l\'école Sacré-Cœur de Welland', '<p>Le 17 juin, nous avons eu l\'honneur de participer à la cérémonie de graduation des élèves de l\'école Sacré-Cœur de Welland. Josette Aubourg-Valcourt, notre dévouée coordinatrice de programme, a représenté SOFIFRAN lors de cet événement mémorable.&nbsp;</p><p>Nous sommes fiers d\'avoir offert une bourse à un(e) étudiant(e) méritant(e), soulignant notre engagement envers l\'éducation et le soutien de la jeunesse.</p><div>Félicitations à tous les diplômés et à leur avenir prometteur !</div>', '<p>Le 17 juin, nous avons eu l\'honneur de participer à la cérémonie de graduation des élèves de l\'école Sacré-Cœur de Welland. Josette Aubourg-Valcourt, notre dévouée coordinatrice de programme, a représenté SOFIFRAN lors de cet événement mémorable.&nbsp;</p><p>Nous sommes fiers d\'avoir offert une bourse à un(e) étudiant(e) méritant(e), soulignant notre engagement envers l\'éducation et le soutien de la jeunesse.</p><div>Félicitations à tous les diplômés et à leur avenir prometteur !<br></div>', 'felicitations-aux-diplomes-de-lecole-sacre-coeur-de-welland', '1718723140.jpg', 'educatif', '2024-06-18 15:29:45', '2024-06-18 13:29:45'),
(34, 'Sofifran Canada 2024', 'Sofifran Canada 2024', '<p>SOFIFRAN celebrates Canada Day 2024: a moment of sharing and community pride</p><p>On July 1, 2024, SOFIFRAN celebrated Canada Day alongside Francophone and Francophile families in the Niagara region. Under sunny skies and in a festive atmosphere, the day was marked by cultural, artistic, and community activities that brought young and old together around the values that make our country so rich: diversity, solidarity, and inclusion.</p><p>From music and traditional dances to children\'s games and food tastings, every moment illustrated the vitality and creativity of the Francophone community. SOFIFRAN volunteers and partners helped create a friendly atmosphere where you could feel the pride of belonging to an open and diverse society.</p><p>This celebration was also an opportunity for SOFIFRAN to reaffirm its commitment to promoting the integration, development, and full participation of Francophone women and families in Canadian society.</p><p>Canada Day with SOFIFRAN is much more than just an event: it is a meeting of cultures, an affirmation of our Francophone identity, and a celebration of living together.</p>', '<p>SOFIFRAN célèbre la Fête du Canada 2024 : un moment de partage et de fierté communautaire</p><p>Le 1er juillet 2024, SOFIFRAN a célébré la Fête du Canada aux côtés des familles francophones et francophiles de la région du Niagara. Sous un ciel radieux et dans une ambiance festive, la journée a été marquée par des activités culturelles, artistiques et communautaires rassemblant petits et grands autour des valeurs qui font la richesse du pays : diversité, solidarité et inclusion.</p><p>De la musique aux danses traditionnelles, en passant par des jeux pour enfants et des dégustations de mets variés, chaque moment a illustré la vitalité et la créativité de la communauté francophone. Les bénévoles et partenaires de SOFIFRAN ont contribué à créer une atmosphère conviviale où l’on pouvait sentir la fierté d’appartenir à une société ouverte et plurielle.</p><p>Cette célébration fut aussi l’occasion pour SOFIFRAN de rappeler son engagement à favoriser l’intégration, l’épanouissement et la pleine participation des femmes et des familles francophones dans la société canadienne.</p><p>La Fête du Canada avec SOFIFRAN, c’est bien plus qu’un simple événement : c’est une rencontre des cultures, une affirmation de notre identité francophone et une célébration du vivre-ensemble.</p>', 'sofifran-canada-2024', '1720026413.jpg', 'social', '2025-10-17 11:45:37', '2025-10-17 11:45:37'),
(35, 'Sofifran ( FESTIV\'EBENE )', 'Sofifran ( FESTIV\'EBENE )', '<p><span style=\"color: rgb(17, 17, 17); font-family: Roboto, sans-serif; font-size: 18px; white-space-collapse: preserve; background-color: rgb(247, 247, 247);\">Sofifran at the Festiv\'Ebene</span></p>', '<p>Sofifran Au Festiv\'Ebene</p>', 'sofifran-festivebene', '1739191763.jpg', 'culturel', '2025-05-17 21:17:14', '2025-05-17 21:17:14'),
(36, 'Safran 2025', 'Safran 2025', '<p>Safran 2025</p>', '<p><span style=\"color: rgb(97, 97, 97); font-family: Inter, sans-serif;\">Safran 2025</span></p>', 'safran-2025', '1743183148.jpg', 'educatif', '2025-05-17 21:18:25', '2025-05-17 21:18:25'),
(37, 'Heartfelt congratulations, Birthday Mom!', 'Félicitations de tout cœur, Maman Fété !', '<p>It is with immense joy and pride that we celebrate Ms. Fété Ngira-Batware Kimpiobi, our Executive Director, honored with the prestigious King Charles III Coronation Medal during an official ceremony held on May 6 in Toronto. This distinction, presented by the Lieutenant Governor of Ontario and administered by the Chancellery of Honours at Rideau Hall, recognizes her exceptional commitment to her peers, her community, Ontario, and Canada.</p>', '<p>C’est avec une immense joie et beaucoup de fierté que nous célébrons Mme Fété Ngira-Batware Kimpiobi, notre Directrice générale, honorée de la prestigieuse Médaille du Couronnement du Roi Charles III lors d’une cérémonie officielle tenue le 6 mai à Toronto. Cette distinction, remise par la Lieutenante-Gouverneure de l’Ontario et administrée par la Chancellerie des distinctions honorifiques à Rideau Hall, souligne son engagement exceptionnel envers ses pairs, sa communauté, l’Ontario et le Canada.</p>', 'felicitations-de-tout-coeur-maman-fete', '1746726600.png', 'social', '2025-05-08 17:50:01', '2025-05-08 17:50:01'),
(38, 'FDM 2025', 'FDM 2025', '<p>FDM 2025&nbsp;</p>', '<p>FDM 2025</p>', 'fdm-2025', '1747653321.png', 'social', '2025-05-19 11:21:27', '2025-05-19 11:21:27'),
(39, 'Sofifran Open Door 2025', 'Sofifran Porte Ouverte 2025', '<p><span style=\"color: rgb(17, 17, 17); font-family: Roboto, sans-serif; font-size: 18px; white-space-collapse: preserve; background-color: rgb(247, 247, 247);\">The Open Doors of Sofifran</span></p>', 'Les portes Ouvertes de Sofifran', 'sofifran-porte-ouverte-2025', '1750342862.jpg', 'social', '2025-06-19 14:21:02', '2025-06-19 14:21:02'),
(40, 'Canadian Multiculturalism Day 2025', 'La Journée Canadienne du multiculturalisme 2025', '<p>Canadian Multiculturalism Day 2025</p>', '<p>La Journée Canadienne du multiculturalisme 2025</p>', 'la-journee-canadienne-du-multiculturalisme-2025', '1753199209.JPG', 'culturel', '2025-07-22 17:00:34', '2025-07-22 17:00:34'),
(41, '50 years of the Franco-Ontarian flag: a colorful celebration!', '50 ans du drapeau franco-ontarien : une célébration haute en couleurs !', '<p>50 Years of the Franco-Ontarian Flag: A Colorful Celebration!</p><p><br></p><p>On September 25, 2025, the Francophonie of Welland, St. Catharines, and the surrounding area celebrated the 50th anniversary of the Franco-Ontarian flag in style. In a whirlwind of green and white, all schools—from daycare to high school—as well as numerous Francophone organizations, including SOFIFRAN, came together to bring the Franco-Ontarian spirit to life.</p><p><br></p><p>The day continued with a festive afternoon at Sacré-Cœur Church in Welland, marked by songs, dances, and testimonies filled with emotion and pride. This moment of communion served as a reminder that the Francophonie in Ontario is not just a story to be told, but a living reality, driven by the energy of young people and the determination of an entire community.</p><p><br></p><p>As an organization committed to the promotion and vitality of the Francophonie, SOFIFRAN is proud to have taken part in this historic celebration and to continue to promote the French language and culture through its programs, events, and community partnerships.</p><p><br></p><p>Proud of our roots. United in diversity. Together, let\'s keep the green and white flying!</p>', '<p>50 ans du drapeau franco-ontarien : une célébration haute en couleurs !&nbsp;</p><p><br></p><p>Le 25 septembre 2025, la francophonie de Welland, St. Catharines et des environs a célébré avec éclat le 50e anniversaire du drapeau franco-ontarien. Dans un tourbillon de vert et de blanc, toutes les écoles – de la garderie au secondaire – ainsi que de nombreux organismes francophones, dont SOFIFRAN, se sont rassemblés pour faire vibrer l’esprit franco-ontarien.</p><p><br></p><p>La journée s’est poursuivie par un après-midi festif à l’église Sacré-Cœur de Welland, marqué par des chants, des danses et des témoignages remplis d’émotion et de fierté. Ce moment de communion a rappelé que la francophonie en Ontario n’est pas seulement une histoire à raconter, mais une réalité vivante, portée par l’énergie des jeunes et la détermination de toute une communauté.</p><p><br></p><p>En tant qu’organisme engagé dans la promotion et la vitalité de la francophonie, SOFIFRAN est fière d’avoir pris part à cette célébration historique et de continuer à faire rayonner la langue et la culture françaises à travers ses programmes, ses événements et ses partenariats communautaires.</p><p><br></p><p>&nbsp;Fiers de nos racines. Unis dans la diversité. Ensemble, continuons de faire flotter le vert et le blanc !&nbsp;</p><div><br></div>', '50-ans-du-drapeau-franco-ontarien-une-celebration-haute-en-couleurs', '1760533271_68ef9b1727242.jpg', 'autre', '2025-10-15 13:01:11', '2025-10-15 13:01:11'),
(42, 'Canadian Multiculturalism Day at the Welland', 'Journée canadienne du multiculturalisme au marché de Welland', 'On June 29, 2025, SOFIFRAN celebrated Canadian Multiculturalism Day at the Welland Market in a friendly and festive atmosphere. Several hundred people, including Welland City Councilor Sharmila Setaram, gathered around a large buffet featuring flavors from around the world: weighed bananas from Haiti, kofta from Sudan, grilled chicken from Palestine, kapsa from the Middle East, koshari from Egypt, cassava leaves, and tilapia from Africa.The day ended with music from Toronto band Cloclo Claudel, offering the community a moment of joy and fellowship. Don\'t miss next year\'s edition!', 'Le 29 juin 2025, SOFIFRAN a célébré la Journée canadienne du multiculturalisme au marché de Welland, dans une ambiance conviviale et festive. Plusieurs centaines de personnes dont la conseillère municipale de Welland Sharmila Setaram, se sont rassemblées autour d’un grand buffet aux saveurs du monde : bananes pesées d’Haïti, kofta du Soudan, poulet grillé de Palestine, kapsa du Moyen-Orient, koshari d’Égypte, feuilles de manioc et tilapia d’Afrique.La journée s’est terminée en musique avec le groupe Cloclo Claudel de Toronto, offrant à la communauté un instant de joie et de fraternité. Ne ratez pas l\'édition de l\'année prochaine!', 'journee-canadienne-du-multiculturalisme-au-marche-de-welland', '1760700116_68f226d4c2777.png', 'social', '2025-10-17 11:25:36', '2025-10-17 11:25:36'),
(43, 'Review of the activity on November 2, 2025 National Francophone Immigration Week 2025', 'Retour sur l\'activité du 2 novembre 2025 Semaine nationale de l’immigration francophone 2025', '<p style=\"margin-bottom: 12px; color: rgb(102, 102, 102); line-height: 1.8; font-size: 15px; font-family: &quot;Open Sans&quot;, sans-serif;\">Niagara celebrates Francophone diversity!</p><p style=\"margin-bottom: 12px; color: rgb(102, 102, 102); line-height: 1.8; font-size: 15px; font-family: &quot;Open Sans&quot;, sans-serif;\">The Niagara Local Francophone Immigration Committee supported the event organized by SOFIFRAN at Welland City Hall as part of the 13th edition of National Francophone Immigration Week, themed “Thank you for enriching our Francophonie.”</p><p style=\"margin-bottom: 12px; color: rgb(102, 102, 102); line-height: 1.8; font-size: 15px; font-family: &quot;Open Sans&quot;, sans-serif;\">This meeting provided an opportunity to present the progress of the Canal Sofifran project, a French-language community television channel currently under development. This project, made possible thanks to $95,800 in funding from the Ontario Trillium Foundation, aims to provide a media space dedicated to cultural diversity and Francophone inclusion in the Niagara region. Canal Sofifran: a new voice for the Francophonie in action!</p>', '<p><span style=\"color: rgb(102, 102, 102); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 15px;\">Niagara célèbre la diversité francophone!</span><br style=\"color: rgb(102, 102, 102); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 15px;\"><span style=\"color: rgb(102, 102, 102); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 15px;\">Le Comité local en immigration francophone de Niagara a soutenu l’événement organisé par SOFIFRAN au City Hall de Welland, dans le cadre de la 13e édition de la Semaine nationale de l’immigration francophone, placée sous le thème « Merci d’enrichir notre francophonie ».</span><br style=\"color: rgb(102, 102, 102); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 15px;\"><span style=\"color: rgb(102, 102, 102); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 15px;\">Cette rencontre a permis de présenter les progrès du projet Canal Sofifran, une chaîne de télévision communautaire francophone en développement. Ce projet, rendu possible grâce au financement de 95 800 $ de la Fondation Trillium de l’Ontario, vise à offrir un espace médiatique dédié à la diversité culturelle et à l’inclusion francophone dans la région de Niagara.Canal Sofifran : une nouvelle voix pour la francophonie en action!</span></p>', 'retour-sur-lactivite-du-2-novembre-2025-semaine-nationale-de-limmigration-francophone-2025', '1763567941_691de9458acdf.jpg', 'culturel', '2025-11-19 15:59:01', '2025-11-19 15:59:01'),
(44, 'Exposition', 'Exposition', '<p>Some photos of the exhibition taken this<br>morning at Saint Jean de Brebeuf Catholic High School in Welland with Professor Amadou Ba.</p><p><br></p>', '<p>Quelques photos de l’exposition prises ce<br>Matin à l’école secondaire catholique Saint Jean de Brebeuf de Welland avec Le professeur Amadou Ba</p>', 'exposition', '1770450562_6986ee8288c5e.jpeg', 'educatif', '2026-02-07 07:49:22', '2026-02-07 07:49:22'),
(45, 'La soirée Cinéma Frantz Fanon du 13 février', 'La soirée Cinéma Frantz Fanon du 13 février', '<p>La soirée Cinéma Frantz Fanon du 13 février</p>', '<p>La soirée Cinéma Frantz Fanon du 13 février</p>', 'la-soiree-cinema-frantz-fanon-du-13-fevrier', '1771791024_699b62b0efac9.jpg', 'culturel', '2026-02-22 20:10:25', '2026-02-22 20:10:25'),
(46, 'Festival Festiv’Ebene 2026', 'Festival Festiv’Ebène 2026', '<p>The 2026 Festiv’Ébène Festival, organized by SOFIFRAN, will be held from February 5 to 28, 2026, in the Niagara region (Welland/St. Catharines) under the theme “Roots and Resonances.”</p><p>This event highlights Afro-descendant cultures, the French-speaking world, and the history of Black communities through presentations, films, and a gala evening. This event highlights African-descendant cultures, Francophone culture, and the history of Black communities through presentations, films, and a gala evening.</p><br><p>Highlights of the 2026 Program:</p><p>    <b>Theme</b>: “Roots and Resonances,” focusing on history, memory, and diversity.<br><b>Dates</b>: February 5-28, 2026.<br><b>Activities</b>: Days of presentations, discussions, films, and a gala of excellence.<br><b>Location</b>: Niagara Region (Welland &amp; St. Catharines).<br><b>Gala Evening</b>: Marked by the 19th edition, held on Saturday, February 28.</p><p>This festival aims to celebrate Black History Month.</p><p><br></p>', '<p><div data-subtree=\"aimfl,mfl\" style=\"display: contents\" data-sfc-cb=\"\" data-processed=\"true\">Festival Festiv’Ébène 2026, organisé par </div>SOFIFRAN,\r\n se tient du 5 au 28 février 2026 dans la région du Niagara (Welland/St.\r\n Catharines) sous le thème « Racines et Résonances ». Cet événement met \r\nen lumière les cultures afrodescendantes, la francophonie et l\'histoire \r\ndes communautés noires via des exposés, du cinéma et une soirée de gala.</p><p><strong class=\"Yjhzub\" data-sfc-cb=\"\" data-processed=\"true\">Points Forts de la Programmation 2026 :</strong><span class=\"txxDge notranslate\" data-wiz-uids=\"sZxn4d_k,sZxn4d_l\" data-sfc-cb=\"\" data-processed=\"true\"><span class=\"vKEkVd\" data-animation-atomic=\"\" data-wiz-attrbind=\"class=sZxn4d_j/TKHnVd\" data-processed=\"true\"><span aria-hidden=\"true\" data-processed=\"true\"></span></span></span></p><div class=\"Y3BBE\" data-sfc-cp=\"\" data-sfc-cb=\"\" data-hveid=\"CAIQAA\" data-processed=\"true\"><span class=\"txxDge notranslate\" data-wiz-uids=\"sZxn4d_k,sZxn4d_l\" data-sfc-cb=\"\" data-processed=\"true\"></span></div><ul class=\"KsbFXc U6u95\" data-sfc-cb=\"\" data-processed=\"true\"><li class=\"dF3vjf\" data-sfc-cb=\"\" data-hveid=\"CAMQAA\" data-processed=\"true\"><span class=\"T286Pc\" data-sfc-cp=\"\" data-sfc-cb=\"\" data-processed=\"true\"><strong class=\"Yjhzub\" data-sfc-cb=\"\" data-processed=\"true\">Thème :</strong> « Racines et Résonances », axé sur l\'histoire, la mémoire et la diversité.</span></li><li class=\"dF3vjf\" data-sfc-cb=\"\" data-hveid=\"CAMQAQ\" data-processed=\"true\"><span class=\"T286Pc\" data-sfc-cp=\"\" data-sfc-cb=\"\" data-processed=\"true\"><strong class=\"Yjhzub\" data-sfc-cb=\"\" data-processed=\"true\">Dates :</strong> Du 5 au 28 février 2026.</span></li><li class=\"dF3vjf\" data-sfc-cb=\"\" data-hveid=\"CAMQAg\" data-processed=\"true\"><span class=\"T286Pc\" data-sfc-cp=\"\" data-sfc-cb=\"\" data-processed=\"true\"><strong class=\"Yjhzub\" data-sfc-cb=\"\" data-processed=\"true\">Activités :</strong> Journées d\'exposés, échanges, cinéma et un gala d\'excellence.</span></li><li class=\"dF3vjf\" data-sfc-cb=\"\" data-hveid=\"CAMQAw\" data-processed=\"true\"><span class=\"T286Pc\" data-sfc-cp=\"\" data-sfc-cb=\"\" data-processed=\"true\"><strong class=\"Yjhzub\" data-sfc-cb=\"\" data-processed=\"true\">Lieu :</strong> Région du Niagara (Welland &amp; St. Catharines).</span></li><li class=\"dF3vjf\" data-sfc-cb=\"\" data-hveid=\"CAMQBA\" data-processed=\"true\"><span class=\"T286Pc\" data-sfc-cp=\"\" data-sfc-cb=\"\" data-processed=\"true\"><strong class=\"Yjhzub\" data-sfc-cb=\"\" data-processed=\"true\">Soirée de Gala :</strong> Marquée par la 19e édition, tenue le samedi 28 février.</span><span class=\"uJ19be notranslate\" data-wiz-uids=\"sZxn4d_13,sZxn4d_14\" data-sfc-cb=\"\" data-processed=\"true\"><span class=\"vKEkVd\" data-animation-atomic=\"\" data-wiz-attrbind=\"class=sZxn4d_12/TKHnVd\" data-processed=\"true\"><span aria-hidden=\"true\" data-processed=\"true\">&nbsp;</span></span></span></li></ul><ul class=\"KsbFXc U6u95\" data-sfc-cb=\"\" data-processed=\"true\"><li class=\"dF3vjf\" data-sfc-cb=\"\" data-hveid=\"CAMQBA\" data-processed=\"true\"><span class=\"uJ19be notranslate\" data-wiz-uids=\"sZxn4d_13,sZxn4d_14\" data-sfc-cb=\"\" data-processed=\"true\"></span><br></li></ul><div class=\"Y3BBE\" data-sfc-cp=\"\" data-sfc-cb=\"\" data-hveid=\"CAQQAA\" data-processed=\"true\">Ce festival vise à célébrer le Mois de l\'histoire des Noirs</div><p><p><br></p></p>', 'festival-festivebene-2026', '1772916436_69ac8ed440fa9.jpg', 'culturel', '2026-03-07 20:47:16', '2026-03-07 20:47:16'),
