(48, 'Visite de la délégation de la Fondation Canadienne des Femmes le 20 Novembre 2025', 'Visite de la délégation de la Fondation Canadienne des Femmes le 20 Novembre 2025', '<p>Visite de la délégation de la Fondation Canadienne des Femmes le 20 Novembre 2025</p>', '<p>Visite de la délégation de la Fondation Canadienne des Femmes le 20 Novembre 2025</p>', 'visite-de-la-delegation-de-la-fondation-canadienne-des-femmes-le-20-novembre-2025', '1774811782_69c97a86bd700.jpg', 'social', '2026-03-29 19:16:22', '2026-03-29 19:16:22'),
(49, 'Visite des locaux de Sofifran par leCentre de santé communautaire Hamilton/Niagara le 9 Décembre 2025', 'Visite des locaux de Sofifran par leCentre de santé communautaire Hamilton/Niagara le 9 Décembre 2025', '<p>Visite des locaux de Sofifran par leCentre de santé communautaire Hamilton/Niagara le 9 Décembre 2025</p>', '<p>Visite des locaux de Sofifran par leCentre de santé communautaire Hamilton/Niagara le 9 Décembre 2025</p>', 'visite-des-locaux-de-sofifran-par-lecentre-de-sante-communautaire-hamiltonniagara-le-9-decembre-2025', '1774812040_69c97b8882771.jpg', 'social', '2026-03-29 19:20:40', '2026-03-29 19:20:40');
INSERT INTO `activites` (`id`, `title_en`, `title_fr`, `description_en`, `description_fr`, `slug`, `image`, `categorie_activity_slug`, `created_at`, `updated_at`) VALUES
(50, 'FÊTE DES MERES SOFIFRAN 2026', 'FÊTE DES MERES SOFIFRAN 2026', '<p>Une célébration mémorable pour la Fête des Mères organisée par SOFIFRAN\r\n\r\nLe 10 mai dernier, SOFIFRAN a eu le plaisir d’organiser une magnifique \r\ncélébration de la Fête des Mères à Welland, réunissant près de 90 \r\nparticipants dans une ambiance chaleureuse, festive et familiale.\r\n\r\nCette journée spéciale a permis aux mamans, aux enfants et aux familles \r\nde partager des moments précieux autour d’activités variées, de musique,\r\n d’échanges et d’un repas communautaire riche en saveurs. Le potluck \r\ntrès varié a particulièrement marqué les participants, mettant en valeur\r\n la diversité culturelle et l’esprit de partage qui caractérisent notre \r\ncommunauté francophone.\r\n\r\nLes enfants présents ont également vécu une expérience mémorable, \r\nprofitant pleinement de l’ambiance joyeuse et conviviale tout au long de\r\n l’événement.  La programmation comprenait une animation musicale \r\nassurée par DJ Donlymix, ainsi qu’une causerie éducative animée par \r\nArnelle TCHAKO, conseillère en assurances et investissement. Cette \r\ndiscussion a permis aux participants d’en apprendre davantage sur \r\nplusieurs sujets importants liés à la gestion financière et à la \r\nprotection familiale, notamment l’assurance handicap, un sujet qui a \r\nsuscité beaucoup d’intérêt.\r\n\r\nAu total, 45 cadeaux ont été distribués aux mamans afin de souligner \r\nleur rôle précieux au sein des familles et de la communauté.\r\n\r\nParmi les nombreux témoignages reçus, Harmelle, l’une des mamans \r\nprésentes, a exprimé sa satisfaction concernant l’organisation de \r\nl’événement, l’ambiance musicale ainsi que la qualité des cadeaux \r\nofferts. Elle a également souligné avoir appris de nouvelles \r\ninformations importantes lors de la causerie sur les finances. Selon \r\nelle, ce type d’initiative permet à SOFIFRAN d’avoir un impact concret \r\ndans la communauté en favorisant les rencontres, les échanges et la \r\nsocialisation entre les familles.  SOFIFRAN tient à remercier \r\nchaleureusement tous les bénévoles, partenaires, participants et \r\ncollaborateurs qui ont contribué au succès de cette belle célébration \r\ndédiée aux mamans.\r\n\r\nNous adressons également un remerciement particulier à Patrimoine \r\ncanadien\r\n pour son soutien précieux, ainsi qu’au Centre communautaire Le Griffon\r\n pour son accompagnement et sa contribution à la réussite de cet \r\névénement communautaire.\r\n\r\nDécouvrez quelques images de cette journée remplie de joie, d’amour et \r\nde partage.                            <br></p>', '<p>Une célébration mémorable pour la Fête des Mères organisée par SOFIFRAN\r\n\r\nLe 10 mai dernier, SOFIFRAN a eu le plaisir d’organiser une magnifique \r\ncélébration de la Fête des Mères à Welland, réunissant près de 90 \r\nparticipants dans une ambiance chaleureuse, festive et familiale.\r\n\r\nCette journée spéciale a permis aux mamans, aux enfants et aux familles \r\nde partager des moments précieux autour d’activités variées, de musique,\r\n d’échanges et d’un repas communautaire riche en saveurs. Le potluck \r\ntrès varié a particulièrement marqué les participants, mettant en valeur\r\n la diversité culturelle et l’esprit de partage qui caractérisent notre \r\ncommunauté francophone.\r\n\r\nLes enfants présents ont également vécu une expérience mémorable, \r\nprofitant pleinement de l’ambiance joyeuse et conviviale tout au long de\r\n l’événement.  La programmation comprenait une animation musicale \r\nassurée par DJ Donlymix, ainsi qu’une causerie éducative animée par \r\nArnelle TCHAKO, conseillère en assurances et investissement. Cette \r\ndiscussion a permis aux participants d’en apprendre davantage sur \r\nplusieurs sujets importants liés à la gestion financière et à la \r\nprotection familiale, notamment l’assurance handicap, un sujet qui a \r\nsuscité beaucoup d’intérêt.\r\n\r\nAu total, 45 cadeaux ont été distribués aux mamans afin de souligner \r\nleur rôle précieux au sein des familles et de la communauté.\r\n\r\nParmi les nombreux témoignages reçus, Harmelle, l’une des mamans \r\nprésentes, a exprimé sa satisfaction concernant l’organisation de \r\nl’événement, l’ambiance musicale ainsi que la qualité des cadeaux \r\nofferts. Elle a également souligné avoir appris de nouvelles \r\ninformations importantes lors de la causerie sur les finances. Selon \r\nelle, ce type d’initiative permet à SOFIFRAN d’avoir un impact concret \r\ndans la communauté en favorisant les rencontres, les échanges et la \r\nsocialisation entre les familles.  SOFIFRAN tient à remercier \r\nchaleureusement tous les bénévoles, partenaires, participants et \r\ncollaborateurs qui ont contribué au succès de cette belle célébration \r\ndédiée aux mamans.\r\n\r\nNous adressons également un remerciement particulier à Patrimoine \r\ncanadien\r\n pour son soutien précieux, ainsi qu’au Centre communautaire Le Griffon\r\n pour son accompagnement et sa contribution à la réussite de cet \r\névénement communautaire.\r\n\r\nDécouvrez quelques images de cette journée remplie de joie, d’amour et \r\nde partage.                            <br></p>', 'fete-des-meres-sofifran-2026', '1778770062_6a05e08e05066.jpeg', 'culturel', '2026-05-14 14:47:42', '2026-05-14 14:47:42'),
(51, 'OCASI 2026', 'OCASI 2026', '<p><span style=\"color: rgb(102, 102, 102); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 15px;\">As part of its new project, “Building Capacity for Equitable Services for Refugees and Newcomers,” SOFIFRAN held a community engagement session attended by more than 30 participants on July 26, 2026, at Sacré-Coeur Church in Welland. During the meeting, Nana Ngobila, a program coordinator, presented SOFIFRAN’s services as well as the ACS+ approach. The session also included time for discussion and a question-and-answer period with participants. The discussions were rich and substantive. Community members shared their needs, expectations, and suggestions for certain services. In the presence of a CERF Niagara representative, proposals were also made regarding employability. This meeting was marked by constructive, forward-looking feedback, in a spirit of dialogue, collaboration, and continuous improvement of the services offered to the community.</span></p>', '<p><span style=\"color: rgb(102, 102, 102); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 15px;\">Dans le cadre de son nouveau projet \" Renforcer les capacités pour des services équitables aux réfugiés et aux nouveaux arrivants\" , SOFIFRAN a tenu une session de mobilisation communautaire réunissant plus d’une trentaine de participants le 26 juillet 2026 à l\'Église Sacré-Coeur de Welland. Lors de cette rencontre, Nana Ngobila, intervenante, a présenté les services de SOFIFRAN ainsi que l’approche ACS+. La session a également permis un temps d’échanges et de questions-réponses avec les participants. Les discussions ont été riches et nourries. Les membres de la communauté ont partagé leurs besoins, leurs attentes, ainsi que des suggestions pour certains services. En présence d’un agent du CERF Niagara, des propositions ont aussi été formulées en matière d’employabilité. Cette rencontre a été marquée par des critiques constructives tournées vers l’avenir, dans un esprit de dialogue, de collaboration et d’amélioration continue des services offerts à la communauté.</span></p>', 'ocasi-2026', '1785944184_6a73587882e74.jpg', 'social', '2026-08-05 15:36:24', '2026-08-05 15:36:24'),
(52, 'Canadian Multicultural Day 2026', 'Journée Multiculturelle Canadienne 2026', '<p><span data-subtree=\"aimfl,mfl\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 400; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\" style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; margin: 0px; border-bottom: 0px rgb(10, 10, 10);\">Canadian Multiculturalism Day took place on </span><mark jsuid=\"PntTV_n\" class=\"HxTRcb\" jsaction=\"click:&amp;PntTV_n|h5M12e;mouseenter:&amp;PntTV_n|sbHm2b;mouseleave:&amp;PntTV_n|Tx5Rb;rcuQ6b:&amp;PntTV_n|npT2md\" jscontroller=\"DfH0l#VLQhtf\" data-sfc-root=\"ep\" data-wiz-uids=\"PntTV_o\" data-ved=\"2ahUKEwjDmuaQ64mWAxWnUUEAHex-Of8QuJAPegoIAggACAAICRAD\" data-complete=\"true\" data-sfc-inited=\"2\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 500; margin: 0px; text-decoration: none; border-bottom: 0px rgb(0, 29, 53);\" style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; margin: 0px; border-bottom: 0px rgb(0, 29, 53);\"><!--qkimaf PntTV_n/HugV6--><!--cqw1tb PntTV_n/HugV6--><span class=\"yADgie\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 500; margin: 0px; text-decoration: none; border-bottom: 0px rgb(0, 29, 53);\" style=\"margin: 0px; border-bottom: 0px rgb(0, 29, 53);\">Saturday, June 27, 2026</span><!--TgQPHd|||[]--></mark><span class=\"yADgie\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 400; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\" style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; margin: 0px; border-bottom: 0px rgb(10, 10, 10);\">. It is an annual federal observance recognizing the diverse cultural communities, traditions, and languages that enrich Canadian society and reinforce the nation\'s commitment to equity, inclusion, and mutual respect.</span></p>', '<p>La Journée du multiculturalisme canadien a eu lieu le samedi 27 juin 2026. Il s\'agit d\'une journée fédérale annuelle qui rend hommage à la diversité des communautés culturelles, des traditions et des langues qui enrichissent la société canadienne et renforcent l\'engagement de la nation en faveur de l\'équité, de l\'inclusion et du respect mutuel.</p>', 'journee-multiculturelle-canadienne-2026', '1785945298_6a735cd2413f6.jpg', 'culturel', '2026-08-05 15:54:58', '2026-08-05 15:54:58');
