INSERT INTO `apropos` (`id`, `nom_fr`, `nom_en`, `title_fr`, `title_en`, `description_fr`, `description_en`, `cle_video`, `created_at`, `updated_at`) VALUES
(1, 'À propos de nous', 'About us', 'Sofifran', 'Sofifran', 'Sofifran', 'Sofifran', '519159959', '2022-05-18 02:20:39', '2022-05-18 00:20:39');
INSERT INTO `ateliers` (`id`, `title_fr`, `title_en`, `description_fr`, `description_en`, `image`, `start`, `end`, `hour_start`, `hour_end`, `slug`, `color`, `created_at`, `updated_at`) VALUES
(1, 'Célébration  fête des mères', 'Mother\'s Day celebration', '<p>Célébration&nbsp; fête des mères</p><p>Le dimanche 8 mai de 15h (3 p.m.) à 18h (6 p.m.) à l&amp;#39;hôtel de ville de Welland. Une belle&nbsp;<span style=\"font-size: 1rem;\">célébration en l’honneur des mamans immigrantes du Niagara. De la poésie, des chants,&nbsp;</span><span style=\"font-size: 1rem;\">des jeux, des cadeaux et un bon repas à partager ensemble! Bienvenue à toutes et à&nbsp;</span><span style=\"font-size: 1rem;\">tous !</span></p>', '<p>Mother\'s Day celebration</p><p>Sunday, May 8 from 3 p.m. to 6 p.m. at Welland City Hall. A beautiful&nbsp;<span style=\"font-size: 1rem;\">celebration in honour of Niagara\'s immigrant moms. Poetry, songs,&nbsp;</span><span style=\"font-size: 1rem;\">games, gifts and a great meal to share! Welcome to all!</span></p><p>Welcome to all!</p>', '1654871369.jpeg', '2022-05-08', '2022-05-08', '00:00:00', '23:59:00', 'emergence-57450', '#007bff', '2022-06-10 14:29:30', '2022-06-10 12:29:30'),
(2, 'Au coin du feu', 'At the Fireside', '<p>Au coin du feu</p><p>Un rendez-vous culturel, artistique et socialement divertissant à ne pas rater ce jeudi 12 mai à 19h. Venez-vous asseoir autour de notre feu virtuel et laissez M. Aimé Avolonto vous emporter dans l\'un de ses beaux contes africains.&nbsp;<br></p>', '<p>At the Fireside</p><p>A cultural, artistic and socially entertaining event not to be missed&nbsp; Thursday, May 12th at 7pm. Come and sit around our virtual fire and let Mr. Aimé Avolonto carry you away in one of his beautiful African tales.&nbsp;<br></p>', '1654870329.jpeg', '2022-05-12', '2022-05-12', '00:00:00', '23:59:00', 'au-coin-du-feu', '#dc3545', '2022-06-10 14:12:25', '2022-06-10 12:12:25'),
(3, 'Notre culture dans nos mets', 'Our culture in our dishes', '<p>Notre culture dans nos mets</p><p><font size=\"4\" face=\"tahoma, sans-serif\" style=\"color: rgb(34, 34, 34);\">Connaissez-vous le Widjila?&nbsp;<span style=\"line-height: 19.26px;\">Venez découvrir ce plat originaire du nord du Mali et l’histoire qui en découle</span></font><font size=\"4\" face=\"tahoma, sans-serif\" style=\"color: rgb(34, 34, 34);\"><span style=\"line-height: 19.26px;\">&nbsp;vendredi 20 mai à 19h (7pm). Présentation en mode virtuel par Kina Macinanké.</span><span style=\"line-height: 19.26px;\">&nbsp;</span>&nbsp;</font></p><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><font face=\"tahoma, sans-serif\" size=\"4\">Lien pour accéder à la réunion</font></div>', '<p>Our culture in our dishes</p><p>Do you know Widjila? Come discover this dish from northern Mali and the history behind it on Friday, May 20th at 7pm. Presentation in virtual mode by Kina Macinanké.&nbsp;&nbsp;</p><p>Link to the meeting</p>', '1654870750.jpeg', '2022-05-20', '2022-05-20', '00:00:00', '23:59:00', 'notre-culture-dans-nos-mets', '#0b0001', '2022-06-10 14:19:20', '2022-06-10 12:19:20'),
(4, 'Anniversaire Garderie Les petits papillons', 'Birthday Garderie Les Petits Papillons', '<p>La garderie Les petits papillons célèbre son premier anniversaire.&nbsp;<br></p>', '<p>The Home child care Les Petits Papillons is celebrating its 1st anniversary.<br></p>', '1653682425.jpg', '2022-05-29', '2022-05-29', '00:00:00', '23:59:00', 'anniversaire-garderie-les-petits-papillons', '#ffc107', '2022-05-27 20:13:45', '2022-05-27 18:13:45'),
(5, 'Niagara Folk Arts Festival', 'Niagara Folk Arts Festival', '<p>Niagara Folk Arts Festival<br></p>', '<p>Niagara Folk Arts Festival<br></p>', '1654284203.jpeg', '2022-06-11', '2022-06-11', '00:00:00', '23:59:00', 'niagara-folk-arts-festival', '#ffc107', '2022-06-03 19:23:24', '2022-06-03 17:23:24'),
(6, 'Assemblée générale annuelle', 'annual general meeting', '<p>Assemblée générale annuelle<br></p>', '<p>Annual general meeting<br></p>', '1654869129.jpeg', '2022-06-19', '2022-06-19', '00:00:00', '23:59:00', 'assemblee-generale-annuelle', '#007bff', '2022-06-10 13:52:10', '2022-06-10 11:52:10'),
(7, 'Le Canada en fête - buffet multiculturel', 'Party Canada - Multicultural buffet', '<p>Le Canada en fête - buffet multiculturel</p><p>Vendredi 1 er juillet célébrons Le Canada en fête / Canada day, pour l’occasion Sofifran&nbsp;<span style=\"font-size: 1rem;\">organise un grand buffet multiculturel qui aura lieu sur la place Welland&nbsp;</span><span style=\"font-size: 1rem;\">Farmers #39;Market, adresse : 70 Young St, Welland, ON L3B 4C5, heure à 15h (3pm).</span></p>', '<p>Party Canada - Multicultural buffet</p><p>Friday, July 1st, let\'s celebrate Canada day / Le Canada en fête, for the occasion&nbsp;&nbsp;<span style=\"font-size: 1rem;\">Sofifran organizes a big multicultural buffet that will take place at the Welland Farmers #39;Market, address: 70 Young St, Welland, ON L3B 4C5, time at 3pm.</span></p>', '1657546755.jpeg', '2022-07-01', '2022-07-01', '15:00:00', '19:00:00', 'le-canada-en-fete-buffet-multiculturel', '#dc3545', '2022-07-11 13:40:44', '2022-07-11 11:40:44'),
(8, 'Camp d\'été Multi\'arts 2022', 'Multi\'arts summer camp 2022', '<p>Le camp d\'été Multi\'arts est de retour, hâtez-vous car les places sont limitées!!</p><p>Inscrivez vos enfants à l\'adresse courriel suivante : info@sofifran.org</p>', '<p>The Multi\'arts summer camp is back, hurry because places are limited!!</p><p>Register your children at the following email address: info@sofifran.org</p>', '1656007481.jpeg', '2022-07-18', '2022-07-22', '08:00:00', '17:05:00', 'camp-dete-multiarts-2022', '#dc3545', '2022-06-23 16:04:42', '2022-06-23 16:04:42'),
(9, 'Camp d\'été Multi\'arts 2022', 'Multi\'arts summer camp 2022', '<p>Le camp d\'été Multi\'arts est de retour, hâtez-vous car les places sont limitées!!</p><p>Inscrivez vos enfants à l\'adresse courriel suivante : info@sofifran.org</p>', '<p>The Multi\'arts summer camp is back, hurry because places are limited!!</p><p>Register your children at the following email address: info@sofifran.org</p>', '1656007601.jpeg', '2022-07-25', '2022-07-29', '08:00:00', '17:00:00', 'camp-dete-multiarts-2022-91552', '#dc3545', '2022-06-23 16:06:41', '2022-06-23 16:06:41'),
(10, 'Les jeux de Sofifran', 'Sofifran\'s games', '<p class=\"MsoNormal\" style=\"margin-bottom:0cm;mso-line-height-alt:12.65pt\"><span style=\"font-size: 16pt; font-family: &quot;Times New Roman&quot;, serif;\">Débutons le mois\r\nd’août en beauté et amusons-nous tous ensemble !</span><span style=\"mso-ascii-font-family:\r\nCalibri;mso-fareast-font-family:&quot;Times New Roman&quot;;mso-hansi-font-family:Calibri;\r\nmso-bidi-font-family:Calibri;color:#222222;mso-fareast-language:FR-CA\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;mso-line-height-alt:12.65pt\"><span style=\"font-size: 16pt; font-family: &quot;Times New Roman&quot;, serif;\">Pour vous Sofifran\r\norganise 2 grandes activités le 1<sup>er</sup>&nbsp;août prochain&nbsp;:</span><span style=\"mso-ascii-font-family:Calibri;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-hansi-font-family:Calibri;mso-bidi-font-family:Calibri;color:#222222;\r\nmso-fareast-language:FR-CA\"><o:p></o:p></span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin-bottom:0cm;mso-add-space:auto;\r\ntext-indent:-18.0pt;mso-line-height-alt:12.65pt;mso-list:l0 level1 lfo1\"><span style=\"font-size: 16pt; font-family: &quot;Times New Roman&quot;, serif;\">*&nbsp; Les jeux de SOFIFRAN pour les jeunes</span><span style=\"mso-ascii-font-family:\r\nCalibri;mso-fareast-font-family:&quot;Times New Roman&quot;;mso-hansi-font-family:Calibri;\r\nmso-bidi-font-family:Calibri;color:#222222;mso-fareast-language:FR-CA\"><o:p></o:p></span></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin-bottom:0cm;mso-add-space:auto;\r\ntext-indent:-18.0pt;mso-line-height-alt:12.65pt;mso-list:l0 level1 lfo1\"><span style=\"font-size: 16pt; font-family: &quot;Times New Roman&quot;, serif;\">*&nbsp; Le BBQ annuel et le potluck de la communauté.</span><span style=\"mso-ascii-font-family:Calibri;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-hansi-font-family:Calibri;mso-bidi-font-family:Calibri;color:#222222;\r\nmso-fareast-language:FR-CA\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;mso-line-height-alt:12.65pt\"><span style=\"font-size: 16pt; font-family: &quot;Times New Roman&quot;, serif;\">Venez nombreux !!</span><span style=\"mso-ascii-font-family:Calibri;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-hansi-font-family:Calibri;mso-bidi-font-family:Calibri;color:#222222;\r\nmso-fareast-language:FR-CA\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;mso-line-height-alt:12.65pt\"><span style=\"font-size: 16pt; font-family: &quot;Times New Roman&quot;, serif;\">Quand: lundi 1<sup>er</sup>&nbsp;août\r\n2022</span><span style=\"mso-ascii-font-family:Calibri;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;;mso-hansi-font-family:Calibri;mso-bidi-font-family:Calibri;\r\ncolor:#222222;mso-fareast-language:FR-CA\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;mso-line-height-alt:12.65pt\"><span lang=\"EN-CA\" style=\"font-size: 16pt; font-family: &quot;Times New Roman&quot;, serif;\">Lieu: Chippawa parc, 128 Fitch St, Welland, ON L3C\r\n4V3</span><span lang=\"EN-CA\" style=\"mso-ascii-font-family:Calibri;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;;mso-hansi-font-family:Calibri;mso-bidi-font-family:Calibri;\r\ncolor:#222222;mso-ansi-language:EN-CA;mso-fareast-language:FR-CA\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;mso-line-height-alt:12.65pt\"><span style=\"font-size: 16pt; font-family: &quot;Times New Roman&quot;, serif;\">Heure: à 12h</span><span style=\"mso-ascii-font-family:Calibri;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-hansi-font-family:Calibri;mso-bidi-font-family:Calibri;color:#222222;\r\nmso-fareast-language:FR-CA\"><o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\"><span style=\"font-size:16.0pt;line-height:107%;mso-bidi-font-family:\r\nCalibri;mso-bidi-theme-font:minor-latin\">Bienvenue à tous!<o:p></o:p></span></p>', '<p>Let\'s start the month of August with a bang and have fun together!</p><p>For you Sofifran is organizing 2 great activities on August 1st :</p><p>&nbsp;*&nbsp; SOFIFRAN\'s games for kids</p><p>&nbsp;*&nbsp; The annual BBQ and community potluck.</p><p>Come and join us!</p><p>When: Monday August 1st 2022</p><p>Where: Chippawa Park, 128 Fitch St, Welland, ON L3C 4V3</p><p>Time: 12pm</p><p>Everyone is welcome!</p><div><br></div>', '1657656225.jpeg', '2022-08-01', '2022-08-01', '12:00:00', '17:00:00', 'les-jeux-de-sofifran', '#ffc107', '2022-07-12 18:03:46', '2022-07-12 18:03:46'),
(11, 'Art\'ifice', 'Art\'ifice', '<p>Nous tenons à remercier spécialement Vice Versa d’avoir donné l’opportunité à SOFIFRAN de créer ces moments de joie inoubliables en juin dernier et septembre 2022, et ce, en collaboration avec toutes les écoles du Conseil scolaire Viamonde de la région du Niagara, l’É.É. L’Héritage, É.É. LaMarsh, É.É. Franco-Niagara, É.É. Nouvel Horizon ainsi que l’É.S. Franco-Niagara !<br></p>', '<p>We would like to especially thank Vice Versa for giving SOFIFRAN the opportunity to create these unforgettable moments of joy last June and September 2022, in collaboration with all the schools of the Conseil scolaire Viamonde in the Niagara region, l \'E.E. The Heritage, É.É. LaMarsh, S.E. Franco-Niagara, É.É. New Horizon as well as the É.S. Franco-Niagara!<br></p>', '1658768736.jpg', '2022-06-09', '2022-06-09', '12:30:00', '12:30:00', 'artifice', '#dc3545', '2022-11-07 21:45:55', '2022-11-07 20:45:55'),
(12, 'Apprends tissage', 'Learn to weave', '<p>Nous tenons à remercier spécialement Vice Versa d’avoir donné l’opportunité à SOFIFRAN de créer ces moments de joie inoubliables en juin dernier et septembre 2022, et ce, en collaboration avec toutes les écoles du Conseil scolaire Viamonde de la région du Niagara, l’É.É. L’Héritage, É.É. LaMarsh, É.É. Franco-Niagara, É.É. Nouvel Horizon ainsi que l’É.S. Franco-Niagara !<br></p>', '<p>We would like to especially thank Vice Versa for giving SOFIFRAN the opportunity to create these unforgettable moments of joy last June and September 2022, in collaboration with all the schools of the Conseil scolaire Viamonde in the Niagara region, l \'E.E. The Heritage, É.É. LaMarsh, S.E. Franco-Niagara, É.É. New Horizon as well as the É.S. Franco-Niagara!<br></p>', '1658769437.jpg', '2022-06-20', '2022-06-20', '13:00:00', '13:00:00', 'apprends-tissage', '#dc3545', '2022-11-07 21:44:29', '2022-11-07 20:44:29'),
(13, 'Marche', 'Hiking', '<p>Venez marcher avec nous dimanche 2 octobre 2022.<br></p>', '<p>Come walk with us on Sunday October 2, 2022.<br></p>', '1667251259.jpeg', '2022-10-02', '2022-10-02', '15:00:00', '15:00:00', 'marche', '#ffc107', '2022-10-31 20:21:00', '2022-10-31 20:21:00'),
(14, 'Notre culture dans nos mets', 'Our culture in our dishes', '<p class=\"MsoNormal\" style=\"margin-left:18.0pt;tab-stops:54.0pt\"><font color=\"#222222\" face=\"Bell MT, serif\"><span style=\"font-size: 21.3333px;\">Et si vous nous accompagniez virtuellement au Sénégal, dans la cuisine de Zeina Tall jeudi 27 octobre à 19h00 (7pm)?&nbsp;</span></font></p><p class=\"MsoNormal\" style=\"margin-left:18.0pt;tab-stops:54.0pt\"><font color=\"#222222\" face=\"Bell MT, serif\"><span style=\"font-size: 21.3333px;\">Ensemble nous apprendrons à préparer, du Tchep au poisson et découvrirons son origine.&nbsp;</span></font></p>', '<p>How about accompanying us virtually to Senegal, in Zeina Tall\'s kitchen on Thursday October 27 at 7:00 p.m. (7 p.m.)?&nbsp;</p><p>Together we will learn how to prepare,&nbsp; Tchep with fish and discover its origin.</p>', '1667251508.jpeg', '2022-10-27', '2022-10-27', '19:00:00', '19:00:00', 'notre-culture-dans-nos-mets-54959', '#dc3545', '2022-10-31 20:25:08', '2022-10-31 20:25:08'),
(15, 'Soirée des dames', 'Ladies night', '<p>Passons une soirée exceptionnelle entre dames!</p>', '<p>Let\'s spend an exceptional evening between ladies!<br></p>', '1667939236.jpeg', '2022-11-26', '2022-11-26', '18:00:00', '18:00:00', 'soiree-des-dames', '#dc3545', '2022-11-08 19:27:16', '2022-11-08 19:27:16'),
(16, 'Soirée intergénérationnelle', 'Intergenerational evening', NULL, NULL, '1668114300.jpeg', '2022-12-01', '2022-12-01', '18:00:00', '18:00:00', 'soiree-intergenerationnelle', '#ffc107', '2022-11-10 20:05:00', '2022-11-10 20:05:00'),
(17, 'À Pleine Voix', 'Out Loud', '<p>Projection du film à pleine voix de la réalisatrice&nbsp;<span style=\"font-size: 1rem;\">Ouchaou Ozarowski, dimanche 11 décembre à&nbsp;</span><span style=\"font-size: 1rem;\">15h (3:00pm) au City Hall de Welland</span></p>', '<p>Screening of the film Out Loud by director Ouchaou Ozarowski, Sunday, December 11 at 15H (3:00 p.m.) at City Hall in Welland<br></p>', '1673987782.jpeg', '2022-12-11', '2022-12-11', '15:00:00', '17:30:00', 'a-pleine-voix', '#dc3545', '2023-01-17 20:49:31', '2023-01-17 19:49:31'),
(18, 'Réveillon', 'New Year\'s Eve', '<p>Clôturons ensemble l\'année 2022 et accueillons&nbsp;<span style=\"font-size: 1rem;\">2023 en musique, en danse, autour d\'un buffet&nbsp;</span><span style=\"font-size: 1rem;\">multiculturel à l\'image de notre communauté, sans&nbsp;</span><span style=\"font-size: 1rem;\">oublier les cadeaux pour nos tout petits.</span></p>', '<div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(0, 0, 0); font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 16px;\">Let\'s end this year together and welcome 2023 with music and dance around a multicultural buffet that reflects our community, without forgetting gifts for our liltle ones.&nbsp;</span><b><font color=\"#cc0000\"><font size=\"4\"><br></font></font></b></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br></div>', '1673988372.jpeg', '2022-12-17', '2022-12-17', '17:00:00', '21:30:00', 'reveillon', '#ffc107', '2023-01-17 19:46:12', '2023-01-17 19:46:12'),
(20, 'Festival Féstiv\'Ébène 16e édition!!', 'Féstiv\'Ébène Festival 16th edition!', '<p>Le Festival Féstiv\'Ébène fait son grand retour en présentiel. Ne manquez pas la 16e édition pleine de surprises!!</p>', '<p>The Festiv\'Ébène Festival is making its big comeback on live. Don\'t miss the 16th edition full of surprises!!<br></p>', '1674856676.jpeg', '2023-02-01', '2023-02-10', '12:00:00', '18:00:00', 'festival-festivebene-16e-edition-41550', '#dc3545', '2023-01-27 21:57:57', '2023-01-27 20:57:57'),
(21, 'Festival Féstiv\'Ébène 16e édition!!', 'Féstiv\'Ébène Festival 16th edition!', '<p>Le festival Festiv\'Ébène fait son grand retour en présentiel à Welland et vous êtes tous les bienvenus!!</p>', '<p>The Festiv\'Ébène festival is back on live in Welland and you are all welcome!<br></p>', '1674856510.jpeg', '2023-02-25', '2023-02-25', '18:00:00', '22:00:00', 'festival-festivebene-16e-edition-82921', '#dc3545', '2023-01-27 20:55:11', '2023-01-27 20:55:11'),
(22, 'Notre culture dans nos mets', 'Our culture in our dishes', 'Retrouvons-nous dimanche 29 janvier à Holy Trinity Chuch de Welland afin d\'apprendre la culture et les mets traditionnels du Congo RDC à 14h00.&nbsp; &nbsp;', '<p>Let\'s meet on Sunday, January 29 at Holy Trinity Chuch in Welland to learn about the culture and traditional dishes of the DRC at 2:00 pm.<br></p>', '1674857518.jpeg', '2023-01-29', '2023-01-29', '14:00:00', '16:00:00', 'notre-culture-dans-nos-mets-21681', '#dc3545', '2023-01-27 21:11:58', '2023-01-27 21:11:58'),
