(49, 'Introduction à la communauté de pratique pour les entrepreneurs noirs.', 'Introduction to the community of practice for black entrepreneurs.', 'Un atelier qui vous offre des outils culturellement adaptés pour aider à vous lancer en affaires avec assurance.', '<p>A workshop offering culturally adapted tools to help you launch your business with confidence.<br></p>', '1688753258.jpeg', '2023-07-09', '2023-07-09', '15:00:00', '17:00:00', 'introduction-a-la-communaute-de-pratique-pour-les-entrepreneurs-noirs', '#28a745', '2023-07-07 18:08:26', '2023-07-07 16:08:26'),
(50, 'Aqua Zumba', 'Aqua Zumba', '<p>Grâce au soutien financier généreusement accordé par la prestigieuse Fondation Trillium de l\'Ontario, SOFIFRAN a le plaisir de présenter un événement emblématique, \"Aqua Zuma\", dans le cadre de son ambitieux programme de sensibilisation à la nutrition saine et aux activités physiques. Cette initiative reflète notre engagement pour le bien-être holistique des femmes immigrées dans la région de Niagara, en les encourageant à adopter un mode de vie sain et actif. Nous vous invitons cordialement à vous joindre à nous pour une expérience mémorable de remise en forme aquatique et de solidarité communautaire.<br></p>', '<p>Thanks to the financial support generously granted by the prestigious Ontario Trillium Foundation, SOFIFRAN is delighted to present an iconic event, \"Aqua Zuma\", as part of its ambitious program to raise awareness of healthy nutrition and physical activities. This initiative reflects our commitment to the holistic well-being of immigrant women in Niagara, encouraging them to adopt a healthy and active lifestyle. We cordially invite you to join us for a memorable experience of aquatic fitness and community solidarity.<br></p>', '1692622207.jpeg', '2023-08-23', '2023-03-23', '18:30:00', '19:30:00', 'aqua-zumba', '#dc3545', '2023-08-21 15:00:15', '2023-08-21 13:00:15'),
(51, 'Réveillon de fin d\'année', 'End of year celebration', '<p>Reconnaissance des partenaires financiers, Cadeaux des enfants, diner, musique et danse avec Hassan El Hadi et Justine Gogoua.</p>', '<p>Recognition of financial partners, children\'s gifts, dinner, dance and music with Hassan El Hadi and Justine Gogoua<br></p>', '1702065902.png', '2023-12-16', '2023-12-16', '17:00:00', '11:30:00', 'reveillon-de-fin-dannee', '#28a745', '2023-12-08 20:05:03', '2023-12-08 19:05:03'),
(52, 'Zumba exercices en groupes pour les femmes', 'Zumba group exercises for women', '<p>Faire savoir à la communauté les meilleures stratégies d\'activités physiques&nbsp; pour se maintenir en bonne santé sous la direction de coach Laetitia Kakindi</p><p>Adresse:</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span lang=\"EN-CA\" style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\">Holy Trinity Church Welland<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span lang=\"EN-CA\" style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\">77 Division St. Welland, ON\r\nL3B 3Z8<o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\">Contact 905&nbsp;714 7333 ou 905&nbsp;226 5282<o:p></o:p></span></p>', '<p>Let the community know about the best physical activity strategies for maintaining good health under the direction of coach Laetitia Kakindi</p><p>Address:</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span lang=\"EN-CA\" style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\">Holy Trinity Church Welland<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span lang=\"EN-CA\" style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\">77 Division St. Welland, ON\r\nL3B 3Z8<o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\">Contact 905&nbsp;714 7333 ou 905&nbsp;226 5282<o:p></o:p></span></p>', '1705087170.jpg', '2024-01-24', '2024-01-24', '18:30:00', '06:30:00', 'zumba-exercices-en-groupes-pour-les-femmes', '#28a745', '2024-01-12 18:19:31', '2024-01-12 18:19:31'),
(53, 'Arriba: exercices en groupe pour les femmes', 'Arriba: Group exercise for women', '<p>Faire savoir à la communauté les meilleures stratégies d\'activités physiques&nbsp; pour se maintenir en bonne santé sous la direction de YMCA</p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Adresse:</span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span lang=\"ES\" style=\"font-size:12.0pt;font-family:&quot;Calibri Light&quot;,sans-serif;mso-ascii-theme-font:\r\nmajor-latin;mso-hansi-theme-font:major-latin;mso-bidi-theme-font:major-latin;\r\nmso-ansi-language:ES\"><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Niagara Centre YMCA 310 Woodlawn Rd,</span><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\">\r\n\r\n</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Calibri Light&quot;,sans-serif;mso-ascii-theme-font:\r\nmajor-latin;mso-hansi-theme-font:major-latin;mso-bidi-theme-font:major-latin\">Welland,\r\nON L3C 7N</span><span style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\"><o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\">Contact 905&nbsp;714 7333 ou 905&nbsp;226 5282<o:p></o:p></span></p>', '<p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Informing the community about the best physical activity strategies for maintaining good health under the direction of the YMCA</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Address:</span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span lang=\"ES\" style=\"font-size:12.0pt;font-family:&quot;Calibri Light&quot;,sans-serif;mso-ascii-theme-font:\r\nmajor-latin;mso-hansi-theme-font:major-latin;mso-bidi-theme-font:major-latin;\r\nmso-ansi-language:ES\"><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Niagara Centre YMCA 310 Woodlawn Rd,</span><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\">\r\n\r\n</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Calibri Light&quot;,sans-serif;mso-ascii-theme-font:\r\nmajor-latin;mso-hansi-theme-font:major-latin;mso-bidi-theme-font:major-latin\">Welland,\r\nON L3C 7N</span><span style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\"><o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\"><span style=\"font-size: 12pt; font-family: &quot;Calibri Light&quot;, sans-serif;\">Contact 905&nbsp;714 7333 ou 905&nbsp;226 5282<o:p></o:p></span></p>', '1705089590.jpg', '2024-01-13', '2024-01-13', '10:30:00', '11:30:00', 'arriba-exercices-en-groupes-pour-les-femmes', '#28a745', '2024-01-25 15:46:24', '2024-01-25 14:46:24'),
(54, 'Festival: De notre foyer au vôtre saison 2', 'Festival: From our home to yours season 2', '<p>Une série d\'ateliers, de contes et de spectacles gratuits pour aller à la découverte des richesses culturelles des franco -ontariens de toutes les origines.</p><p>adresse:</p><p>Niagara Folk Arts Multicultural Centre</p><p>85 Church St, Saint Catharines ON</p><p>contact: 905 714 7333 / 905 226 5282</p>', '<p>A series of free workshops, stories and shows to discover the cultural richness of Franco-Ontarians of all origins.</p><p>address:</p><p>Niagara Folk Arts Multicultural Centre</p><p>85 Church St, Saint Catharines ON</p><p><span style=\"font-size: 1rem;\">contact: 905 714 7333 / 905 226 5282</span><br></p>', '1705948256.jpg', '2024-02-10', '2024-02-10', '18:00:00', '21:00:00', 'de-notre-foyer-au-votre-saison-2', '#28a745', '2024-02-05 20:09:17', '2024-02-05 19:09:17'),
(55, 'SOFIFRAN annonce avec enthousiasme la 2e édition du Salon du livre des Francophonies du Niagara (SAFRAN)', 'SOFIFRAN is pleased to announce the 2nd edition of the \'\'Salon du livre des Francophonies du Niagara\'\' (SAFRAN)', '<p style=\"text-align: justify; \">SOFIFRAN est ravie de dévoiler les détails de la prochaine édition du Salon du livre&nbsp;<span style=\"font-size: 1rem;\">des francophonies du Niagara (SAFRAN), un événement littéraire et culturel&nbsp;</span><span style=\"font-size: 1rem;\">incontournable qui se tiendra du jeudi 21 mars au dimanche 24 mars 2024.&nbsp;</span><span style=\"font-size: 1rem;\">L\'événement débutera à 10h chaque jour et se déroulera au prestigieux espace de&nbsp;</span><span style=\"font-size: 1rem;\">l\'école des beaux-arts Marilyn A. Walker de l\'université Brock, située à St. Catharines.</span></p><p>E-mail: lesafran2024@gmail.com</p><p>Site: www.sofifran.org/safran<br></p><p>contact: 905 714 7333/905 226 5282</p><p><br></p>', '<p style=\"text-align: justify; \">SOFIFRAN is delighted to announce the details of the next edition of the Salon du Livre&nbsp;<span style=\"font-size: 1rem;\">des Francophonies du Niagara (SAFRAN), an exceptional literary event in and for the&nbsp;</span><span style=\"font-size: 1rem;\">peninsula. The event will take place March 21 st to 24 th , 2024, and will begin at 10am&nbsp;</span><span style=\"font-size: 1rem;\">each day in the prestigious space of the Marilyn I. Walker School of Fine and&nbsp;</span><span style=\"font-size: 1rem;\">Performing Arts, Brock University, downtown St Catharines. The opening will be held at&nbsp;</span><span style=\"font-size: 1rem;\">the Film House, in the First Ontario Performing Arts Centre, also located in downtown&nbsp;</span><span style=\"font-size: 1rem;\">St Catharines.</span></p><p>E-mail: lesafran2024@gmail.com</p><p>Site: www.sofifran.org/safran<br></p><p>contact: 905 714 7333/905 226 5282<span style=\"font-size: 1rem;\"><br></span></p>', '1705517726.jpg', '2024-03-21', '2024-03-24', '10:00:00', '18:00:00', 'sofifran-annonce-avec-enthousiasme-la-2e-edition-du-salon-du-livre-des-francophonies-du-niagara-safran', '#28a745', '2024-01-17 19:02:46', '2024-01-17 18:02:46'),
(56, 'Festiv \'Ébène: Effervescence Culturelle 2024', 'Festiv \'Ebène : Cultural Effervescence 2024', '<p>Sofifran célèbre le mois de l\'histoire des noirs avec deux événements importants à savoir:</p><p>* 10 février 2024 à 17h&nbsp; Festival: De notre foyer au vôtre</p><p>*24 février 2024 à 17h Festiv\' Ébène Effervescence culturelle 2024</p><p>Adresse:&nbsp;</p><p>Niagara Folk Arts Multiculturel centre</p><p>85 Church St, Saint Catharines</p><p>contact: 905 714 7333 / 905 226 5282</p>', '<p>Sofifran celebrates Black History Month with two major events:</p><p>* February 10, 2024 at 5pm&nbsp;<span style=\"font-size: 1rem;\">Festiva :&nbsp;</span><span style=\"font-size: 1rem;\">From our home to yours</span></p><p>*February 24, 2024 at 5pm&nbsp; Festiv \'Ebene Cultural effervescence 2024</p><p>Address:</p><p>Niagara Folk Arts Multicultural center</p><p>85 Church St, Saint Catharines</p><p><span style=\"font-size: 1rem;\">contact: 905 714 7333 / 905 226 5282</span><br></p>', '1708007640.png', '2024-02-24', '2024-02-24', '17:00:00', '21:00:00', 'effervescence-culturelle-2024', '#28a745', '2024-02-15 14:34:01', '2024-02-15 13:34:01'),
(57, 'Nutrition saine et activités physiques: Zumba', 'Healthy nutrition and physical activity : Zumba', '<p>Nutrition saine et activités physiques: Zumba exercices en groupes pour les femmes&nbsp;sous la direction de coach Laeticia Kakindi</p><p>Adresse:&nbsp;</p><p>Holy Trinity Anglican Church&nbsp;</p><p>77 Division St, Welland ON</p><p>contact: 905 714 7333/905 226 5282</p>', '<p>Healthy nutrition and physical activities: Zumba group exercises for women led by coach Laeticia Kakindi<br></p><p>Adresse:</p><p>Holy Trinity Anglican Church&nbsp;</p><p>77 Division St, Welland ON</p><p>contact: 905 714 7333/905 226 5282</p>', '1706198446.jpg', '2024-02-07', '2024-02-07', '18:00:00', '19:00:00', 'zumba-exercices-en-groupes-pour-les-femmes-30354', '#28a745', '2024-02-05 20:06:24', '2024-02-05 19:06:24'),
(58, 'Nutrition saine et activités physiques: Arriba', 'Healthy nutrition and physical activity: Arriba', '<p>Nutrition saine et activités physiques: Arriba&nbsp;sous la direction de YMCA</p><p>Adresse:&nbsp;</p><p>Niagara Centre YMCA 310 Woodlawn Rd, Welland</p><p><span style=\"font-size: 1rem;\">Contact 905 714 7333 / 905 226 5282</span><br></p>', '<p>Healthy nutrition and physical activity: Arriba&nbsp; under the leadership of YMCA.</p><p>Address:</p><p>Niagara Centre YMCA 310 Woodlawn Rd, Welland</p><p><span style=\"font-size: 1rem;\">Contact 905 714 7333 / 905 226 5282</span></p>', '1706203776.jpg', '2024-02-03', '2024-02-03', '10:30:00', '10:30:00', 'faire-savoir-a-la-communaute-les-meilleures-strategies-dactivites-physiques-pour-se-maintenir-en-bonne-sante-sous-la-direction-de-ymca', '#28a745', '2024-02-05 20:02:16', '2024-02-05 19:02:16'),
(59, 'Journée internationale des droits des femmes \'Tenue de soirée\'', 'International Women\'s Rights Day \'formal dressing\'', '<p>Très chères Dames,</p><p>Nous avons le plaisir de vous inviter à une soirée très spéciale en l\'honneur de la&nbsp;<span style=\"font-size: 1rem;\">Journée Internationale de la Femme,&nbsp;</span><span style=\"font-size: 1rem;\">qui se déroulera le samedi 9 mars à 18h (6 pm) .</span></p><p>Nous espérons que vous pourrez vous joindre à nous pour célébrer cette occasion&nbsp;<span style=\"font-size: 1rem;\">importante.&nbsp;</span>Nous sommes impatients de partager cette soirée mémorable avec vous.</p><p>NB : SAISISSEZ L\'OCCASION POUR EXPOSER VOS CRÉATIONS, BUSINESS, OEUVRES&nbsp;<span style=\"font-size: 1rem;\">LITTÉRAIRES, ARTISTIQUES, ETC...</span></p><p>Adresse: Four Points by Sheraton St. Catharines Niagara Suites, 3530 Schmon Pkwy,&nbsp;<span style=\"font-size: 1rem;\">Thorold, ON L2V 4Y6</span></p><p>Contact: 905 226-5282<br></p>', '<p>Dear Ladies</p><p>We\'re delighted to invite you to a very special evening in honor of International Women\'s Day, to be held on Saturday March 9 at 6 pm.</p><p><span style=\"font-size: 1rem;\">We hope you can join us to celebrate this important occasion. We look forward to sharing this memorable evening with you.</span></p><p>NB: TAKE THE OPPORTUNITY TO EXHIBIT YOUR CREATIONS, BUSINESS, LITERARY AND ARTISTIC WORKS, ETC...</p><p><span style=\"font-size: 1rem;\">Address: Four Points by Sheraton St. Catharines Niagara Suites, 3530 Schmon Pkwy, Thorold, ON L2V 4Y6</span><br></p><p><span style=\"font-size: 1rem;\">Contact: 905 226-5282</span></p>', '1709829140.png', '2024-03-09', '2024-03-09', '18:00:00', '06:00:00', 'journee-internationale-des-droits-des-femmes-tenue-de-soiree', '#28a745', '2024-03-07 16:33:04', '2024-03-07 15:33:04'),
(60, 'Démonstration de recettes du beignet Africain', 'African donut recipe demonstration', '<blockquote style=\"color: rgb(34, 34, 34); margin: 0cm 0cm 0cm 36pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-origin: initial; background-clip: initial; font-size: 11pt; font-family: Calibri, sans-serif;\" class=\"blockquote\"><p><span style=\"font-size: 16pt; font-family: Arial, sans-serif;\">Veuillez noter que&nbsp;:</span></p></blockquote><blockquote style=\"color: rgb(34, 34, 34); margin: 0cm 0cm 0cm 36pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-origin: initial; background-clip: initial; font-size: 11pt; font-family: Calibri, sans-serif;\" class=\"blockquote\"><p><span style=\"font-size: 16pt; font-family: Arial, sans-serif;\"><br></span><span style=\"font-size: 16pt; font-family: Arial, sans-serif;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-feature-settings: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><span style=\"font-size: 16pt; font-family: Arial, sans-serif;\">&nbsp;La première démonstration des recettes aura lieu le samedi 16 mars à 15h dans les cuisines Holy Trinity Church, situé au 77, Division Street, Welland.</span></p></blockquote>', '<blockquote class=\"blockquote\"><p><span style=\"font-family: Arial;\">Please note that :</span><br>1.&nbsp; &nbsp;The first recipe demonstration will take place on Saturday, March 16 at 3 p.m. in the Holy Trinity Church kitchens, located at 77 Division Street, Welland.</p></blockquote>', '1710771514.jpg', '2024-03-16', '2024-03-16', '15:14:00', '03:00:00', 'demonstration-de-recettes-du-beignet-africain', '#28a745', '2024-06-19 14:32:05', '2024-06-19 12:32:05'),
(62, 'Deuxième séance pratique du Beignet Africain', 'second practical session on African donut', '<div><font color=\"#222222\" face=\"Arial, Helvetica, sans-serif\" size=\"4\">Nous vous informons que notre espace de découverte et de partage culturels continue.</font></div><div><font color=\"#222222\" face=\"Arial, Helvetica, sans-serif\" size=\"4\">Nous avons notre deuxième séance pratique du \'\'Beignet Africain\'\' qui se tiendra le dimanche 05 mai 2024 à 14h dans les cuisines Holy Trinity Church de Welland.</font></div><div><font color=\"#222222\" face=\"Arial, Helvetica, sans-serif\" size=\"4\">Nous vous invitons à participer à la dégustation pour donner votre opinion.</font></div><div><font color=\"#222222\" face=\"Arial, Helvetica, sans-serif\" size=\"4\"><br></font></div><div><font color=\"#222222\" face=\"Arial, Helvetica, sans-serif\" size=\"4\">Adresse: Holy Trinity Church, situé au 77, Division Street, Welland.</font></div><div><font color=\"#222222\" face=\"Arial, Helvetica, sans-serif\" size=\"4\">Contact: 905 714 7333 / 905 226 5282</font></div>', '<p>Our space for cultural discovery and sharing continues.</p><p>We have our second hands-on session of the \'\'African donut\'\' to be held on Sunday May 05, 2024 at 2pm in the Holy Trinity Church kitchens in Welland.</p><p>We invite you to take part in the tasting and give your opinion.</p><p>Address: Holy Trinity Church, 77 Division Street, Welland.</p><p>Contact: 905 714 7333 / 905 226 5282</p>', '1713289555.jpg', '2024-05-05', '2024-05-05', '14:00:00', '02:00:00', 'deuxieme-seance-pratique-du-beignet-africain', '#28a745', '2024-06-19 14:37:41', '2024-06-19 12:37:41'),
(63, 'Sensibilisation à la nutrition saine; ateliers théoriques en mode virtuel.', 'Raising awareness of healthy nutrition ;  On line Workshops.', '<h4 style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"></h4><p><span style=\"font-size: 1rem; font-family: &quot;Source Sans Pro&quot;;\">Nous vous invitons à participer aux ateliers théoriques en mode virtuels, afin de s\'informer sur les meilleurs choix nutritionnels et se maintenir en bonne santé.</span></p><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 0.5rem; font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; line-height: 1.2; color: rgb(0, 0, 0); font-size: 1.25rem; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><span style=\"box-sizing: border-box; font-family: Arial; font-size: 12pt; text-align: left;\"><span style=\"font-family: &quot;Source Sans Pro&quot;;\">&nbsp;Voici le lien:&nbsp;</span><span style=\"box-sizing: border-box; font-family: &quot;Source Sans Pro&quot;;\"><span style=\"font-family: &quot;Source Sans Pro&quot;;\">https&nbsp;:</span><span style=\"font-family: &quot;Source Sans Pro&quot;;\">//sofifran.meet.markel.io/conf/call/2177266</span></span></span></p><h5><span style=\"font-family: Arial;\"></span></h5><h5><span style=\"font-family: Arial; font-size: 12pt; text-align: left;\"></span></h5><p class=\"MsoNormal\" style=\"margin-bottom:.25pt;line-height:115%\"><span style=\"font-size: 12pt; line-height: 115%; font-family: &quot;Calibri Light&quot;, sans-serif;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><br></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><span style=\"font-family: &quot;Calibri Light&quot;, sans-serif;\"><o:p></o:p></span></p>', '<h4 style=\"margin-bottom:.25pt;line-height:115%\"></h4><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem; color: inherit;\">We invite you to take part on line workshops, to learn about the best nutritional choices for maintaining good health.</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Here\'s the link:&nbsp;</span><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 12pt;\">https&nbsp;://sofifran.meet.markel.io/conf/call/2177266</span></p>', '1713377917.jpg', '2024-04-19', '2024-04-19', '18:30:00', '06:30:00', 'sensibilisation-a-la-nutrition', '#28a745', '2024-04-18 18:42:37', '2024-04-18 16:42:37');
INSERT INTO `ateliers` (`id`, `title_fr`, `title_en`, `description_fr`, `description_en`, `image`, `start`, `end`, `hour_start`, `hour_end`, `slug`, `color`, `created_at`, `updated_at`) VALUES
(64, 'Sensibilisation à la nutrition saine;  ateliers pratiques en cuisine.', 'Raising awareness of healthy nutrition; Hands-on cooking workshops.', '<p style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem; color: inherit;\">Nous vous invitons à participer aux ateliers pratiques de préparations d\'une soupe à base des légumes et d\'autres plats nutritionnels très bénéfiques pour le bien-être.</span></p><p style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><br></p><p style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><span style=\"color: rgb(34, 34, 34); font-family: &quot;Source Sans Pro&quot;; text-align: left;\">Lieu: Cuisine de l’église Holy Trinity Church</span></p><p style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><span style=\"color: rgb(34, 34, 34); font-family: &quot;Source Sans Pro&quot;; text-align: left;\">Heure: 16h</span></p><p style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><span style=\"color: rgb(34, 34, 34); font-family: &quot;Source Sans Pro&quot;; text-align: left;\">Adresse: 77 Division St, Welland, ON L3B 3Z8</span></p><p style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><span style=\"color: rgb(34, 34, 34); font-family: &quot;Source Sans Pro&quot;; text-align: left;\">Contact : 905 714 7333 / 905 226 5282</span><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem; color: inherit;\"><br></span></p>', '<p style=\"margin-bottom: 0cm; text-align: justify; line-height: normal;\"><span style=\"font-family: &quot;Source Sans Pro&quot;;\">We invite you to take part in hands on workshops to prepare a vegetable based soup and other nutritional dish that are highly beneficial to well being.</span></p><p style=\"margin-bottom: 0cm; text-align: justify; line-height: normal;\"><br></p><p style=\"margin-bottom: 0cm; text-align: justify; line-height: normal;\"><span style=\"color: rgb(34, 34, 34); font-family: &quot;Source Sans Pro&quot;; text-align: left;\">Location: Cuisine de l’église Holy Trinity Church</span></p><p style=\"margin-bottom: 0cm; text-align: justify; line-height: normal;\"><span style=\"color: rgb(34, 34, 34); font-family: &quot;Source Sans Pro&quot;; text-align: left;\">Time: 4 PM</span></p><p style=\"margin-bottom: 0cm; text-align: justify; line-height: normal;\"><span style=\"color: rgb(34, 34, 34); font-family: &quot;Source Sans Pro&quot;; text-align: left;\">Addresse: 77 Division St, Welland, ON L3B 3Z8</span></p><p style=\"margin-bottom: 0cm; text-align: justify; line-height: normal;\"><span style=\"color: rgb(34, 34, 34); font-family: &quot;Source Sans Pro&quot;; text-align: left;\">Contact : 905 714 7333 / 905 226 5282</span></p><p></p>', '1713383896.jpg', '2024-04-20', '2024-04-20', '16:00:00', '04:00:00', 'ateliers-pratiques-en-cuisine', '#28a745', '2024-04-18 18:32:09', '2024-04-18 16:32:09'),
