(72, 'Niagara Folk Arts Festival', 'Niagara Folk Arts Festival', '<div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><p class=\"MsoNormal\" style=\"text-align: left; margin-bottom: 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 14pt; font-family: Arial, sans-serif;\">SOFIFRAN vous\r\ninvite&nbsp;chaleureusement à venir célébrer la culture, le Folklore et les\r\ntraditions culinaires du Sénégal et des deux Congo.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: left; margin-bottom: 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 14pt; font-family: Arial, sans-serif;\">Ne manquez surtout\r\npas cette opportunité&nbsp;de divertissement original.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: left;\"><span style=\"font-size:14.0pt;line-height:107%\">&nbsp;</span></p></div>', '<p class=\"MsoNormal\"><span lang=\"EN-CA\" style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-ansi-language:EN-CA\">SOFIFRAN warmly invites\r\nyou to come and celebrate the culture, folklore and culinary traditions of\r\nSenegal and the two Congo.</span></p><p class=\"MsoNormal\"><span lang=\"EN-CA\" style=\"font-size: 14pt; line-height: 107%; font-family: Arial, sans-serif;\">Don\'t miss this\r\nopportunity for original entertainment</span><span lang=\"EN-CA\" style=\"font-size: 1rem;\">.</span></p>', '1715188956.jpg', '2024-05-18', '2024-05-18', '15:00:00', '03:00:00', 'niagara-folk-arts-festival-26129', '#28a745', '2024-05-08 17:35:21', '2024-05-08 15:35:21'),
(74, 'La fête des pères', 'Happy father\'s day', '<p><span style=\"font-size: 12pt; line-height: 106%; font-family: &quot;Source Sans Pro&quot;;\">Célébration des pères de la communauté, p</span><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 12pt;\">etite partie de football, disputée entre les papas et les jeunes.</span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;text-align:justify;line-height:\r\nnormal\"><span lang=\"EN-CA\" style=\"font-family: &quot;Source Sans Pro&quot;; color: rgb(34, 34, 34);\">Adresse:</span><span lang=\"EN-CA\" style=\"font-family:&quot;Calibri Light&quot;,sans-serif;mso-ascii-theme-font:\r\nmajor-latin;mso-hansi-theme-font:major-latin;mso-bidi-theme-font:major-latin;\r\nmso-ansi-language:EN-CA\"><span style=\"font-family: &quot;Source Sans Pro&quot;;\"> 405 Memorial Park Dr Pavillon # 1, Welland, ON L3B 1A5</span><span style=\"color:#222222\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:normal\">\r\n\r\n\r\n\r\n<span style=\"font-size: 12pt; line-height: 106%; font-family: &quot;Source Sans Pro&quot;;\">Contact\r\n905&nbsp;714 7333 / 905&nbsp;226 5282</span><br></p>', '<p>Celebration of fathers in the community, small soccer game played between dads and youngsters.</p><p>Address: 405 Memorial Park Dr Pavilion #5, Welland, ON L3B 1A5</p><p><span style=\"font-size: 1rem;\">Contact 905 714 7333 / 905 226 5282</span></p>', '1728505126.jpg', '2024-06-16', '2024-06-16', '15:00:00', '03:00:00', 'la-fete-des-peres', '#28a745', '2024-10-09 20:18:47', '2024-10-09 20:18:47'),
(75, 'Troisième séance pratique du Beignet Africain', 'Third practical session of the  African Donut', '<p>Nous vous informons que notre espace de découverte et de partage culturels continuent.</p><p>Nous avons notre troisième séance pratique du \'\'Beignet Africain\'\' qui se tiendra le samedi 08 juin 2024 à 14h dans les cuisines Holy Trinity Church de Welland.&nbsp;<span style=\"font-size: 1rem;\">Nous vous invitons à participer à la dégustation pour donner votre opinion.</span></p><p><span style=\"font-size: 1rem;\">Adresse: Holy Trinity Church, situé au 77, Division Street, Welland.</span><br></p><p>Contact: 905 714 7333 / 905 226 5282</p>', '<p><span style=\"font-size: 1rem;\">Our space for cultural discovery and sharing continues.</span><br></p><p>We have our third hands-on session of the \'\' African Donut\'\' to be held on Saturday, June 08, 2024 at 2pm in the Holy Trinity Church kitchens in Welland.&nbsp;<span style=\"font-size: 1rem;\">We invite you to take part in the tasting and give your opinion.</span></p><p>Address: Holy Trinity Church, 77 Division Street, Welland.</p><p>Contact: 905 714 7333 / 905 226 5282</p>', '1716904471.jpg', '2024-06-08', '2024-06-08', '14:00:00', '02:00:00', 'troisieme-seance-pratique-du-beignet-africain', '#28a745', '2024-06-19 14:34:45', '2024-06-19 12:34:45'),
(76, 'Démonstration de recettes du beignet Africain', 'African donut recipe demonstration', '<p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(97, 97, 97); font-family: Inter, sans-serif;\"><span style=\"font-size: 1rem; font-family: &quot;Source Sans Pro&quot;;\">Nous vous informons que notre dernière séance pratique du \'\'Beignet Africain\'\'&nbsp; se tient&nbsp; ce samedi 22 juin 2024 à 14h dans les cuisines Holy Trinity Church de Welland.&nbsp;</span><span style=\"font-size: 1rem; margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit; font-family: &quot;Source Sans Pro&quot;;\">Nous vous invitons à participer à la dégustation pour donner votre opinion.</span><br></p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(97, 97, 97); font-family: Inter, sans-serif;\"><span style=\"margin: 0px; padding: 0px; border: none; outline: none; font-size: 1rem; line-height: inherit; font-family: &quot;Source Sans Pro&quot;;\">Adresse: Holy Trinity Church, situé au 77, Division Street, Welland.</span><br style=\"margin: 0px; padding: 0px; border: none; outline: none; line-height: inherit;\"></p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; border: none; outline: none; line-height: inherit; color: rgb(97, 97, 97); font-family: Inter, sans-serif;\"><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Contact: 905 714 7333 / 905 226 5282</span></p>', '<p><font face=\"Source Sans Pro\">We\'d like to inform you that our final hands-on session of the \"African Donut\" takes place this Saturday, June 22, 2024 at 2pm in the Holy Trinity Church kitchens in Welland. We invite you to take part in the tasting and give your opinion.</font><br></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">Address: Holy Trinity Church, 77 Division Street, Welland.</span></p><p><span style=\"font-size: 1rem;\">Contact: 905 714 7333 / 905 226 5282</span><br></p>', '1718805710.jpg', '2024-06-22', '2024-06-22', '14:00:00', '02:00:00', 'demonstration-de-recettes-du-beignet-africain-36695', '#28a745', '2024-06-19 14:33:39', '2024-06-19 12:33:39'),
(79, 'VENEZ CELEBRER AVEC NOUS LA FETE DU CANADA', 'COME TO CELEBRATE WITH US CANADA DAY', '<p>Lundi, le 1er juillet 2024 à 13h</p><p>Welland Farmer\'s market</p><p>70 Young St, Welland, ON L3B 4C5</p>', '<p>Monday July 1st, 2024 at 1pm</p><p>Welland Farmer\'s market</p><p>70 Young St, Welland, ON&nbsp;<span style=\"font-size: 1rem;\">L3B 4C5</span></p>', '1718809127.jpg', '2024-07-01', '2024-07-01', '13:00:00', '01:00:00', 'venez-celebrer-avec-nous-la-fete-du-canada', '#28a745', '2024-06-19 15:00:30', '2024-06-19 13:00:30'),
(80, 'Assemblée Générale Annuelle (AGA)', 'Annual General Meeting', '<div style=\"color: rgb(101, 101, 101); font-family: Helvetica; font-size: 12px; text-align: center;\"><span style=\"font-size: 16px;\">SOFIFRAN vous invite à son Assemblée générale annuelle (AGA) qui aura lieu le dimanche 22 septembre 2024 à 15h (3 PM) en mode virtuel.</span></div><div style=\"color: rgb(101, 101, 101); font-family: Helvetica; font-size: 12px; text-align: center;\"><span style=\"font-size: 16px;\">Voici le raccourci du lien&nbsp;:&nbsp;&nbsp;</span><span style=\"color: rgb(17, 85, 204); font-family: &quot;Source Sans Pro&quot;, helvetica, arial, sans-serif; font-size: 15px; text-align: start; background-color: rgb(250, 250, 250);\"><a href=\"https://conference.sofifran/\" target=\"_blank\" data-saferedirecturl=\"https://www.google.com/url?q=https://conference.sofifran&amp;source=gmail&amp;ust=1726345142664000&amp;usg=AOvVaw1VNRtmmGLQQkZl5NT5M3kk\" style=\"color: rgb(17, 85, 204);\">https://conference.<wbr>sofifran</a>.</span><span style=\"color: rgb(17, 85, 204); font-family: &quot;Source Sans Pro&quot;, helvetica, arial, sans-serif; font-size: 15px; text-align: start; background-color: rgb(250, 250, 250);\">org</span><span style=\"font-size: 16px;\">&nbsp;</span></div>', '<p>SOFIFRAN invites you to its Annual General Meeting (AGM) to be held on Sunday 22 September 2024 at 3 pm (3 PM) in virtual mode.</p><p>Here is the shortcut to the link: https://conference.sofifran.org&nbsp;</p>', '1726259020.jpg', '2024-09-22', '2024-09-22', '15:00:00', '03:00:00', 'assemblee-generale-annuelle-aga', '#28a745', '2024-09-13 18:23:42', '2024-09-13 18:23:42'),
(81, 'Soirée Intergénérationnelle', 'Intergenerational evening', '<p class=\"MsoNormal\" style=\"margin-bottom:14.4pt;mso-para-margin-bottom:1.2gd\"><span style=\"font-family:&quot;Verdana&quot;,sans-serif\">SOFIFRAN en partenariat avec le CFOF\r\n(Centre franco-ontarien de folklore) vous invite une soirée inoubliable: \" Soirée Intergénérationnelle\"<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:14.4pt;mso-para-margin-bottom:1.2gd\"><span style=\"font-family:&quot;Verdana&quot;,sans-serif\">Venez profiter d\'un spectacle\r\nexceptionnel, « De notre foyer au vôtre », présenté par des artistes\r\nfranco-ontariens et immigrants francophones qui vous transporteront dans un\r\nunivers de talents et de cultures.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm\"><span style=\"font-family:&quot;Verdana&quot;,sans-serif\">Jeudi 28 novembre 2024 </span><span style=\"font-size:7.0pt;line-height:107%;\r\nfont-family:&quot;Verdana&quot;,sans-serif\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm\"><span style=\"font-family:&quot;Verdana&quot;,sans-serif\">De 17h à 21h&nbsp;&nbsp;<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm\"><span style=\"font-family:&quot;Verdana&quot;,sans-serif\">Paroisse Sacré-Cœur, 72 Empire St, Welland<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm\"><span style=\"font-family:&quot;Verdana&quot;,sans-serif\">Contact:\r\n905 714 7333 / 905 226 5282<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm\"><span style=\"font-family:&quot;Verdana&quot;,sans-serif\">&nbsp;</span></p><p class=\"MsoNormal\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"margin-bottom:14.4pt;mso-para-margin-bottom:1.2gd\"><span style=\"font-family:&quot;Verdana&quot;,sans-serif\">Ne manquez pas cette belle occasion de\r\ncréer des souvenirs ensemble !&nbsp;<o:p></o:p></span></p>', '<p><font face=\"Verdana\">SOFIFRAN in partnership with the CFOF (Centre franco-ontarien de folklore) invites you to an unforgettable evening: \"Intergenerational Evening\"</font><br></p><p><span style=\"font-family: Verdana;\">Come and enjoy an exceptional show, “De notre foyer au vôtre”, pressente by Franco-Ontarian and Francophone immigrant artists who will transport you into a world of talent and culture.</span></p><p><span style=\"font-family: Verdana;\">Thursday, November 28, 2024&nbsp;&nbsp;</span></p><p><span style=\"font-family: Verdana;\">Time: 5pm - 9pm&nbsp;&nbsp;</span></p><p><span style=\"font-family: Verdana; font-size: 1rem;\">Paroisse Sacré-Cœur, 72 Empire St, Welland</span></p><p><span style=\"font-family: Verdana;\">Contact: 905 714 7333 / 905 226 5282</span></p><p><span style=\"font-family: Verdana;\">Don\'t miss this great opportunity to create memories together!&nbsp;</span></p>', '1729522448.png', '2024-11-28', '2024-11-28', '17:00:00', '05:00:00', 'soiree-intergenerationnelle-25610', '#28a745', '2024-10-21 14:54:09', '2024-10-21 14:54:09'),
(82, 'Célébrons  ensemble le Réveillon', 'Celebrating New Year\'s Eve together', '<div style=\"text-align: center;\"><p class=\"MsoNormal\" style=\"text-align: left; margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><span style=\"text-align: center; font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\"><font face=\"Segoe UI, sans-serif\">Rejoignez-nous</font></span><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 13.5pt;\">&nbsp;pour une soirée exceptionnelle de reconnaissance et de festivités !</span></p><p class=\"MsoNormal\" style=\"text-align: left; margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><font face=\"Segoe UI, sans-serif\"><span style=\"font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\">Reconnaissance de nos bienfaiteurs et donateurs : Un moment spécial pour honorer ceux qui ont généreusement contribué à la réalisation de cet événement.</span></font></p><p class=\"MsoNormal\" style=\"text-align: left; margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><font face=\"Segoe UI, sans-serif\"><span style=\"font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\">Distribution de Cadeaux aux Enfants : Un instant magique pour illuminer les yeux de nos plus jeunes invités.</span></font></p><p class=\"MsoNormal\" style=\"text-align: left; margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><font face=\"Segoe UI, sans-serif\"><span style=\"font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\">Souper : préparé et présenté par les dames de la communauté</span></font></p><p class=\"MsoNormal\" style=\"text-align: left; margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><font face=\"Source Sans Pro\"><span style=\"font-size: 18px;\">Paroisse Sacré-Cœur,&nbsp;</span></font><span style=\"font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\">72 Empire St, Welland</span></p><p class=\"MsoNormal\" style=\"text-align: left; margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><span style=\"font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\">905 714 7333 / 905 226 5282</span></p><p class=\"MsoNormal\" style=\"text-align: left; margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><span style=\"font-family: &quot;Segoe UI&quot;, sans-serif; font-size: 13.5pt;\"></span><br></p></div><div style=\"text-align: center;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"></div>', '<p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Join us for an exceptional evening of recognition and festivities!</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Recognition of our benefactors and donors: A special moment to honour those who have generously contributed to making this event possible.</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Distribution of Gifts to the Children : A magical moment to light up the eyes of our youngest guests.</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Dinner : prepared and presented by the ladies of the community</span></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><font face=\"Source Sans Pro\"><span style=\"font-size: 18px;\">Paroisse Sacré-Cœur,&nbsp;</span></font><span style=\"font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\">72 Empire St, Welland</span></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 15pt; line-height: normal; border: none; padding: 0cm;\"><span style=\"font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\">905 714 7333 / 905 226 5282</span></p><div><span style=\"font-size: 18px; font-family: &quot;Source Sans Pro&quot;;\"><br></span></div>', '1734362908.jpg', '2024-12-21', '2024-12-21', '17:00:00', '05:00:00', 'celebrons-le-reveillon-avec-nous', '#28a745', '2024-12-16 15:28:29', '2024-12-16 15:28:29'),
(83, 'Des services francophones à Niagara', 'Francophone services in Niagara', '<p>Célébrons ensemble la Semaine Nationale de l\'Immigration Francophone</p><p>Des services Francophones à Niagara, nous sommes là</p><p>Merci de prendre en considération ces dates:&nbsp;</p><p>-Dimanche 3 novembre 2024&nbsp; à 9h</p><p>-Église Béthanie de Welland</p><p>-610 Ontario Road Welland, ON L3B 5C8</p>', '<p>Celebrating National Francophone Immigration Week Together</p><p>Francophone services in Niagara, we\'re here</p><p>Please bear these dates in mind:&nbsp;<br></p><p>-Sunday November 3 2024&nbsp; at 9 a.m.</p><p>-Bethany Church of Welland</p><p>-610 Ontario Road Welland, ON L3B 5C8</p>', '1730474081.PNG', '2024-11-03', '2024-11-03', '09:00:00', '09:00:00', 'des-services-francophones-du-niagara', '#28a745', '2024-11-01 15:25:42', '2024-11-01 15:25:42'),
(84, 'Festival FESTIV’ÉBÈNE 2025 : L\'événement culturel incontournable est de retour', 'FESTIV\'ÉBÈNE 2025 Festival: The must-see cultural event returns', '<div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Festival FESTIV’ÉBÈNE 2025 : L\'événement culturel incontournable est de retour !</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\"><br></font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">&nbsp; &nbsp; &nbsp; Exposition:&nbsp;&nbsp;<i>Afrique Éternelle : Passé, Présent, Futur</i>, un voyage visuel captivant, où chaque œuvre raconte une histoire profonde et célèbre la richesse des racines traditionnelles et culturelles africaines.</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Lieu : FirstOntarioPAC, 250 St. Paul St, St. Catharines ON&nbsp; L2R 3M2</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Date et heures : du 8 au 14 février, de 13h à 19h (1 PM - 7 PM)&nbsp;</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Vernissage : Samedi 8 février de 14h à 16h (2 PM - 4 PM). Artiste invité : Amadou Kiénou</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\"><br></font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">&nbsp; Soirée spectacle : musique et danse avec les groupes Klasik-O et Cloclo Clodel.</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Date et heures : Samedi 15 février à 18h (6 PM)</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Lieu : École secondaire catholique Saint-Jean-de-Brébeuf; 620, chemin River, Welland ON L3B 0A2</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Avec les plats succulents de la Table de Calixte.</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">&nbsp;</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Deux événements à ne pas manquer !</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">FESTIV’ÉBÈNE : Là où l’art et la culture prennent vie !</font></div>', '<p>FESTIV\'ÉBÈNE 2025 Festival: The not-to-be-missed cultural event is back!</p><p style=\"text-align: center; \">&nbsp; &nbsp;Exhibition: Eternal Africa: Past, Present, Future, a captivating visual journey, where each work tells a profound story and celebrates the richness of Africa\'s traditional and cultural roots.</p><p style=\"text-align: center; \">Location: FirstOntarioPAC, 250 St. Paul St, St. Catharines ON L2R 3M2</p><p style=\"text-align: center; \">Date and time: February 8 to 14, 1 pm to 7 pm (1 PM - 7 PM)&nbsp;</p><p style=\"text-align: center; \">Vernissage: Saturday, February 8, 2 pm to 4 pm (2 PM - 4 PM). Guest artist: Amadou Kiénou</p><p style=\"text-align: center; \"><span style=\"font-size: 1rem;\">&nbsp;Evening show: music and dance with the groups Klasik-O and Cloclo Clodel.</span><br></p><p style=\"text-align: center; \">Date and time: Saturday, February 15 at 6 PM (6 PM)</p><p style=\"text-align: center; \">Location: École secondaire catholique Saint-Jean-de-Brébeuf; 620 River Road, Welland ON L3B 0A2</p><p style=\"text-align: center; \">With delicious dishes from La Table de Calixte.</p><p style=\"text-align: center; \">Two events not to be missed!</p><p style=\"text-align: center; \">FESTIV\'ÉBÈNE: Where art and culture come alive!</p><p style=\"text-align: center; \"><br></p>', '1738076420.jpg', '2025-02-15', '2025-01-15', '18:00:00', '06:00:00', 'festival-festivebene-2025-levenement-culturel-incontournable-est-de-retour', '#28a745', '2025-01-28 15:01:58', '2025-01-28 15:01:58'),
(85, 'Invitation officielle au Vernissage Afrique Éternelle: Passé, Présent, Future', 'Official invitation to the Vernissage Eternal Africa: Past, Present, Future', '<div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Festival FESTIV’ÉBÈNE 2025 : L\'événement culturel incontournable est de retour !</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\"><br></font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">&nbsp; &nbsp; &nbsp; Exposition:&nbsp;&nbsp;<i>Afrique Éternelle : Passé, Présent, Futur</i>, un voyage visuel captivant, où chaque œuvre raconte une histoire profonde et célèbre la richesse des racines traditionnelles et culturelles africaines.</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Lieu : FirstOntarioPAC, 250 St. Paul St, St. Catharines ON&nbsp; L2R 3M2</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Date et heures : du 8 au 14 février, de 13h à 19h (1 PM - 7 PM)&nbsp;</font></div><div style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small; text-align: center;\"><font size=\"4\">Vernissage : Samedi 8 février de 14h à 16h (2 PM - 4 PM). Artiste invité : Amadou Kiénou</font></div>', '<p style=\"text-align: center; \">FESTIV\'ÉBÈNE 2025 Festival: The not-to-be-missed cultural event is back!</p><p style=\"text-align: center; \"><br></p><p style=\"text-align: center; \">&nbsp; &nbsp; &nbsp; Exhibition: Eternal Africa: Past, Present, Future, a captivating visual journey, where each work tells a profound story and celebrates the richness of Africa\'s traditional and cultural roots.</p><p style=\"text-align: center; \">Location: FirstOntarioPAC, 250 St. Paul St, St. Catharines ON L2R 3M2</p><p style=\"text-align: center; \">Date and time: February 8 to 14, 1 pm to 7 pm (1 PM - 7 PM)&nbsp;</p><p style=\"text-align: center; \">Vernissage: Saturday, February 8, 2 pm to 4 pm (2 PM - 4 PM). Guest artist: Amadou Kiénou</p>', '1738078257.jpg', '2025-02-08', '2025-01-08', '14:00:00', '02:00:00', 'invitation-officielle-au-vernissage-afrique-eternelle-passe-present-future', '#28a745', '2025-01-28 15:30:57', '2025-01-28 15:30:57');
INSERT INTO `ateliers` (`id`, `title_fr`, `title_en`, `description_fr`, `description_en`, `image`, `start`, `end`, `hour_start`, `hour_end`, `slug`, `color`, `created_at`, `updated_at`) VALUES
(86, 'C\'est MARS et le Salon du Livre des Francophonies du Niagara 2025 (SAFRAN 2025)', 'It\'s MARCH, and the Salon du Livre des Francophones du Niagara 2025 (SAFRAN 2025)', '<p class=\"MsoNormal\" style=\"margin-bottom:3.0pt\"><span lang=\"FR-CA\">C\'est MARS et\r\nle Salon du Livre des Francophonies du Niagara 2025 (SAFRAN 2025) approche à\r\ngrand pas</span></p><p class=\"MsoNormal\" style=\"margin-bottom:3.0pt\"><span lang=\"FR-CA\"><br></span><span style=\"font-size: 1rem;\">Voici\r\nun festival littéraire unique où la culture, l\'éveil et l\'expression\r\nfrancophone seront à l\'honneur.</span></p><p class=\"MsoNormal\" style=\"margin-bottom:3.0pt\"><span lang=\"FR-CA\">Au croisement\r\ndes imaginaires et des inspirations, le SAFRAN célèbre la puissance des lettres\r\nfrancophones.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:3.0pt\"><span lang=\"FR-CA\">Venez découvrir\r\nun espace ou chaque livre est une fenêtre ouverte sur le monde, chaque échange,\r\nune invitation au voyage.</span></p><p class=\"MsoNormal\" style=\"margin-bottom:3.0pt\"><br></p><p class=\"MsoNormal\" style=\"margin-bottom:3.0pt\"><span lang=\"FR-CA\">Réservez les dates!</span></p><p data-start=\"0\" data-end=\"18\"><span style=\"font-size: 1rem;\">- Le Safran – Salon du Livre des Francophonies du Niagara aura lieu du 20 au 23 mars 2025 à St. Catharines, Ontario.</span></p><p data-start=\"138\" data-end=\"236\">- Le lancement officiel se tiendra le 20 mars au FirstOntario Performing Arts Centre de 18h à 21h.</p><p class=\"MsoNormal\" style=\"margin-bottom:3.0pt\"><span lang=\"FR-CA\">\r\n\r\n\r\n</span></p><p data-start=\"238\" data-end=\"360\">- Les journées du 21, 22 et 23 mars se dérouleront à la Marilyn I. Walker School of Fine and Performing Arts de 10h à 18h.</p>', '<p class=\"MsoNormal\" style=\"margin-bottom:5.0pt\"><span lang=\"EN-CA\">It\'s MARCH, and the Salon du Livre des Francophones\r\ndu Niagara 2025 (SAFRAN 2025) is fast approaching...<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:5.0pt\"><span lang=\"EN-CA\"><font face=\"Segoe UI Emoji, sans-serif\">-&nbsp;</font>Here is a unique literary festival\r\nwhere culture, awakening, and Francophone expression will be in the spotlight.\r\nAt the crossroads of imaginations and inspirations, SAFRAN celebrates the power\r\nof Francophone literature. Come discover a space where each book is a window\r\nopen to the world, and each exchange is an invitation to travel.</span></p><p data-start=\"0\" data-end=\"18\"><br></p><p data-start=\"0\" data-end=\"18\">Save the dates !</p><p data-start=\"20\" data-end=\"136\">- Dates : March 20, 21, 22, 23, 2025 March </p><p data-start=\"20\" data-end=\"136\">– FirstOntario Performing Arts Centre, St. Catharines (Lancement Officiel), 6pm-9pm March 21, 22, 23 </p><p data-start=\"20\" data-end=\"136\">– Marilyn I. Walker School of Fine and Performing Arts, 10pm-6pm</p>', '1741368633.jpeg', '2025-03-20', '2025-03-23', '18:00:00', '21:00:00', 'cest-mars-et-le-salon-du-livre-des-francophonies-du-niagara-2025-safran-2025', '#28a745', '2025-03-07 17:30:33', '2025-03-07 17:30:33'),
(87, 'Célébrons les mamans', 'Celebrating moms', '<p>La tradition se poursuit : nous sommes ravies de vous inviter à notre célébration de la Fête des Mères, qui aura lieu le dimanche 11 mai à l’Hôtel de Ville de Welland, de 14h30 h à 18h00.</p><p>Ambiance musicale</p><p>Projection d’extraits du sitcom réalisé par Saïd Benyoucef, avec nos bénévoles, grâce au soutien de la Fondation Trillium de l’Ontario</p><p>Déclarations d’amour des enfants à leurs mamans</p><p>Et bien sûr… une surprise pour chaque maman inscrite !</p><p>&nbsp;Potluck : Merci à chaque participante d’apporter un plat à partager. Ce moment de convivialité repose sur votre générosité — pensez à indiquer le nom de votre plat lors de votre inscription pour éviter les doublons.</p><p>&nbsp;INSCRIPTION OBLIGATOIRE en contactant Sofifran:</p><p>Les cadeaux seront préparés uniquement pour les personnes inscrites.</p><p>Nous avons hâte de vivre ce beau moment avec vous!</p>', '<p>The tradition continues: we\'re delighted to invite you to our Mother\'s Day celebration on Sunday, May 11 at Welland City Hall, from 2:30 p.m. to 6:00 p.m.</p><p>Musical ambiance</p><p>Screening of excerpts from the sitcom directed by Saïd Benyoucef, with our volunteers, thanks to the support of the Ontario Trillium Foundation</p><p>Declarations of love from children to their moms</p><p>And of course... a surprise for every registered mom!</p><p> Potluck: Please bring a dish to share. This moment of conviviality relies on your generosity - remember to indicate the name of your dish when registering to avoid duplicates.</p><p> MANDATORY REGISTRATION by contacting Sofifran:</p><p>Gifts will be prepared only for those who register.</p><p>We look forward to sharing this wonderful moment with you!</p>', '1746146685.jpg', '2025-05-11', '2025-05-11', '14:00:00', '18:00:00', 'celebrons-les-mamans', '#dc3545', '2025-05-02 00:44:45', '2025-05-02 00:44:45'),
(88, 'Célébrons les pères', 'Celebrating fathers', '<p>La tradition se poursuit : nous sommes ravies de vous inviter à notre célébration de la Fête des pères, qui aura lieu le dimanche 16 Juin à l’Hôtel de Ville de Welland, de 14h30 h à 18h00.</p><p>Ambiance musicale</p><p>Projection d’extraits du sitcom réalisé par Saïd Benyoucef, avec nos bénévoles, grâce au soutien de la Fondation Trillium de l’Ontario</p><p>Déclarations d’amour des enfants à leurs mamans</p><p>Et bien sûr… une surprise pour chaque maman inscrite !</p><p>&nbsp;Potluck : Merci à chaque participante d’apporter un plat à partager. Ce moment de convivialité repose sur votre générosité — pensez à indiquer le nom de votre plat lors de votre inscription pour éviter les doublons.</p><p>&nbsp;INSCRIPTION OBLIGATOIRE en contactant Sofifran:</p><p>Les cadeaux seront préparés uniquement pour les personnes inscrites.</p><p>Nous avons hâte de vivre ce beau moment avec vous!</p>', '<p>The tradition continues: we\'re delighted to invite you to our Mother\'s Day celebration on Sunday, June 16 at Welland City Hall, from 2:30 p.m. to 6:00 p.m.</p><p>Musical ambiance</p><p>Screening of excerpts from the sitcom directed by Saïd Benyoucef, with our volunteers, thanks to the support of the Ontario Trillium Foundation</p><p>Declarations of love from children to their moms</p><p>And of course... a surprise for every registered mom!</p><p> Potluck: Please bring a dish to share. This moment of conviviality relies on your generosity - remember to indicate the name of your dish when registering to avoid duplicates.</p><p> MANDATORY REGISTRATION by contacting Sofifran:</p><p>Gifts will be prepared only for those who register.</p><p>We look forward to sharing this wonderful moment with you!</p>', 'peres.jpeg', '2025-06-15', '2025-06-15', '14:00:00', '18:00:00', 'celebrons-les-peres', '#dc3545', '2025-05-04 18:59:56', '2025-05-02 00:44:45'),
(90, 'Atelier sur le Mentorat', 'Mentorship Activity', '<p>Atelier dans le cadre du projet de garderie en milieu familial</p>', '<p>Atelier dans le cadre du projet de garderie en milieu familial</p>', NULL, '2025-10-21', '2025-10-21', '18:30:00', '19:30:00', 'atelier-sur-le-mentorat', '#007bff', '2025-10-15 14:25:56', '2025-10-15 14:25:56'),
(91, 'Projection du sitcom 2rives et dérives', 'Project of sitcom 2rives and dérives', 'Retrouvons-nous ce dimanche 2 novembre à 15h (3 pm), au City Hall de Welland, pour un après-midi&nbsp; convivial et inspirant placé sous La semaine Nationale de l’Immigration Francophone.&nbsp;<br><br>Le programme : Projection de la sitcom « 2 Rives et Dérives », un film original réalisé par Saïd Ben et interprété par des bénévoles de la communauté.<br><br>Une histoire à la fois drôle, touchante et inspirante, qui met en lumière les réalités de l’intégration et les défis vécus par les nouveaux arrivants au Canada.<br><br>Ambiance “comme au cinéma”, en collaboration avec La Table de Calixte — avec snacks et pop-corn pour agrémenter la rencontre !<br><br>Venez partager un moment de rires, d’émotions et de réflexion en célébrant la richesse de notre francophonie et la diversité qui la fait vivre.<br><br>&nbsp; &nbsp; &nbsp;Adresse: 60 E Main St, Welland, ON L3B 3W3<br><br><br><br>Entrée libre – Bienvenue à toutes et à tous !<br><br>Sofifran<br>8-165 Plymouth Rd, Welland<br>Welland (ON) L3B 3E1<br>Tél.&nbsp; : 905-714-7333 - Cel. 905-226-5282<br>Site Web&nbsp; &nbsp; www.sofifran.org', 'Retrouvons-nous ce dimanche 2 novembre à 15h (3 pm), au City Hall de Welland, pour un après-midi&nbsp; convivial et inspirant placé sous La semaine Nationale de l’Immigration Francophone.&nbsp;<br><br>Le programme : Projection de la sitcom « 2 Rives et Dérives », un film original réalisé par Saïd Ben et interprété par des bénévoles de la communauté.<br><br>Une histoire à la fois drôle, touchante et inspirante, qui met en lumière les réalités de l’intégration et les défis vécus par les nouveaux arrivants au Canada.<br><br>Ambiance “comme au cinéma”, en collaboration avec La Table de Calixte — avec snacks et pop-corn pour agrémenter la rencontre !<br><br>Venez partager un moment de rires, d’émotions et de réflexion en célébrant la richesse de notre francophonie et la diversité qui la fait vivre.<br><br>&nbsp; &nbsp; &nbsp;Adresse: 60 E Main St, Welland, ON L3B 3W3<br><br><br><br>Entrée libre – Bienvenue à toutes et à tous !<br><br>Sofifran<br>8-165 Plymouth Rd, Welland<br>Welland (ON) L3B 3E1<br>Tél.&nbsp; : 905-714-7333 - Cel. 905-226-5282<br>Site Web&nbsp; &nbsp; www.sofifran.org', '1761615219_69001d7396817.jpg', '2025-11-02', '2025-11-02', '15:00:00', '17:00:00', 'projection-du-sitcom-2rives-et-derives', '#dc3545', '2025-10-28 02:07:43', '2025-10-28 02:07:43'),
(92, 'Réveillon et soirée intergénérationnelle', 'Réveillon et soirée intergénérationnelle', '<p>Réveillon et soirée intergénérationnelle</p>', '<p>Réveillon et soirée intergénérationnelle</p>', NULL, '2025-12-13', '2025-12-13', '17:00:00', '23:00:00', 'reveillon-et-soiree-intergenerationnelle', '#dc3545', '2025-11-25 15:45:15', '2025-11-25 15:45:15'),
(93, 'Préparez-vous pour une soirée inoubliable !', 'Get ready for an unforgettable evening!', '<p>Nous vous invitons à vivre un moment haut en couleurs lors de notre grand Réveillon intergénérationnel, le samedi 13 décembre dès 17h30,&nbsp;<br><br>à la salle paroissiale Sacré-Cœur, 72 Empire St, Welland.<br><br>Au programme : rires, rencontres, chaleur humaine et traditions partagées !<br>Une occasion unique de rassembler petits et grands, jeunes et moins jeunes, pour célébrer ensemble dans une ambiance festive,&nbsp;<br>joyeuse et pleine d’énergie !<br>Rejoignez-nous pour écrire ensemble de merveilleux souvenirs, veuillez confirmer votre présence!</p>', '<p>We invite you to experience a vibrant and colorful moment at our grand intergenerational New Year’s Eve celebration on Saturday, December 13, from 5:30 PM, at the Sacré-Cœur parish hall, 72 Empire St, Welland.<br><br>On the program: laughter, meeting new people, warmth, and shared traditions!<br>A unique opportunity to bring together young and old, children and adults, to celebrate together in a festive, joyful, and energetic atmosphere!<br>Join us to create wonderful memories together, please confirm your attendance!</p>', '1764694091_692f184bb2eb0.jpeg', '2025-12-13', '2025-12-13', '17:30:00', '17:30:00', 'preparez-vous-pour-une-soiree-inoubliable', '#dc3545', '2025-12-02 16:48:11', '2025-12-02 16:48:11'),
(94, 'Du 5 au 28 février 2026 – Un mois de célébration dans la région du Niagara', 'Du 5 au 28 février 2026 – Un mois de célébration dans la région du Niagara', '<p>SOFIFRAN vous donne rendez-vous du 5 au 28 février 2026 pour Festiv’Ébène 2026 – Racines et Résonances, un festival dédié à la valorisation des cultures afrodescendantes, à la mémoire collective et à la francophonie plurielle.</p>', '<p>SOFIFRAN vous donne rendez-vous du 5 au 28 février 2026 pour Festiv’Ébène 2026 – Racines et Résonances, un festival dédié à la valorisation des cultures afrodescendantes, à la mémoire collective et à la francophonie plurielle.</p>', '1771068231_69905b47609bb.jpg', '2026-02-05', '2026-02-28', '09:12:00', '10:20:00', 'du-5-au-28-fevrier-2026-un-mois-de-celebration-dans-la-region-du-niagara', '#dc3545', '2026-02-14 11:23:51', '2026-02-14 11:23:51'),
(95, 'Racine et Résonances', 'Racine et Résonances', 'Racines et Résonances<br>Journée d’exposés et d’échanges mettant en lumière l’histoire des communautés noires, de l’Afrique précoloniale au Canada, ainsi que les contributions et figures marquantes de la diaspora canadienne.<br><br>- Vendredi 6 février 2026<br>- École catholique St-Jean-de-Brébeuf, 620 River Rd, Welland (Ontario) L3B 5N4<br>- Toute la journée<br>- Professeur Amadou Ba', '<p>Roots and Resonances</p><p>A day of presentations and discussions highlighting the history of Black communities, from pre-colonial Africa to Canada, as well as the contributions and notable figures of the Canadian diaspora.</p><p>- Friday, February 6, 2026<br>- St. Jean de Brébeuf Catholic School, 620 River Rd, Welland, Ontario L3B 5N4<br>- All day<br>- Professor Amadou Ba</p>', '1770451113_6986f0a92d14d.jpeg', '2026-02-06', '2026-02-07', '07:20:00', '19:30:00', 'decouverte-expose', '#ffc107', '2026-02-07 08:14:55', '2026-02-07 08:14:55'),
(96, 'Cinéma', 'Cinéma', '<p>Célébration du centenaire de Frantz Fanon, en collaboration avec l’Université Brock</p>', '<p>Célébration du centenaire de Frantz Fanon, en collaboration avec l’Université Brock</p>', NULL, '2026-02-13', '2026-02-13', '17:00:00', '22:00:00', 'cinema', '#dc3545', '2026-01-17 22:30:09', '2026-01-17 22:30:09'),
(97, 'Exposition', 'Exposition', 'Dans le cadre de Festiv’Ébène 2026 et du Mois de l’Histoire des Noirs / Mois du Patrimoine Africain, SOFIFRAN s’associe au Centre for Studies in Arts and Culture (STAC) pour présenter l’exposition :<br><br>Voix du milieu / Voices in-between :<br>La francophonie plurielle du Niagara<br><br>- 13 au 28 février 2026<br>- Museum in the Hallway<br>Marilyn I. Walker School of Fine and Performing Arts<br>(2e étage, près de l’entrée du théâtre et à divers emplacements dans l’école)<br><br>Cette exposition rassemble une sélection de petites sculptures, d’images et d’objets issus de la culture matérielle, provenant de l’exposition Eternal Africa – Past, Present, Future (FirstOntario Performing Arts Centre, 2025), ainsi que des collections privées de Nafée Nelly Faigou (St. Catharines) et Fété Ngira-Batwaré Kimpiobi (Welland).<br><br>À travers ces œuvres installées dans différents espaces de la Marilyn I. Walker School of Fine and Performing Arts, l’exposition célèbre la richesse, la diversité et la pluralité des voix francophones noires de la région du Niagara.<br><br>L’exposition est commissariée par David Vivian et Nafée Nelly Faigou, avec la généreuse collaboration de la galerie du Département des arts visuels de la MIWSFPA.<br><br>L\'exposition se poursuivra en mars afin de mettre en valeur les activités récentes du Salon du livre SAFRAN – Salon des Francophonies du Niagara.<br>L’édition 2026 du Salon du livre est prévue le 21 mars 2026 au Niagara Artists Centre.<br><br>- Événement gratuit et ouvert au public<br><br>- <a href=\"brocku.ca/stac\" target=\"_blank\">brocku.ca/stac</a>', 'Dans le cadre de Festiv’Ébène 2026 et du Mois de l’Histoire des Noirs / \r\nMois du Patrimoine Africain, SOFIFRAN s’associe au Centre for Studies in\r\n Arts and Culture (STAC) pour présenter l’exposition :<br><br>Voix du milieu / Voices in-between :<br>La francophonie plurielle du Niagara<br><br>- 13 au 28 février 2026<br>- Museum in the Hallway<br>Marilyn I. Walker School of Fine and Performing Arts<br>(2e étage, près de l’entrée du théâtre et à divers emplacements dans l’école)<br><br>Cette\r\n exposition rassemble une sélection de petites sculptures, d’images et \r\nd’objets issus de la culture matérielle, provenant de l’exposition \r\nEternal Africa – Past, Present, Future (FirstOntario Performing Arts \r\nCentre, 2025), ainsi que des collections privées de Nafée Nelly Faigou \r\n(St. Catharines) et Fété Ngira-Batwaré Kimpiobi (Welland).<br><br>À \r\ntravers ces œuvres installées dans différents espaces de la Marilyn I. \r\nWalker School of Fine and Performing Arts, l’exposition célèbre la \r\nrichesse, la diversité et la pluralité des voix francophones noires de \r\nla région du Niagara.<br><br>L’exposition est commissariée par David \r\nVivian et Nafée Nelly Faigou, avec la généreuse collaboration de la \r\ngalerie du Département des arts visuels de la MIWSFPA.<br><br>L\'exposition\r\n se poursuivra en mars afin de mettre en valeur les activités récentes \r\ndu Salon du livre SAFRAN – Salon des Francophonies du Niagara.<br>L’édition 2026 du Salon du livre est prévue le 21 mars 2026 au Niagara Artists Centre.<br><br>- Événement gratuit et ouvert au public<br><br>- <a href=\"brocku.ca/stac\" target=\"_blank\">brocku.ca/stac</a>', '1771068108_69905accb3b2f.jpg', '2026-02-13', '2026-02-28', '10:00:00', '22:00:00', 'exposition', '#dc3545', '2026-02-14 11:21:48', '2026-02-14 11:21:48'),
(98, 'Soirée de Gala du Festiv’Ébène 2026', 'Soirée de Gala du Festiv’Ébène 2026', 'Racines et Résonances<br>Journée d’exposés et d’échanges mettant en lumière l’histoire des communautés noires, de l’Afrique précoloniale au Canada, ainsi que les contributions et figures marquantes de la diaspora canadienne.<br><br>- Vendredi 6 février 2026<br>- École catholique St-Jean-de-Brébeuf, 620 River Rd, Welland (Ontario) L3B 5N4<br>- Toute la journée<br>- Professeur Amadou Ba', 'Racines et Résonances<br>Journée d’exposés et d’échanges mettant en \r\nlumière l’histoire des communautés noires, de l’Afrique précoloniale au \r\nCanada, ainsi que les contributions et figures marquantes de la diaspora\r\n canadienne.<br><br>- Vendredi 6 février 2026<br>- École catholique St-Jean-de-Brébeuf, 620 River Rd, Welland (Ontario) L3B 5N4<br>- Toute la journée<br>- Professeur Amadou Ba', '1771068177_69905b112c20e.jpg', '2026-02-28', '2026-02-28', '17:00:00', '22:00:00', 'soiree-de-gala-du-festivebene-2026', '#dc3545', '2026-02-14 11:22:57', '2026-02-14 11:22:57'),
(99, 'Forum des Femmes Entrepreneures du Niagara', 'Niagara Women Entrepreneurs Forum', '<p>Vous êtes une femme entrepreneure ou vous rêvez de lancer votre entreprise ?<br>Ne manquez pas le Forum des Femmes Entrepreneures du Niagara, un événement virtuel inspirant qui rassemble des femmes leaders, des expertes et des entrepreneures passionnées prêtes à partager leur expérience et leurs conseils pour réussir.<br><br>Organisé par SOFIFRAN, ce forum est une occasion unique de vous inspirer, apprendre et développer votre réseau dans un environnement dynamique et motivant.<br><br>Au programme, des échanges authentiques sur les réalités de l’entrepreneuriat, l’accès au financement, les stratégies de marketing et l’importance du bien-être et de la résilience pour bâtir une entreprise solide et durable.<br><br>Ce que vous allez découvrir<br><br>- Des histoires inspirantes de femmes entrepreneures qui ont transformé les défis en opportunités<br>- Des conseils concrets pour accéder au financement et développer votre entreprise<br>- Des stratégies de marketing et de positionnement pour faire grandir votre projet<br>- Une session pratique pour élaborer votre plan d’affaires et passer de l’idée à l’action<br><br>Panélistes<br><br>Susan Morin<br>Accès au financement et modèle Venture Niagara<br><br>Carelle Lahouri<br>Parcours d’entrepreneure : des obstacles à l’excellence<br><br>Rhodie Lamour<br>Marketing, bien-être et résilience<br><br>Atelier spécial<br><br>Les experts de Innovative Consultants vous accompagneront dans une session dédiée à la création d’un plan d’affaires inspiré des panels, afin de transformer les apprentissages du forum en actions concrètes pour votre projet.<br><br>Informations sur l’événement<br><br>Date : Vendredi 13 mars<br>Heure : 13h – 16h (1pm – 4pm)<br>Format : En mode virtuel<br><br>Réservez votre place dès maintenant<br><br>Joignez-vous à cette rencontre unique de femmes ambitieuses qui souhaitent apprendre, se connecter et faire grandir leur vision entrepreneuriale.<br><br>Informations<br><br>- 905-714-7333<br>- 905-226-5282<br><br>Cet événement est rendu possible grâce au soutien de la Fondation canadienne des femmes.</p>', '<p>Are you a female entrepreneur or dreaming of starting your own business?</p><p>Don\'t miss the Niagara Women Entrepreneurs Forum, an inspiring virtual event that brings together female leaders, experts, and passionate entrepreneurs ready to share their experiences and advice for success.</p><p>Organized by SOFIFRAN, this forum is a unique opportunity to be inspired, learn, and grow your network in a dynamic and motivating environment.</p><p>The program includes authentic discussions on the realities of entrepreneurship, access to financing, marketing strategies, and the importance of well-being and resilience in building a strong and sustainable business.</p><p>What you will discover</p><p>- Inspiring stories from women entrepreneurs who have turned challenges into opportunities</p><p>- Concrete advice on accessing financing and growing your business<br>- Marketing and positioning strategies to grow your project<br>- A practical session to develop your business plan and move from idea to action</p><p>Panelists</p><p>Susan Morin<br>Access to Financing and Venture Niagara Model</p><p>Carelle Lahouri<br>Entrepreneurial journey: from obstacles to excellence</p><p><br></p><p>Rhodie Lamour<br>Marketing, well-being, and resilience</p><p>Special workshop</p><p>Experts from Innovative Consultants will guide you through a session dedicated to creating a business plan inspired by the panels, in order to transform the forum\'s lessons into concrete actions.</p><br><p>Event Information</p><p>Date: Friday, March 13<br>Time: 1 p.m. – 4 p.m.<br>Format: Virtual</p><p>Reserve your spot now</p><p>Join this unique gathering of ambitious women who want to learn, connect, and grow their entrepreneurial vision.</p><p>Information</p><p>- 905-714-7333<br>- 905-226-5282</p><p>This event is made possible thanks to the support of the Canadian Women\'s Foundation.</p>', '1772835074_69ab5102cc27d.jpg', '2026-03-13', '2026-03-13', '13:00:00', '18:00:00', 'forum-des-femmes-entrepreneures-du-niagara', '#dc3545', '2026-03-06 22:11:14', '2026-03-06 22:11:14'),
(100, 'Salon du livre des francophonies du Niagara', 'Salon du livre des francophonies du Niagara', '<p>Salon du livre des francophonies du Niagara<br><br>Voix du milieu : « mots dits, mots en balades »<br><br>SOFIFRAN vous invite au Salon du livre des francophonies du Niagara, un événement culturel qui célèbre la richesse de la création et de l’expression francophones dans la région.<br><br>21 mars 2026<br>Niagara Artists Centre<br>354 St. Paul St, St. Catharines, ON<br><br>Cette journée mettra à l’honneur la parole, l’écriture et les arts à travers une programmation variée comprenant tables rondes, lectures-spectacle et rencontres artistiques. Les participants auront également l’occasion de découvrir différentes formes d’expression culturelle telles que la peinture, le cinéma, le théâtre et la musique.<br><br>Le Salon du livre des francophonies du Niagara se veut un espace de rencontre, de dialogue et de créativité, réunissant artistes, auteurs et membres de la communauté autour de la vitalité de la francophonie</p>', '<p>Niagara Francophone Book Fair</p><p>Voices from the Community: “Spoken Words, Words on the Move”</p><p>SOFIFRAN invites you to the Niagara Francophone Book Fair, a cultural event celebrating the richness of Francophone creativity and expression in the region.</p><p>March 21, 2026<br>Niagara Artists Centre<br>354 St. Paul St, St. Catharines, ON</p><p>This day will highlight speech, writing, and the arts through a diverse program featuring panel discussions, staged readings, and artistic encounters. Participants will also have the opportunity to discover various forms of cultural expression such as painting, film, theater, and music.</p><p>The Niagara Francophone Book Fair aims to be a space for gathering, dialogue, and creativity, bringing together artists, authors, and community members around the vitality of the Francophone community.</p>', '1773667790_69b805ce0f098.jpg', '2026-03-21', '2026-03-21', '08:00:00', '18:00:00', 'salon-du-livre-des-francophonies-du-niagara', '#dc3545', '2026-03-16 13:29:50', '2026-03-16 13:29:50'),
(101, 'Fête des Mères 2026. Une célébration pleine d’amour', 'Fête des Mères 2026. Une célébration pleine d’amour', '<p><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Fête des Mères 2026. Une célébration pleine d’amour\r\n\r\nÀ l’occasion de la Fête des Mères, SOFIFRAN vous invite à un événement spécial dédié à honorer et célébrer les mamans.\r\n\r\nCette journée sera un moment unique de partage, de convivialité et d’inspiration, dans une ambiance chaleureuse et familiale.\r\n\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Au programme\r\nUn potluck pour partager un bon repas ensemble\r\nUne ambiance musicale animée par DJ Donlymix\r\nUne mini-conférence sur la gestion des finances présentée par Arnelle TCHAKO, conseillère en assurances et investissements\r\nDes moments de connexion, de célébration et de reconnaissance envers les mamans\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Informations pratiques\r\n\r\nDate : 10 mai 2026\r\nHeure : 14h à 18h (2pm – 6pm)\r\nLieu : Paroisse Sacré Cœur (Sacred Heart Church)\r\n72 Empire St, Welland, ON L3B 2L4\r\n\r\nContact : +1 (905) 226-5282\r\n\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Pourquoi participer ?\r\n\r\nParce que chaque maman mérite d’être célébrée, honorée et entourée d’amour. Cet événement est une occasion parfaite pour renforcer les liens familiaux et communautaires.\r\n\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Venez nombreux avec vos proches et célébrons ensemble celles qui comptent le plus.</span></p>', '<p><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Fête des Mères 2026. Une célébration pleine d’amour\r\n\r\nÀ l’occasion de la Fête des Mères, SOFIFRAN vous invite à un événement spécial dédié à honorer et célébrer les mamans.\r\n\r\nCette journée sera un moment unique de partage, de convivialité et d’inspiration, dans une ambiance chaleureuse et familiale.\r\n\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Au programme\r\nUn potluck pour partager un bon repas ensemble\r\nUne ambiance musicale animée par DJ Donlymix\r\nUne mini-conférence sur la gestion des finances présentée par Arnelle TCHAKO, conseillère en assurances et investissements\r\nDes moments de connexion, de célébration et de reconnaissance envers les mamans\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Informations pratiques\r\n\r\nDate : 10 mai 2026\r\nHeure : 14h à 18h (2pm – 6pm)\r\nLieu : Paroisse Sacré Cœur (Sacred Heart Church)\r\n72 Empire St, Welland, ON L3B 2L4\r\n\r\nContact : +1 (905) 226-5282\r\n\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Pourquoi participer ?\r\n\r\nParce que chaque maman mérite d’être célébrée, honorée et entourée d’amour. Cet événement est une occasion parfaite pour renforcer les liens familiaux et communautaires.\r\n\r\n</span><span style=\"color: rgb(0, 0, 0); font-family: Roboto, -apple-system, &quot;apple color emoji&quot;, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen-Sans, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: pre-wrap; background-color: rgb(227, 254, 224); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Venez nombreux avec vos proches et célébrons ensemble celles qui comptent le plus.</span></p><p><br></p>', '1777558641_69f3647184c9e.jfif', '2026-05-10', '2026-05-10', '14:00:00', '18:00:00', 'fete-des-meres-2026-une-celebration-pleine-damour', '#dc3545', '2026-04-30 14:17:21', '2026-04-30 14:17:21'),
(102, 'OPEN HOUSE – NIAGARA FOLK ARTS FESTIVAL 2026. Une célébration vivante des cultures !', 'OPEN HOUSE – NIAGARA FOLK ARTS FESTIVAL 2026. A vibrant celebration of cultures!', '<p>Le dimanche 24 mai 2026, SOFIFRAN vous ouvre ses portes pour une expérience culturelle immersive unique au Niagara Folk Arts Festival.<br><br>Au programme. une explosion de couleurs, de sons et de saveurs qui vous feront voyager à travers les cultures du monde.<br><br>- Temps forts de l’événement : Performance live de l’artiste invité : Ensemble Kouraba Foli, avec des percussionnistes qui feront vibrer l’ambiance<br>- Défilé culturel exclusif présenté par l’ambassadrice de SOFIFRAN<br>- Découverte gastronomique avec des plats authentiques d’Haïti et de Côte d’Ivoire<br>-&nbsp; Open House, un moment convivial pour découvrir, échanger et célébrer ensemble<br><br>Un moment unique pour célébrer nos cultures, partager nos traditions et créer des souvenirs inoubliables.<br><br>- Lieu : 100 Garnet Street, St. Catharines<br>- Date : Dimanche 24 mai 2026<br>- Heure : 16h à 20h</p>', '<p>On Sunday, May 24, 2026, SOFIFRAN opens its doors to you for a unique immersive cultural experience at the Niagara Folk Arts Festival.</p><p>On the program: an explosion of colors, sounds, and flavors that will take you on a journey through the cultures of the world.</p><p>- Event highlights: Live performance by the guest artist: Ensemble Kouraba Foli, with percussionists who will get the crowd moving<br>- Exclusive cultural parade presented by the SOFIFRAN ambassador<br>- Culinary discovery featuring authentic dishes from Haiti and Côte d’Ivoire<br>- Open House, a friendly gathering to discover, connect, and celebrate together</p><p>A unique opportunity to celebrate our cultures, share our traditions, and create unforgettable memories.</p><p>- Location: 100 Garnet Street, St. Catharines<br>- Date: Sunday, May 24, 2026<br>- Time: 4:00 PM to 8:00 PM</p><p><br></p>', '1778769264_6a05dd70eba79.jpg', '2026-05-24', '2026-05-24', '16:00:00', '20:00:00', 'open-house-niagara-folk-arts-festival-2026-une-celebration-vivante-des-cultures', '#dc3545', '2026-05-14 14:34:25', '2026-05-14 14:34:25'),
(103, 'La Journée canadienne du multiculturalisme 2026 : une célébration de la diversité à Welland', 'Canadian Multiculturalism Day 2026: A Celebration of Diversity in Welland', '<p>SOFIFRAN a le plaisir d\'inviter la population de Welland, du Niagara et des régions environnantes à participer à la Journée canadienne du multiculturalisme, qui se tiendra le dimanche 28 juin 2026, de 13 h à 19 h, au Farmer\'s Market Square de Welland.</p><p>Cette célébration vise à mettre en valeur la richesse culturelle qui compose le tissu social canadien. À travers la musique, la gastronomie, les échanges interculturels et les activités familiales, l\'événement offrira une occasion unique de découvrir et d\'apprécier les traditions provenant des différentes communautés qui contribuent au dynamisme de notre société.</p><p>Les visiteurs pourront profiter d\'un buffet international, assister à des prestations artistiques et participer à diverses activités favorisant le rapprochement entre les cultures. Les enfants ne seront pas en reste grâce aux jeux gonflables et au maquillage artistique (face painting) prévus spécialement pour eux.</p><p>L\'événement accueillera également l\'artiste invité Amadou Kiénou, reconnu pour son talent exceptionnel et son engagement dans la promotion des cultures africaines.</p><p>Informations pratiques :</p><p>- Date : Dimanche 28 juin 2026<br><span style=\"font-size: 1rem;\">- Heure : 13 h à 19 h<br></span><span style=\"font-size: 1rem;\">- Lieu : Farmer\'s Market Square, 70 Young Street, Welland (Ontario)<br></span><span style=\"font-size: 1rem;\">- Entrée : Gratuite</span></p><p>Nous vous attendons nombreux pour célébrer ensemble la diversité, le vivre-ensemble et les valeurs de partage qui font la richesse du Canada.</p>', '<p>SOFIFRAN is pleased to invite the residents of Welland, Niagara, and the surrounding areas to participate in Canadian Multiculturalism Day, which will take place on Sunday, June 28, 2026, from 1:00 p.m. to 7:00 p.m., at Farmer’s Market Square in Welland.</p><p>This celebration aims to highlight the cultural richness that makes up the fabric of Canadian society. Through music, food, intercultural exchanges, and family-friendly activities, the event will offer a unique opportunity to discover and appreciate the traditions of the diverse communities that contribute to the vibrancy of our society.</p><p>Visitors will be able to enjoy an international buffet, watch artistic performances, and participate in various activities that foster cultural exchange. Children will not be left out, thanks to inflatable games and face painting planned especially for them.</p><p>The event will also feature guest artist Amadou Kiénou, renowned for his exceptional talent and his commitment to promoting African cultures.</p><p>Practical Information:</p><p>- Date: Sunday, June 28, 2026<br><span style=\"font-size: 1rem;\">- Time: 1:00 PM to 7:00 PM<br></span><span style=\"font-size: 1rem;\">- Location: Farmer’s Market Square, 70 Young Street, Welland, Ontario<br></span><span style=\"font-size: 1rem;\">- Admission: Free</span></p><p>We look forward to seeing many of you there to celebrate together the diversity, community spirit, and values of sharing that make Canada so rich.</p>', '1781728202_6a3303cab702e.jpg', '2026-06-28', '2026-06-28', '01:00:00', '07:00:00', 'la-journee-canadienne-du-multiculturalisme-2026-une-celebration-de-la-diversite-a-welland', '#dc3545', '2026-06-17 20:30:02', '2026-06-17 20:30:02');
INSERT INTO `axe_interventions` (`id`, `titre_en`, `titre_fr`, `contenu_en`, `contenu_fr`, `created_at`, `updated_at`) VALUES
(1, 'Areas intervention', 'Axes d\'interventions', '<h3>AXE I : les jeunes noirs à risque</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Accompagner les jeunes noirs à risque dans leur reconstruction identitaire afin de retrouver leurs valeurs, leur culture et la fierté de leur identité noire </li>\r\n              <li>Objectif 2 : Accompagner les jeunes noirs à risque pour empêcher qu’il ne bascule dans la délinquance juvénile et la criminalité ; </li>\r\n              <li>Objectif 3 : Accompagner les jeunes noirs à risque en prise avec le système pénal pour les aider à réintégrer avec succès la société canadienne;</li>\r\n              <li>Objectif 4 : Sensibiliser les jeunes de la communauté noire sur la crise croissante de la santé mentale et de l\'abus de substances psychoactives. </li>\r\n          </ul>\r\n\r\n          <h3>AXE II : les familles des jeunes noirs à risque</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Accompagner les familles des jeunes noirs à risque dans la médiation et la reconstruction du noyau familial ;</li>\r\n              <li>Objectif 2 : Accompagner les familles à comprendre le système pénal </li>\r\n              <li>Objectif 3 : accompagner les familles dans la réhabilitation et la réinsertion de leurs jeunes dans la société canadienne</li>\r\n          </ul>\r\n\r\n          <h3>AXE III : Le système éducatif</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Soutenir le système éducatif pour prévenir la stigmatisation, le racisme et la discrimination, en leur donnant des ressources et approches culturellement sensibles.</li>\r\n              <li>Objectif 2 : Jouer un rôle de médiateur entre les institutions éducatives et les jeunes afin d’éviter qu’il se retrouve dans le système pénal et décroche dans leurs études secondaires</li>\r\n              <li>Objectif 3 : Maintenir et restaurer le dialogue entre les familles et le système éducatif</li>\r\n          </ul>\r\n\r\n          <h3>AXE IV : La communauté</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Accompagner les communautés pour prévenir les stigmatisations envers les jeunes noirs à risque et favoriser la compassion</li>\r\n          </ul>\r\n\r\n          <h3>AXE V : Le système pénal</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Changer les attitudes et les stigmas vis-à-vis des jeunes noirs à risque afin d’éviter qu’ils se retrouvent dans le système pénal avec des charges mineures</li>\r\n          </ul>', '<h3>AXE I : les jeunes noirs à risque</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Accompagner les jeunes noirs à risque dans leur reconstruction identitaire afin de retrouver leurs valeurs, leur culture et la fierté de leur identité noire </li>\r\n              <li>Objectif 2 : Accompagner les jeunes noirs à risque pour empêcher qu’il ne bascule dans la délinquance juvénile et la criminalité ; </li>\r\n              <li>Objectif 3 : Accompagner les jeunes noirs à risque en prise avec le système pénal pour les aider à réintégrer avec succès la société canadienne;</li>\r\n              <li>Objectif 4 : Sensibiliser les jeunes de la communauté noire sur la crise croissante de la santé mentale et de l\'abus de substances psychoactives. </li>\r\n          </ul>\r\n\r\n          <h3>AXE II : les familles des jeunes noirs à risque</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Accompagner les familles des jeunes noirs à risque dans la médiation et la reconstruction du noyau familial ;</li>\r\n              <li>Objectif 2 : Accompagner les familles à comprendre le système pénal </li>\r\n              <li>Objectif 3 : accompagner les familles dans la réhabilitation et la réinsertion de leurs jeunes dans la société canadienne</li>\r\n          </ul>\r\n\r\n          <h3>AXE III : Le système éducatif</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Soutenir le système éducatif pour prévenir la stigmatisation, le racisme et la discrimination, en leur donnant des ressources et approches culturellement sensibles.</li>\r\n              <li>Objectif 2 : Jouer un rôle de médiateur entre les institutions éducatives et les jeunes afin d’éviter qu’il se retrouve dans le système pénal et décroche dans leurs études secondaires</li>\r\n              <li>Objectif 3 : Maintenir et restaurer le dialogue entre les familles et le système éducatif</li>\r\n          </ul>\r\n\r\n          <h3>AXE IV : La communauté</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Accompagner les communautés pour prévenir les stigmatisations envers les jeunes noirs à risque et favoriser la compassion</li>\r\n          </ul>\r\n\r\n          <h3>AXE V : Le système pénal</h3>\r\n          <ul>\r\n              <li>Objectif 1 : Changer les attitudes et les stigmas vis-à-vis des jeunes noirs à risque afin d’éviter qu’ils se retrouvent dans le système pénal avec des charges mineures</li>\r\n          </ul>', '2021-01-17 15:49:30', '0000-00-00 00:00:00');
