INSERT INTO `blocs` (`id`, `title_fr`, `title_en`, `description_fr`, `description_en`, `icon`, `btn_name_fr`, `btn_name_en`, `btn_link`, `color`, `created_at`, `updated_at`) VALUES
(1, 'Être un bénévole', 'Being a volunteer', 'Point Ancrage Jeunesse a besoin de votre aide pour continuer son travail auprès des jeunes de la communauté noire et aussi pour mettre en place les projets en cours afin de valoriser la voix aux jeunes noir.es. Nous les accompagnons dans leur reconstruction identitaire afin qu\'ils retrouvent leurs valeurs, leur culture et la fierté de leur identité noire.\r\n\r\nNous avons besoin de votre engagement ! Impliquez-vous auprès de nous pour nos activités ainsi que nos évènements à venir.\r\n\r\nEnsemble, redonnons une voix plus forte aux jeunes Noir.es !', 'Youth Anchorage Point needs your help to continue to work with youth in the Black community and also to develop ongoing projects to enhance the voice of Black youth.  We support them in their reconstruction of their identity so that they can regain their values, their culture and the pride of their black identity.\r\n\r\nWe need your commitment! Get involved with us in our activities and upcoming events.\r\n\r\nTogether, let\'s give a stronger voice to Black youth !', 'flaticon-solidarity', 'Impliquez-vous !', 'Get involved !', 'https://pointancragejeunesse.org/impliquez-vous', '', '2021-04-07 20:48:23', '2021-04-07 18:48:23'),
(2, 'Faire un don', 'Donate', 'PAJ a besoin de fonds pour continuer son travail au quotidien et son engagement auprès des jeunes Noir.es.\r\nNous avons besoin de Vous, et de vos dons pour permettre l\'épanouissement de nos jeunes dans cette société canadienne.', 'YAP needs funds to continue our work and commitment to Black youth.\r\nWe need you, and your donations, to support the well-being of Black youth in this society.', 'flaticon-donation', 'Commencez', 'Starting', 'https://pointancragejeunesse.org/projets', 'two', '2021-03-28 20:27:47', '2021-03-28 18:27:47'),
(3, 'Découvrir PAJ', 'Learn more about YAP', 'Avez-vous quelque chose à nous partager ? N\'hésitez pas à nous contacter !', 'Do you have a suggestion to share with us? Feel free to contact us !', 'flaticon-love', 'Nous Joindre', 'Contact us', 'https://pointancragejeunesse.org/contact', 'three', '2021-03-28 20:38:58', '2021-03-28 18:38:58');
INSERT INTO `blogs` (`id`, `title_fr`, `title_en`, `description_fr`, `description_en`, `slug`, `image`, `created_at`, `updated_at`) VALUES
(1, 'Une cérémonie de clôture haute en culture organisée par Sofifran', 'A high culture closing ceremony organized by Sofifran', 'La directrice générale de Sofifran, Fété Kimpiobi, souligne fièrement, le 28 février, la fin du Mois de l’histoire des Noirs (MHN). L’organisme offre des services communautaires aux francophones et francophiles en Ontario et, particulièrement dans la région du Niagara.\r\n\r\n« En février et en tout temps, célébrons l’histoire des communautés noires aujourd’hui et tous les jours. Bonne soirée! », lance-t-elle dans son introduction qui fait place à un tour de table de divers artistes et personnalités noires issus de la communauté partageant leur cheminement.\r\n\r\nPour l’animatrice et artiste Justine Gogoua, le MHN c’est l’histoire de l’humanité qui a débuté en Afrique de l’Est plus précisément. « Chez nous en Afrique, célébrer le talent c’est au-delà de faire de la musique, danser et faire rire la galerie. C’est être fier de la culture, de qui nous sommes », affirme-t-elle.\r\n\r\nElle souhaite que les gens s’allient à la découverte des cultures noires. « De ce peuple magnifique, qui est riche en couleur, riche de culture et qui a bâti une grande partie de l’humanité », indique-t-elle.\r\n\r\nSonia Kleper présente une plateforme de partage de l’art culinaire africain, By Nia cuisine. « Je ne suis pas cuisinière professionnelle mais je suis une grande passionnée », avoue-t-elle, le sourire aux lèvres.\r\n\r\nElle s’exprime sur l’importance de maintenir certains rituels tel celui de manger avec les mains pour un contact direct avec la nourriture. « Toutes les pratiques et les cérémonies observées dans l’art culinaire font la richesse de la culture des Noirs », mentionne Mme Kleper.\r\n\r\nLes musiciens Amadou Kienou et Borelson offrent des mini concerts et l’artiste dessinateur Jean Salomon André raconte les histoires de ses dessins. D’autres professionnels, dont Vanessa Aubourg, Sabine Soumare et Aminatou Diallo, s’ajoutent aux festivités pour jaser de leurs divers accomplissements.\r\n\r\nLa célébration est disponible en rediffusion sur la page Facebook de Sofifran.\r\n\r\n \r\n\r\nPHOTO – Sonia Kleper\r\n\r\nSOURCE – Élodie Dorsel', 'Sofifran\'s general manager, Fité Kimpioobi, proudly underlines, on February 28, the end of the month of black history (MHH). The organization offers community services to Francophones and Francophiles in Ontario and, particularly in the Niagara region.\r\n\r\n\"In February and at all times, let\'s celebrate the history of black communities today and every day. Have a good evening! », She launches in her introduction which gives way to a round of the table of various black artists and personalities from the community sharing their journey.\r\n\r\nFor the host and artist Justine Gogoua, the MHN is the history of humanity that has started in East Africa more precisely. \"With us in Africa, celebrating talent is beyond making music, dancing and making the gallery laugh. It is to be proud of culture, who we are, \"she says.\r\n\r\nShe hopes people to discover black cultures. \"Of this magnificent people, who are rich in color, rich in culture and who has built a large part of humanity,\" she said.\r\n\r\nSonia Kleper presents a platform for sharing African culinary art, by Nia Cuisine. \"I am not a professional cook but I am a great passionate,\" she admits, smiling.\r\n\r\nIt is expressed on the importance of maintaining certain rituals such as eating with hands for direct contact with food. \"All the practices and ceremonies observed in culinary art make the richness of the culture of blacks,\" said Ms. Kleper.\r\n\r\nThe musicians Amadou Kienou and Borelson offer mini concerts and the designer artist Jean Salomon André tells the stories of his drawings. Other professionals, including Vanessa Aubourg, Sabine Soumare and Aminou Diallo, are added to the festivities to chat in their various accomplishments.\r\n\r\nThe celebration is available in replay on Sofifran\'s Facebook page.\r\n\r\n \r\n\r\nPhoto - Sonia Kleper\r\n\r\nSource - Élodie Dorsel', 'une-ceremonie-de-cloture-haute-en-culture-organisee-par-sofifran', '1652707876.png', '2022-05-16 13:31:17', '2022-05-16 11:31:17'),
(2, 'Une exploration culinaire présentée par SOFIFRAN', 'A culinary exploration presented by Sofifran', 'La Semaine nationale de l’immigration francophone se constitue de diverses activités, parfois ludiques, parfois éducatives, souvent les deux à la fois. La rencontre culinaire virtuelle organisée par SOFIFRAN appartenait sans aucun doute à cette dernière catégorie.\r\n\r\nC’est donc par le biais des plaisirs de la table que l’organisme a abordé la question du multiculturalisme. En vedette : le poulet tshiluabenyi, qui tire son nom de l’épice qui est utilisée dans sa préparation et qui constitue en fait le véritable intérêt de ce mets.\r\n\r\n« La recette vient de la République démocratique du Congo. C’est un plat qui est présenté dans toutes les occasions spéciales, les circonstances importantes de la vie », débute Fété Kimpiobi. La directrice générale de SOFIFRAN explique qu’il existe différentes variantes au poulet tshiluabenyi, en fonction du rythme de préparation et du symbolisme de la situation qui va des baptêmes aux fiançailles en passant par les problèmes matrimoniaux.\r\n\r\nCe n’était cependant pas entre les mains de Mme Kimpiobi que la préparation de la recette fut confiée, mais plutôt à Régine Tshibangu. Une vidéo d’une dizaine de minutes à cet effet a été présentée au cours de laquelle Mme Tshibangu a accommodé une version standard et simplifiée de la recette, puisqu’en Afrique c’est le poulet entier qui est inclus dans la préparation.\r\n\r\nUn accompagnement fait de tomate, oignon, persil, ciboulette, ail et huile végétale est apprêté et dans lequel le poulet, fendu ça et là au préalable pour absorber la saveur de cette sauce, doit cuire pendant un temps. Quant au tshiluabenyi, qui se présente sous la forme de petites feuilles foncées, il est tout simplement répandu sur le tout au cours de la cuisson.\r\n\r\n« L’idée, c’est de manger le tshiluabenyi et non pas le poulet! », assure Régine Tshibangu. Bien sûr, il s’agit-là d’une hyperbole, mais qui traduit bien l’intérêt que vouent les Congolais pour cette épice.\r\n\r\nAprès la présentation de la vidéo, la cuisinière a répondu aux questions du public. Les alternatives aux ingrédients typiquement africains ont également été discutées, puisqu’il n’est souvent pas facile de les dénicher dans les épiceries de nos contrées.\r\n\r\nD’ailleurs, comme il a été souligné, il arrive que des ingrédients en apparence très similaires aient un goût différent en fonction de leur provenance.\r\n\r\nIl y a quelques années, SOFIFRAN avait d’ailleurs entrepris d’expérimenter, dans la région du Niagara, la culture de fruits et légumes authentiquement africains, une initiative qui avait plu et qui donnait directement accès à une gamme de produits autrement rares sous nos latitudes.\r\n\r\nComme quoi l’art culinaire n’a jamais été étranger à SOFIFRAN.\r\n\r\n \r\n\r\nPHOTO – Régine Tshibangu a expliqué les grandes lignes de la préparation de la recette.', 'The National Week of Francophone Immigration consists of various activities, sometimes playful, sometimes educational, often both. The virtual culinary meeting organized by Sofifran undoubtedly belonged to this last category.\r\n\r\nIt was therefore through the pleasures of the table that the organization addressed the question of multiculturalism. Standard: the Tshiluabenyi chicken, which takes its name from the spice which is used in its preparation and which in fact constitutes the real interest of this dishes.\r\n\r\n“The recipe comes from the Democratic Republic of Congo. It is a dish that is presented on all special occasions, the important circumstances of life, \"begins Feté Kimpioobi. Sofifran\'s general manager explains that there are different variants with Tshiluabenyi chicken, depending on the pace of preparation and the symbolism of the situation that goes from baptisms to engagement through matrimonial problems.\r\n\r\nHowever, it was not in the hands of Mrs. Kimpioobi that the preparation of the recipe was entrusted, but rather to Régine Tshibangu. A video of ten minutes for this purpose was presented during which Ms. Tshibangu accommodated a standard and simplified version of the recipe, since in Africa it is the whole chicken which is included in the preparation.\r\n\r\nAn accompaniment made of tomato, onion, parsley, chives, garlic and vegetable oil is primed and in which the chicken, split here and there before to absorb the flavor of this sauce, must cook for a while. As for the Tshiluabenyi, which is in the form of small dark leaves, it is simply widespread on everything during cooking.\r\n\r\n\"The idea is to eat tshiluabenyi and not chicken! \", Ensures Régine Tshibangu. Of course, this is a hyperbola, but which translates the interest that Congolese for this spice devote.\r\n\r\nAfter the presentation of the video, the cook answered questions from the public. The alternatives to typically African ingredients have also been discussed, since it is often not easy to find them in the grocery stores of our regions.\r\n\r\nBesides, as has been pointed out, it happens that apparently very similar ingredients have a different taste depending on their origin.\r\n\r\nA few years ago, Sofifran had also undertook to experiment, in the Niagara region, the cultivation of authentically African fruits and vegetables, an initiative which had rained and which gave directly to a range of products otherwise rare under our latitudes.\r\n\r\nLike what culinary art has never been foreign to Sofifran.\r\n\r\n \r\n\r\nPhoto - Régine Tshibangu explained the main lines of the preparation of the recipe.', 'une-exploration-culinaire-presentee-par-sofifran', '1652710930.png', '2022-05-16 12:22:11', '2022-05-16 12:22:11'),
(3, 'Une année bien remplie pour SOFIFRAN', 'A busy year for Sofifran', 'Il est toujours surprenant de constater à quel point SOFIFRAN bourdonne d’activités et de projets. Encore une fois, l’assemblée générale annuelle du 20 juin dernier a permis de saisir la pleine mesure de l’impact de cet organisme dans le Niagara et bien au-delà.\r\nUn large éventail de nouvelles activités sont également nées de la pandémie : 19 ateliers sur les différentes facettes de la crise et les manières d’y faire face de même que la distribution de paniers de nourriture et de produits sanitaires en sont de bons exemples.\r\n\r\nSOFIFRAN a également bénéficié du soutien de la Fondation Trillium de l’Ontario, de la Fondation canadienne des femmes et du Fonds d’appui aux communautés noires, notamment pour former son personnel, acquérir certains équipements et se prémunir contre la transmission du virus.\r\n\r\nComme c’est l’usage, c’est la directrice générale, Fété Kimpiobi, qui a fait un survol des réalisations de la dernière année.\r\n\r\nSans surprise, bon nombre d’activités régulières ont dû être converties au format web (fête des Mères, Semaine de l’immigration francophone, Festiv’Ébène, etc.) tandis que d’autres ont été annulées ou remises à plus tard (cueillette de fruits et de légumes et Folks Arts). Malgré tout, les circonstances ou la nécessité ont également permis à quelques initiatives de se dérouler en présentiel : on n’a qu’à penser à la soirée reconnaissance des bénévoles et la mise en place d’une garderie pilote en milieu familial.\r\nL’organisme a aussi recruté un collaborateur des plus prometteurs au cours de la dernière année. « Nous avons la chance d’avoir un nouveau directeur artistique : c’est M. Saïd Ben », a rappelé Fété Kimpiobi. Le public de SOFIFRAN a d’ailleurs eu l’occasion d’avoir un aperçu de ses projets et champs de prédilection lors du plus récent Festiv’Ébène.', 'It is always surprising to see how Sofifran buzzes with activities and projects. Once again, the annual general meeting of June 20 made it possible to seize the full measure of the impact of this organization in Niagara and far beyond.\r\nA wide range of new activities were also born from the pandemic: 19 workshops on the various facets of the crisis and the ways of dealing with it as well as the distribution of baskets of food and sanitary products are good examples.\r\n\r\nSofifran has also benefited from the support of the Ontario Trillium Foundation, the Canadian Women\'s Foundation and the Support Fund for Black Communities, in particular to form its staff, acquire certain equipment and protect themselves against the transmission of the virus.\r\nThe organization also recruited a most promising employee in the past year. \"We are fortunate to have a new artistic director: it is Mr. Saïd Ben,\" said Feté Kimpioobi. Sofifran\'s public also had the opportunity to have an overview of his favorite projects and fields during the most recent Festiv’ Ebène.', 'une-annee-bien-remplie-pour-sofifran', '1652720188.png', '2022-05-16 17:05:50', '2022-05-16 15:05:50'),
(4, 'SOFIFRAN fait le bonheur des enfants', 'Sofifran makes children happy', 'C’est dans les derniers jours de février que se concentrent les événements les plus importants du Mois de l’histoire des Noirs. Le Festiv’Ébène est de ceux-là et, comme tous les autres, a dû se dérouler en ligne.\r\n\r\nComme une pandémie bouscule un tantinet les habitudes, il y avait lieu de se demander si le public serait au rendez-vous. En termes d’habitude, les habitués de Sofifran n’avaient pas perdu celle d’arriver au compte-goutte, mais ils n’en étaient pas moins tous là! Avec, au plus fort de l’achalandage, environ 65 appareils connectés à la plateforme Zoom, dont certains avec plus d’un utilisateur, sans compter ceux qui suivaient l’événement en direct sur Facebook, on peut dire que le public de Sofifran s’est montré fidèle.\r\n\r\nAnimé par Vanessa Aubourg Jean Charles, membre du conseil d’administration, ce Festiv’Ébène constituait le premier de Saïd Ben, nouveau directeur artistique de l’organisme.\r\n\r\nC’est d’abord avec quelques adolescentes de la communauté venues partager leurs talents musicaux que la soirée a commencé. Sherna Jean-Charles, Erika Jean-Charles, Rodia Mwamba, Marla Zephir et Diana Dorvil ont offert un bouquet de chansons de divers styles.\r\n\r\nLeur ont succédé Gaston Mabaya qui, dans une veine plus littéraire, a abordé le thème du devoir de mémoire. Par l’entremise d’un récit vivant, tantôt monologue dramatique, tantôt exposé historique, il a brossé le tableau de l’histoire des Noirs des cinq derniers siècles.\r\n\r\nSes interventions alternaient avec d’autres prestations. Le rappeur Borelson a ainsi réchauffé l’événement d’un style musical qu’ont y a rarement entendu. Erta Rose Ekosso a fait entendre sa voix aussi puissante que mélodieuse donner vie à quelques ballades empreintes d’émotions. Abel Maxwell a de son côté donné dans la gaité avec certains de ses succès. Quant à Yao, il a enchaîné les mélodies tissées de poésie.\r\n\r\nLe directeur artistique de Sofifran n’était pas en reste et a contribué au Festiv’Ébène par son domaine de prédilection : le théâtre. Saïd Ben a interprété trois sketchs surréalistes mais qui donnaient à réfléchir en plus de laisser un sourire aux lèvres des spectateurs.\r\n\r\nLe rideau est ainsi tombé sur un Festiv’Ébène bien rempli et des plus étonnants. Alors que plusieurs commencent à se lasser des activités en ligne, Sofifran aura su renouveler ce plaisir imposé par la pandémie.', 'It is in the last days of February that the most important events in the month in black history are concentrated. The Festiv’ Ebène is one of them and, like all the others, had to take place online.\r\n\r\nAs a pandemic shakes up a little habits, there was reason to wonder if the public would be there. In terms of habit, the regulars of Sofifran had not lost the one to arrive at the dropper, but they were nonetheless there! With, at the height of traffic, around 65 devices connected to the Zoom platform, some with more than one user, not to mention those who followed the live event on Facebook, we can say that the public of Sofifran S \'is shown faithful.\r\n\r\nHosted by Vanessa Aubourg Jean Charles, member of the Board of Directors, this Festiv’ Ebène was the first of Said Ben, new artistic director of the organization.\r\n\r\nIt was first with a few teenage girls from the community who came to share their musical talents that the evening began. Sherna Jean-Charles, Erika Jean-Charles, Rodia Mwamba, Marla Zephir and Diana Dorvil offered a bouquet of songs from various styles.\r\n\r\nGaston Mabaya succeeded them who, in a more literary vein, addressed the theme of the duty of memory. Through a living story, sometimes dramatic monologue, sometimes historical exposed, he has brushed the painting of the history of blacks in the last five centuries.\r\n\r\nHis interventions alternated with other services. Rapper Borelson held the event of a musical style that has rarely heard. Erta Rose Ekosso made her voice heard as powerful as it is melodious bringing to some walks of emotions. Abel Maxwell for his part gave in gaiety with some of his successes. As for Yao, he chained the melodies woven with poetry.\r\n\r\nThe artistic director of Sofifran was not to be outdone and contributed to the festiv’ rébène by his favorite field: theater. Said Ben interpreted three surreal sketches but which gave to think in addition to leaving a smile on the lips of the spectators.\r\n\r\nThe curtain thus fell on a well -filled and most amazing festiv’a festiv. While many are starting to get tired of online activities, Sofifran has been able to renew this pleasure imposed by the pandemic.', 'sofifran-fait-le-bonheur-des-enfants', '1652721401.png', '2022-05-16 15:16:41', '2022-05-16 15:16:41'),
(5, 'Mémoires vives', 'Small memories', 'Samedi 26 février Sofifran a célébré ses 15 ans de présence au Niagara ainsi que les 15 ans du festival Festiv’Ébène sous le thème de ‘’Mémoires vives’’. Pour l’occasion, une série de performances musicales, oratoires et une pièce dramatique ont été présentées au public. Nous vous invitons à les visionner sur nos réseaux sociaux. Ci-dessous les liens.\r\n\r\nYoutube: https://youtu.be/Tvpq9WPUn5w\r\n \r\nFacebook: https://fb.watch/bvB3qekNd_/', 'On Saturday, February 26, Sofifran celebrated its 15 years of presence in Niagara as well as the 15th anniversary of the Festiv’s festival under the theme of ‘’ Mémoires Vives ’’. For the occasion, a series of musical performance, oratories and a dramatic piece were presented to the public. We invite you to view them on our social networks. Below the links.\r\n\r\nYouTube: https://youtu.be/tvpq9wpun5W\r\n \r\nFacebook: https://fb.watch/bvb3qeknd_/', 'memoires-vives', '1652721584.jpg', '2022-05-16 15:19:44', '2022-05-16 15:19:44'),
(6, 'SOFIFRAN se dote d’un plan stratégique ambitieux', 'Sofifran has an ambitious strategic plan', 'Il y a de cela un an, la Fondation Trillium de l’Ontario, par l’entremise de son Fonds pour les communautés résilientes, accordait une subvention à SOFIFRAN. La pandémie et les incertitudes qui l’entouraient avaient mené à la création de ce fonds destiné à minimiser l’impact de la COVID-19 sur le milieu communautaire et l’organisme basé à Welland avait saisi cette opportunité pour mieux s’outiller afin de répondre aux besoins de son milieu.\r\n\r\nLe personnel et le conseil d’administration ont donc été formés dans le but de mieux s’acquitter de leurs tâches, les programmes ont été numérisés et, surtout, une consultation a été menée afin de connaître l’opinion des membres de la communauté à propos de l’organisme et des services qu’ils aimeraient recevoir.\r\n\r\nPrendre le pouls de sa clientèle cible s’inscrivait dans un exercice plus large de réflexion qui devait permettre à SOFIFRAN de se doter d’un plan stratégique s’échelonnant jusqu’en 2025. Ce plan a non seulement été complété récemment, mais vient tout juste d’entrer en vigueur.\r\n\r\nLes défis de longue date qui ont été identifiés sont le manque de ressources financières et humaines qui limite les interventions auprès d’une population immigrante croissante. Les défis immédiats sont ceux engendrés par la pandémie et sont d’ordre financier et opérationnel.\r\n\r\nDans la communauté, les problèmes liés aux confinements sont principalement les pertes d’emploi et la violence conjugale et familiale. SOFIFRAN considère aussi les questionnements entourant la discrimination raciale comme étant un sujet d’actualité en lien direct avec son mandat.\r\n\r\nLes circonstances actuelles et ce que l’on perçoit déjà des prochaines années se caractérisent également par certaines opportunités, nommément la transformation numérique, la collaboration accrue avec les partenaires, le développement et la formation du personnel de même que les possibilités offertes par la diversité et l’inclusion sous condition de promotion de l’identité culturelle.\r\n\r\nLe plan stratégique de SOFIFRAN répond à ces constats par deux axes principaux, soit l’intégration accrue du numérique dans ses activités et un meilleur fonctionnement organisationnel, en d’autres mots accroître son personnel et son efficacité.\r\n\r\nLe plan stratégique est également constitué de trois piliers prioritaires, c’est-à-dire l’économique, le social et le culturel, pour répondre aux besoins des clients.\r\n\r\nLe pilier économique se rapporte surtout à l’employabilité des immigrants francophones. Celui consacré au social touche pour l’essentiel à l’accueil et à l’intégration des immigrants. Quant au pilier voué aux arts et à la culture, il réfère à l’épanouissement identitaire.\r\n\r\nSOFIFRAN s’est aussi doté d’une liste de gestes précis à poser couplés à des indicateurs de rendement pour parvenir à l’atteinte de ses objectifs. Au cours des prochaines semaines, l’organisme se mettra donc au travail pour faire de ce plan une réalité.', 'A year ago, the Trillium Foundation in Ontario, through its fund for resilient communities, granted a subsidy to Sofifran. The pandemic and the uncertainty that surrounded it had led to the creation of this fund intended to minimize the impact of the COVID-19 on the community environment and the organization based in Welland had seized this opportunity to better overturn to meet the needs of his environment.\r\n\r\nThe staff and the board of directors were therefore trained in order to better fulfill their tasks, the programs have been digitized and, above all, a consultation was carried out in order to know the opinion of the members of the community in words about the organization and the services they would like to receive.\r\n\r\nTaking the pulse of its target clientele was part of a broader exercise of reflection which was to allow Sofifran to acquire a strategic plan arched until 2025. This plan was not only completed recently, but comes everything just to come into force.\r\n\r\nThe long -standing challenges that have been identified are the lack of financial and human resources that limit interventions with an increasing immigrant population. Immediate challenges are those engendered by the pandemic and are financial and operational.\r\n\r\nIn the community, problems related to confinements are mainly losses of employment and domestic and family violence. Sofifran also considers questions surrounding racial discrimination as a topical subject directly related to his mandate.\r\n\r\nThe current circumstances and what we already receive from the next few years are also characterized by certain opportunities, namely digital transformation, increased collaboration with partners, the development and training of staff as well as the possibilities offered by diversity and Inclusion subject to promoting cultural identity.\r\n\r\nSofifran\'s strategic plan meets these findings by two main axes, the increased integration of digital technology in its activities and better organizational functioning, in other words to increase its staff and its efficiency.\r\n\r\nThe strategic plan is also made up of three priority pillars, that is to say economic, social and cultural, to meet the needs of customers.\r\n\r\nThe economic pillar relates above all to the employability of French -speaking immigrants. The one devoted to the social essentially affects the reception and integration of immigrants. As for the pillar dedicated to the arts and culture, it refers to identity development.\r\n\r\nSofifran also has a specific list of gestures to be made coupled with performance indicators to achieve its objectives. In the coming weeks, the organization will therefore get to work to make this plan a reality.', 'sofifran-se-dote-dun-plan-strategique-ambitieux', '1652721729.jpg', '2022-05-16 15:22:09', '2022-05-16 15:22:09'),
(7, 'Travail d’été', 'Summer job', 'Vous êtes élève au Csc Mon Avenir et vous êtes à la recherche d’un travail d’été. Voici un poste de recherchiste adjoint(e) qui pourrait vous convenir. Veuillez adresser votre C.V. à sofifran2007@gmail.com au plus tard le 16 juin 2021. Ci-dessous, la description du poste.', 'You are a student at CSC my future and you are looking for summer work. Here is a position of assistant researcher that could suit you. Please send your C.V. to Sofifran2007@gmail.com at the latest on June 16, 2021. Below is the description of the position.', 'travail-dete', '1652722524.jpg', '2022-05-16 15:35:24', '2022-05-16 15:35:24'),
(8, 'Brock, Festival, Culture et Masques !', 'Brock, festival, culture and masks!', 'Au cours des années et de ses nombreuses activités, l’organisme Sofifran, bien que basé à Welland, a tissé des liens avec les institutions et les communautés de toute la région qu’il dessert, soit le Niagara. Le 7 février dernier, c’est à l’Université Brock, à St. Catharines, que deux représentantes de Sofifran ont participé à une soirée culturelle aux multiples facettes.\r\n\r\nL’activité avait autant pour objectif de donner la parole à Fété Kimpiobi et Nafée Nelly Faïgou qu’à mettre de l’avant les programmes du Département des langues modernes, des littératures et des cultures, dont le nom à rallonge évoque la relation complexe entre ces divers champs d’étude. Les commentaires des intervenants portaient plus particulièrement sur l’étude du français et la directrice de ce programme, Astrid Heyer, a d’ailleurs passé un bon moment à parler de la compétition que l’université organise depuis 1978. Le Concours de français Brock-Niagara permet aux élèves du secondaire de 11e et 12e années de mesurer leurs connaissances de la langue de Molière tout en courant la chance de remporter des prix. L’édition de cette année sera améliorée et comportera une dimension consacrée à l’interaction culturelle.\r\n\r\nMme Faïgou, directrice artistique du Festiv’Ébène, a ensuite fait une présentation sur la place des masques en Afrique. Ceux-ci se divisent en deux catégories générales : les masques sacrés, qui représentent les ancêtres et les divinités, et les masques profanes, qui transmettent une mémoire sociohistorique. Loin d’être des objets inertes, ils sont à la jonction de tous les rapports sociaux. Leurs fonctions sont à la fois religieuse, politique, sociale, culturelle, économique… Les fonctions du masque sont autant imbriquées dans toutes les dimensions de la vie en société que ne l’est la conception du divin, le sacré étant immanent aux diverses réalités du quotidien. D’ailleurs, les masques à vocation religieuse sont « habités » par des esprits avec tout ce que cela sous-entend comme rapport immédiat à l’au-delà.\r\n\r\nMme Kimpiobi, directrice générale de l’organisme, a mentionné à ce propos qu’il existe en Afrique des fraternités et des sororités dédiées aux masques. On trouve également des « démagnétiseurs » chargés de retirer les pouvoirs des masques ayant servi dans des cérémonies.\r\n\r\nAprès cette parenthèse anthropologique, la soirée s’est terminée sur une note littéraire. Fété Kimpiobi a lu un extrait de son roman Nyota – Le secret de la plume. Nafée Nelly Faïgou a de son côté récité quelques poèmes tirés de son recueil intitulé Masques, un titre décidément de circonstance.\r\n\r\nLes masques seront à l’honneur à l’Université Brock jusqu’au 1er mars avec une exposition disséminée à la bibliothèque et au Département des langues modernes. Une autre exposition sur le même thème sera en montre au musée Rodman, affilié à l’université, du 16 février au 3 mars.', 'Over the years and its many activities, the Sofifran organization, although based in Welland, has woven links with the institutions and communities of the whole region it serves, Niagara. On February 7, it was at Brock University in St. Catharines, that two representatives of Sofifran participated in a cultural evening with multiple facets.\r\n\r\nThe activity had as much the objective of giving the floor to Fété Kimimobi and Nafée Nelly Faïgou to put forward the programs of the Department of Modern Languages, Literature and Cultures, whose extended name evokes the complex relationship between These various fields of study. The comments of the stakeholders focused more particularly on the study of the French and the director of this program, Astrid Heyer, also had a good time talking about the competition that the University has organized since 1978. The French Brock- competition- Niagara allows secondary school students in 11th and 12th years to measure their knowledge of Molière\'s language while running the chance to win prices. This year\'s editing will be improved and will have a dimension devoted to cultural interaction.\r\n\r\nMs. Faïgou, artistic director of Festiv’ Ebène, then made a presentation on the place of masks in Africa. These are divided into two general categories: sacred masks, which represent ancestors and deities, and profane masks, which transmit sociohistoric memory. Far from being inert objects, they are at the junction of all social relationships. Their functions are at the same time religious, political, social, cultural, economic ... The functions of the mask are as much intended in all the dimensions of life in society as is the conception of the divine, the sacred being immanent in the various realities of the daily. Moreover, the masks with a religious vocation are \"inhabited\" by spirits with all that that implies as an immediate relationship to the beyond.\r\n\r\nMs. Kimpioobi, director general of the organization, said in this regard that there are fraternities and sororities dedicated to masks in Africa. There are also \"demagnetists\" responsible for removing the powers from the masks used in ceremonies.\r\n\r\nAfter this anthropological parenthesis, the evening ended with a literary note. Feté Kimpioobi read an extract from his nyota novel - the secret of the pen. Nafée Nelly Faïgou has recited some poems taken from her collection entitled Masks, a decidedly circumstance title.\r\n\r\nThe masks will be in the spotlight at Brock University until March 1 with an exhibition scattered at the Library and the Department of Modern Languages. Another exhibition on the same theme will be watching at the Rodman Museum, affiliated to the University, from February 16 to March 3.', 'brock-festival-culture-et-masques', '1652724980.jpg', '2022-05-16 16:16:21', '2022-05-16 16:16:21'),
(9, 'Assemblée Générale Annuelle de Sofifran', 'Annual General Meeting of Sofifran', 'C’est au terme d’une année bien remplie que, le dimanche 23 juin, l’organisme Sofifran tenait son assemblée générale annuelle (AGA) à Welland. Les activités de toutes sortes n’ont pas manqué comme l’a révélé le rapport à cet effet : Journée internationale de la femme, visites aux personnes dans le besoin, ateliers sur l’entreprenariat, le leadership et les victimes d’actes criminels, présentations à l’Université Brock, Festiv’Ébène, « portes ouvertes » dans le cadre du Folk Arts, etc. De la promotion de la culture au développement socioéconomique, il semble qu’il n’y ait pas un domaine dans lequel Sofifran ne soit engagé! L’AGA a également permis de lever le voile sur certains projets qui pourraient voir le jour au cours de la prochaine année. Pour les mener à bien, l’organisme continuera à compter sur son personnel dévoué et ses administratrices enthousiastes.\r\n\r\nPhoto : le conseil d’administration est formé (de gauche à droite) de Sandra Jactilus, Nadine Numa, Marie Dominique Laborde, Clarice Djuikouo, Nyarai Kapisavanhu et Kettia Zéphir. (Absente : Naromie Azar Charles).', 'It was after a busy year that, on Sunday, June 23, the Sofifran organization held its annual general assembly (AGA) in Welland. Activities of all kinds did not fail as the report on this purpose revealed: International Women\'s Day, visits to people in need, workshops on entrepreneurship, leadership and victims of criminal acts, Presentations at Brock University, Festiv\'Ébène, \"Open Doors\" as part of Folk Arts, etc. From the promotion of culture to socioeconomic development, it seems that there is not an area in which Sofifran is not engaged! AGA has also made it possible to lift the veil on certain projects that may see the light of day in the next year. To carry them out, the organization will continue to count on its dedicated staff and its enthusiastic administrators.\r\n\r\nPhoto: The board of directors is formed (from left to right) by Sandra JACTUS, Nadine NUMA, Marie Dominique Laborde, Clarice Djuikouo, Nyarai Kapisavanhu and Kettia Zéphir. (Absent: Naromie Azar Charles).', 'assemblee-generale-annuelle-de-sofifran', '1652726055.jpg', '2022-05-16 16:34:15', '2022-05-16 16:34:15'),
(10, 'Une cérémonie de clôture haute en culture organisée par Sofifran', 'A cultural closing ceremony organized by Sofifran', 'La directrice générale de Sofifran, Fété Kimpiobi, souligne fièrement, le 28 février, la fin du Mois de l’histoire des Noirs (MHN). L’organisme offre des services communautaires aux francophones et francophiles en Ontario et, particulièrement dans la région du Niagara.\r\n\r\n« En février et en tout temps, célébrons l’histoire des communautés noires aujourd’hui et tous les jours. Bonne soirée! », lance-t-elle dans son introduction qui fait place à un tour de table de divers artistes et personnalités noires issus de la communauté partageant leur cheminement.\r\n\r\nPour l’animatrice et artiste Justine Gogoua, le MHN c’est l’histoire de l’humanité qui a débuté en Afrique de l’Est plus précisément. « Chez nous en Afrique, célébrer le talent c’est au-delà de faire de la musique, danser et faire rire la galerie. C’est être fier de la culture, de qui nous sommes », affirme-t-elle.\r\n\r\n\r\nElle souhaite que les gens s’allient à la découverte des cultures noires. « De ce peuple magnifique, qui est riche en couleur, riche de culture et qui a bâti une grande partie de l’humanité », indique-t-elle.\r\n\r\nSonia Kleper présente une plateforme de partage de l’art culinaire africain, By Nia cuisine. « Je ne suis pas cuisinière professionnelle mais je suis une grande passionnée », avoue-t-elle, le sourire aux lèvres.\r\n\r\nElle s’exprime sur l’importance de maintenir certains rituels tel celui de manger avec les mains pour un contact direct avec la nourriture. « Toutes les pratiques et les cérémonies observées dans l’art culinaire font la richesse de la culture des Noirs », mentionne Mme Kleper.\r\n\r\nLes musiciens Amadou Kienou et Borelson offrent des mini concerts et l’artiste dessinateur Jean Salomon André raconte les histoires de ses dessins. D’autres professionnels, dont Vanessa Aubourg, Sabine Soumare et Aminatou Diallo, s’ajoutent aux festivités pour jaser de leurs divers accomplissements.\r\n\r\nLa célébration est disponible en rediffusion sur la page Facebook de Sofifran.\r\n\r\n \r\n\r\nPHOTO – Sonia Kleper\r\n\r\nSOURCE – Élodie Dorsel', 'Sofifran\'s Executive Director, Fété Kimpiobi, proudly marks the end of Black History Month (BHM) on February 28. The organization provides community services to Francophones and Francophiles in Ontario, and particularly in the Niagara region.\r\n\r\n\"In February and at all times, let\'s celebrate the history of Black communities today and every day. Have a great evening,\" she said in her introduction, which gave way to a round table discussion of various Black artists and personalities from the community sharing their journey.\r\n\r\nFor host and artist Justine Gogoua, the MHN is the history of humanity that began in East Africa specifically. \"For us in Africa, celebrating talent is more than making music, dancing and making people laugh. It\'s about being proud of the culture, of who we are,\" she says.\r\n\r\n\r\nShe wants people to join in the discovery of black cultures. \"Of this beautiful people, who are rich in color, rich in culture, and who have built a large part of humanity,\" she says.\r\n\r\nSonia Kleper presents a platform for sharing African culinary art, By Nia cuisine. \"I am not a professional cook but I am very passionate,\" she admits, with a smile.\r\n\r\nShe speaks about the importance of maintaining certain rituals such as eating with the hands for direct contact with the food. \"All the practices and ceremonies observed in the art of cooking are part of the richness of Black culture,\" says Kleper.\r\n\r\nMusicians Amadou Kienou and Borelson offer mini concerts and artist Jean Salomon André tells the stories of his drawings. Other professionals, including Vanessa Aubourg, Sabine Soumare and Aminatou Diallo, join the festivities to talk about their various accomplishments.\r\n\r\nThe celebration is available for replay on Sofifran\'s Facebook page.\r\n\r\nTranslated with www.DeepL.com/Translator (free version)\r\n\r\nPHOTO – Sonia Kleper\r\n\r\nSOURCE – Élodie Dorsel', 'une-ceremonie-de-cloture-haute-en-culture-organisee-par-sofifran', '1653496627.png', '2022-05-25 14:37:08', '2022-05-25 14:37:08'),
(11, 'Sofifran accompagne les entrepreneurs noirs avec leurs entreprises respectives', 'Sofifran accompanies black entrepreneurs with their respective companies', 'Au cours de la dernière semaine du mois d’avril, l’organisme Solidarité des femmes et familles interconnectées francophones du Niagara (Sofifran) a lancé le projet « Communauté de pratiques pour l’entrepreneuriat des communautés noires ».\r\n\r\nPrésenté par Fété Kimpiobi, directrice générale de l’organisme, l’événement virtuel a réuni une trentaine de personnes. Pour améliorer les performances des entrepreneurs noirs et de leurs entreprises respectives, Sofifran a opté pour un plan à trois volets : la mise en contexte et l’explication du thème, les conseils des experts et une période de questions/réponses.\r\n\r\nLa première présentation était celle de Ntunga Mazoresa. Pendant une quinzaine de minutes, l’experte d’Innovative Consultants a entretenu les participants sur les enjeux et les défis pour les entrepreneurs noirs.\r\n\r\n\r\nSi le problème au Canada n’est pas la création d’entreprises, les entrepreneurs noirs doivent faire face aux barrières culturelles, au racisme systémique, à l’absence d’accompagnements financiers et de gestion.\r\n\r\nPour faire face à ces défis, Mme Mazoresa propose d’établir une Communauté de pratiques pour les entrepreneurs noirs qui permettrait un partage d’expérience. Toutefois, elle explique que « l’efficacité d’une communauté de pratique est liée à son niveau d’activité et d’interaction, à l’engagement mutuel et à la satisfaction des membres ».\r\n\r\nDans le cadre de ce projet, Sofifran offrira « une plateforme virtuelle de soutien dont l’accès sera limité aux participants ayant des projets d’affaires à différentes étapes de leur développement, que ce soit la conception, le démarrage ou l’expansion », ajoute-t-elle.\r\n\r\nPour s’inscrire à ce programme, il faut se rendre sur le site Web de Sofifran. L’originalité réside dans son adaptation culturelle et le parcours des immigrants francophones, leur intégration économique et la gestion du racisme systémique.\r\n\r\n \r\n\r\nImportance de la communication\r\n\r\nRhodie Lamour a expliqué l’importance et l’impact de la communication dans les affaires. Sa présentation Communication et connexion était divisée en trois parties : l’importance de la connaissance de soi, la communication et l’entrepreneuriat ainsi que l’impact de la communication dans les affaires.\r\n\r\nSelon Mme Lamour, « il est important de se connaître avant de devenir entrepreneur, de connaître ses forces et de savoir où demander de l’aide ». Il s’agit de faire une analyse de ses « forces, faiblesses, opportunités et menaces » (SWOT, en anglais) pour découvrir ses passions en restant authentique.\r\n\r\nQuant à l’entrepreneuriat, il s’agit de se visualiser, de connaître la portée de son produit ou service et s’assurer que le message parvienne correctement aux clients potentiels. L’impact de la communication dans les affaires consiste à s’ouvrir au monde et à savoir ce qu’on recherche.\r\n\r\n« Celui qui ne sait pas ce qu’il recherche ne sait pas ce qu’il a trouvé », affirme Mme Lamour. L’objectif de la communication est toujours de se faire connaître.\r\n\r\nDans la foulée de la rencontre, Emmanuel Mompongo a partagé son expérience avant la période des questions, dernier segment du webinaire.\r\n\r\n \r\n\r\nPhoto : Rhodie Lamour (Photo : RhodieLamour.com)\r\n\r\nSource: https://leregional.com/author/denis/', 'During the last week of April, the organization Solidarité des femmes et familles interconnectées francophones du Niagara (Sofifran) launched the \"Community of Practice for Black Community Entrepreneurship\" project.\r\n\r\nPresented by Fété Kimpiobi, the organization\'s executive director, the virtual event was attended by about 30 people. To enhance the performance of black entrepreneurs and their respective businesses, Sofifran opted for a three-part plan: context and explanation of the topic, advice from experts and a question and answer period.\r\n\r\nThe first presentation was by Ntunga Mazoresa. For about 15 minutes, the expert from Innovative Consultants spoke to the participants about the issues and challenges for black entrepreneurs.\r\n\r\n\r\nIf the problem in Canada is not the creation of businesses, black entrepreneurs must face cultural barriers, systemic racism, lack of financial and management support.\r\n\r\nTo address these challenges, Ms. Mazoresa proposes the establishment of a Community of Practice for Black entrepreneurs that would allow for experience sharing. However, she explains that \"the effectiveness of a community of practice is related to its level of activity and interaction, mutual commitment, and member satisfaction.\"\r\n\r\nAs part of this project, Sofifran will offer \"a virtual support platform with limited access to participants with business projects at different stages of development, be it conception, start-up or expansion,\" she adds.\r\n\r\nTo register for this program, one must go to the Sofifran website. The originality lies in its cultural adaptation and the journey of Francophone immigrants, their economic integration and the management of systemic racism.\r\n\r\n \r\n\r\nImportance of communication\r\n\r\nRhodie Lamour explained the importance and impact of communication in business. Her presentation Communication and Connection was divided into three parts: the importance of self-awareness, communication and entrepreneurship, and the impact of communication in business.\r\n\r\nAccording to Ms. Lamour, \"it is important to know yourself before becoming an entrepreneur, to know your strengths and where to turn for help. It\'s about doing a SWOT analysis to discover your passions while remaining authentic.\r\n\r\nAs for entrepreneurship, it\'s about visualizing yourself, knowing the scope of your product or service and making sure that the message reaches potential customers correctly. The impact of communication in business is about being open to the world and knowing what you are looking for.\r\n\r\n\"If you don\'t know what you\'re looking for, you don\'t know what you\'ve found,\" says Lamour. The objective of communication is always to make oneself known.\r\n\r\nFollowing the meeting, Emmanuel Mompongo shared his experience before the question and answer session, the final segment of the webinar.\r\n\r\n \r\n\r\nPhoto: Rhodie Lamour (Photo: RhodieLamour.com)\r\n\r\nSource: https://leregional.com/author/denis/', 'sofifran-accompagne-les-entrepreneurs-noirs-avec-leurs-entreprises-respectives', '1653496967.jpg', '2022-05-25 14:42:47', '2022-05-25 14:42:47');
INSERT INTO `blogs` (`id`, `title_fr`, `title_en`, `description_fr`, `description_en`, `slug`, `image`, `created_at`, `updated_at`) VALUES
(12, 'Les activités reprennent dans le Niagara', 'Back to Niagara activities', 'La Table interagence du Niagara tenait sa rencontre mensuelle en ligne le 26 avril, une occasion pour les organismes de la région de partager leurs projets et activités.\r\n\r\nAnimée par Susan Morin, la discussion a débuté par l’organisation, la coordination et la visibilité de certaines activités communautaires tel le lever du drapeau franco-ontarien.\r\n\r\nLa majorité des intervenants prônent pour la mise en place d’un sous-comité communautaire pour une meilleure coordination et représentation pour les activités phares de la francophonie locale afin qu’elles soient plus représentatives de la nouvelle réalité multiculturelle dans la région.\r\n\r\n\r\n« On pourrait y insérer des compétences administratives du monde des affaires, par exemple, et ce sous-comité pourrait être géré par la Maison de la culture puisque l’organisme se cherche une vocation », explique Susan Morin.\r\n\r\nL’animatrice a présenté aux participants quatre nouveaux designs proposés pour remplacer le logo actuel de la Table créé en 2015, ainsi qu’un nouveau slogan Une force en action!\r\n\r\nLa majorité des intervenants ont préféré le logo numéro 2. Plusieurs ont fait des propositions pour améliorer le logo proposé alors Mme Morin assurera le suivi et proposera deux nouveaux modèles à une prochaine rencontre.\r\n\r\nDans la mise à jour du comité de l’immigration, Mikhaela Sullivan, du Réseau en immigration francophone du Centre-Sud-Ouest, a annoncé que son organisme a participé à la 24e édition de Métropolis Canada, en mars dernier à Vancouver, où le Réseau a animé un atelier, en collaboration avec la professeure Gertrude Mianda de l’Université York sur « l’impact des discriminations raciales sur l’intégration des immigrants francophones en Ontario ». Ce colloque a permis, entre autres, aux organismes participants de travailler sur des stratégies de lutte contre le racisme.\r\n\r\nPour sa part, Mélanie Robitaille du Conseil scolaire catholique MonAvenir a mentionné que le Conseil faisait face à une forte pénurie d’enseignants depuis le début de la pandémie. De plus, il semblerait y avoir un déplacement important d’enseignants dans l’est du pays, au Nouveau-Brunswick, où les conditions salariales sont meilleures. « Nous avons aussi constaté cette année que moins d’élèves francophones s’inscrivent dans les écoles françaises, un autre défi pour notre Conseil », dit-elle.\r\n\r\nL’ABC communautaire, située à Welland, offrira prochainement une série de cours, a indiqué la directrice générale de l’organisme, Linda Johnston. Parmi ces micro-cours, il sera question des bases du programme Antidote, des vendredis technos et des bases du logiciel QuickBooks. « Nous prévoyons aussi d’offrir des formations en entreprise personnalisées et travaillons à la création d’un site Web qui sera plus interactif et facile à consulter », a ajouté Mme Johnston.\r\n\r\nEn ce qui concerne le Centre de santé communautaire Hamilton/Niagara, sa directrice générale France Vaillancourt a confirmé le lancement d’un nouveau site Web et son équipe travaille pour développer des soins de santé palliatifs à Hospice Niagara.\r\n\r\nL’organisme SOFIFRAN a reçu une subvention de 50 600 $ de la Fondation Trillium pour des équipements technologiques qui permettront d’offrir des activités en ligne et de diffuser des émissions en direct sur YouTube.\r\n\r\n« Nous avons également reçu des fonds de FedDev Ontario pour la mise en place d’une communauté de pratique pour les entrepreneurs noirs, confirme la directrice générale de SOFIFRAN, Fété Kimpiobi. Il s’agit d’une plateforme où il sera question des défis (accès au capital, accompagnement pour la préparation de plans d’affaires, etc.) des entrepreneurs noirs ainsi que des outils, des ateliers et d’occasions d’échange pour les aider. Ce nouveau service répondra à certains de leurs défis. ».\r\n\r\nSOFIFRAN offrira aussi un camp d’été artistique avec Justine Gogoua, soit deux semaines au cours lesquelles les jeunes en apprendront davantage sur les autres cultures par le biais de contes, de la musique et d’ateliers (djembe, écriture, peinture et dessin..\r\n\r\nÀ noter que l’assemblée générale de SOFIFRAN aura lieu le dimanche 19 juin.\r\n\r\nLa dernière nouvelle de la rencontre : celle de Muriel Thibault Gauthier concernant la fête de la Saint-Jean qui aura lieu cette année à l’Auberge Richelieu à Welland, le dimanche 26 juin.\r\n\r\n \r\n\r\nPhoto: Fété Kimpiobi', 'The Niagara Interagency Table held its monthly online meeting on April 26, an opportunity for organizations in the region to share their projects and activities.\r\n\r\nModerated by Susan Morin, the discussion began with the organization, coordination and visibility of certain community activities such as the Franco-Ontarian flag raising.\r\n\r\nThe majority of the participants advocated for the establishment of a community sub-committee to better coordinate and represent the flagship activities of the local Francophonie so that they are more representative of the new multicultural reality in the region.\r\n\r\n\r\n\"This sub-committee could be managed by the Maison de la culture since the organization is looking for a vocation,\" explained Susan Morin.\r\n\r\nThe facilitator presented participants with four new proposed designs to replace the Table\'s current logo created in 2015, as well as a new slogan A force in action!\r\n\r\nThe majority of stakeholders preferred logo number 2. Several made suggestions to improve the proposed logo so Ms. Morin will follow up and propose two new designs at a future meeting.\r\n\r\nIn the Immigration Committee update, Mikhaela Sullivan, from the Réseau en immigration francophone du Centre-Sud-Ouest, announced that her organization participated in the 24th edition of Metropolis Canada, last March in Vancouver, where the Réseau animated a workshop, in collaboration with Professor Gertrude Mianda from York University, on \"the impact of racial discrimination on the integration of Francophone immigrants in Ontario\". This symposium allowed the participating organizations to work on strategies to fight racism.\r\n\r\nMélanie Robitaille of the Conseil scolaire catholique MonAvenir mentioned that the Conseil has been facing a severe shortage of teachers since the beginning of the pandemic. In addition, there seems to be a significant displacement of teachers in the east of the country, in New Brunswick, where the salary conditions are better. \"We have also seen this year that fewer francophone students are enrolling in French schools, another challenge for our board,\" she says.\r\n\r\nThe ABC communautaire, located in Welland, will soon be offering a series of courses, said the organization\'s executive director, Linda Johnston. These micro-courses will include Antidote basics, Tech Fridays and QuickBooks basics. \"We also plan to offer customized corporate training and are working on creating a website that will be more interactive and easy to navigate,\" Johnston said.\r\n\r\nFor the Hamilton/Niagara Community Health Centre, executive director France Vaillancourt confirmed the launch of a new website and her team is working to develop palliative care at Hospice Niagara.\r\n\r\nSOFIFRAN received a $50,600 grant from the Trillium Foundation for technology equipment that will allow for online activities and live broadcasts on YouTube.\r\n\r\nWe also received funding from FedDev Ontario for the development of a community of practice for black entrepreneurs,\" says SOFIFRAN Executive Director Fété Kimpiobi. It will be a platform to address the challenges (access to capital, business plan coaching, etc.) of black entrepreneurs as well as tools, workshops and networking opportunities to help them. This new service will address some of their challenges.\r\n\r\nSOFIFRAN will also offer a summer art camp with Justine Gogoua, a two-week program during which youth will learn about other cultures through storytelling, music and workshops (djembe, writing, painting and drawing.\r\n\r\nPlease note that the general assembly of SOFIFRAN will take place on Sunday, June 19.\r\n\r\nThe last news of the meeting: Muriel Thibault Gauthier\'s news about the St. John\'s Day celebration which will take place this year at the Auberge Richelieu in Welland, on Sunday June 26.\r\n\r\n \r\n\r\nPhoto: Fété Kimpiobi', 'les-activites-reprennent-dans-le-niagara', '1653497507.png', '2022-05-25 14:51:47', '2022-05-25 14:51:47'),
(13, 'SOFIFRAN propose les couleurs et saveurs de la culture africaine', 'SOFIFRAN offers the colors and flavors of African culture', 'Le Festival des arts folkloriques du Niagara et ses sept clubs culturels proposaient 11 portes ouvertes récemment dans la région et le 11 juin, à la paroisse Immaculée-Conception de St. Catharines, c’était au tour de SOFIFRAN de recevoir la communauté avec une porte-ouverte riche en couleurs, en saveurs et en musique africaines. Au programme, nourriture congolaise, ivoirienne, sénégalaise et nigérienne, ainsi qu’une performance de danse et musique du folklore africain avec l’artiste Justine Gogoua et l’excellent musicien spécialiste du djembé, Amadou Kienou. Selon la directrice générale de SOFIFRAN, Fété Ngira-Batware Kimpiobi, Il y avait un peu moins de personnes que par les années prépandémie mais l’événement s’est très bien déroulé. Les visiteurs ont beaucoup dansé. Sur cette photo, la jeune ambassadrice de SOFIFRAN qui était présente lors de cette porte-ouverte, Rebecca Surin et Mme Kimpiobi.\r\n\r\nLe Régional', 'The Niagara Folk Arts Festival and its seven cultural clubs recently held 11 open houses in the region and on June 11, at Immaculate Conception Parish in St. Catharines, it was SOFIFRAN\'s turn to welcome the community with an open house full of African colors, flavors and music. The program included Congolese, Ivorian, Senegalese and Nigerian food, as well as a performance of African folklore dance and music by artist Justine Gogoua and the excellent djembe musician Amadou Kienou. According to the general manager of SOFIFRAN, Fété Ngira-Batware Kimpiobi, there were a few less people than in pre-pandemic years but the event went very well. The visitors danced a lot. In this picture, the young ambassador of SOFIFRAN who was present at this open house, Rebecca Surin and Mrs. Kimpiobi.\r\n\r\nLe Régional', 'sofifran-propose-les-couleurs-et-saveurs-de-la-culture-africaine', '1657218510.jpeg', '2022-07-07 16:28:31', '2022-07-07 16:28:31'),
(14, 'La communauté ethnoculturelle de Welland partage ses saveurs exotiques', 'Welland\'s ethnocultural community shares its exotic flavours', 'Pour célébrer la Journée canadienne du multiculturalisme et la Fête du Canada avec ses communautés ethnoculturelles, SOFIFRAN a organisé une célébration rassembleuse le 1er juillet au Marché des fermiers de Welland. Un grand buffet gratuit a été offert au public avec animation musicale.\r\n\r\nIl y avait beaucoup de monde au centre-ville ce jour-là puisque la municipalité avait organisé des célébrations en même temps pour la fête du Canada au bord du Canal Welland. De plus, une grande partie de ces visiteurs ont fait un arrêt au marché pour déguster des plats traditionnels de la Palestine, de la Syrie, du Soudan, de l’Égypte, des Émirats Unis, de l’Érythrée, du Congo, du Burkina Faso, de la Guinée, du Cameroun, de la Côte d’Ivoire, de la Jamaïque et d’Haïti préparés par 27 femmes de la région sous la coordination de SOFIFRAN.\r\n\r\nBeaucoup de nourriture qui a permis à plus de 300 personnes de goûter les saveurs diversifiées des communautés ethnoculturelles du Niagara.\r\n« Nous avons pu offrir ce banquet de saveurs grâce à un projet financé par Patrimoine canadien pour la Journée canadienne du multiculturalisme qui a lieu habituellement le 27 juin, explique Fété Ngira-Batware Kimpiobi, directrice générale de SOFIFRAN. Cependant, étant donné que cette fête entrait en conflit avec la célébration locale de la Saint-Jean à l’Auberge Richelieu, nous avons décidé de célébrer cette journée en même temps que la fête du Canada. Nos communautés sont venues de St. Catharines, de Fort Erie et de Port Colborne pour participer à cet événement. »\r\n\r\nCôté musical, l’organisme a fait venir le groupe Borelson, un artiste d’origine africaine qui chante un rap engagé, et dont la musique est très appréciée par le jeune public. Puis, un DJ s’est occupé de mettre de la musique arabe et africaine pour satisfaire toutes les cultures représentées à cette activité.\r\n\r\n« Les personnes qui sont venues ont pu faire un voyage par le biais des saveurs de nos communautés et ont constaté que les immigrants font partie intégrante du paysage culturel de Welland. La réaction des gens a démontré l’urgence de la communauté au besoin de vivre ensemble, au retour à la normalité », conclut Mme Kimpiobi.\r\n\r\nLa prochaine activité de l’organisme sera les mini Jeux Olympiques de SOFIFRAN pour les enfants et aura lieu le 1er août au parc Chippawa à Welland.', 'To celebrate Canadian Multiculturalism Day and Canada Day with its ethnocultural communities, SOFIFRAN organized a unifying celebration on July 1st at the Welland Farmers Market. A large free buffet was offered to the public with musical entertainment.\r\n\r\nThere were many people downtown that day as the municipality had organized Canada Day celebrations at the same time on the Welland Canal. In addition, many of these visitors stopped by the market to taste traditional dishes from Palestine, Syria, Sudan, Egypt, United Emirates, Eritrea, Congo, Burkina Faso, Guinea, Cameroon, Ivory Coast, Jamaica and Haiti prepared by 27 local women under the coordination of SOFIFRAN.\r\n\r\nA lot of food that allowed more than 300 people to taste the diverse flavours of Niagara\'s ethnocultural communities.\r\nWe were able to offer this banquet of flavours thanks to a project funded by Canadian Heritage for Canadian Multiculturalism Day, which is usually held on June 27,\" explains Fété Ngira-Batware Kimpiobi, Executive Director of SOFIFRAN. However, since this holiday conflicted with the local St. John\'s Day celebration at Auberge Richelieu, we decided to celebrate this day at the same time as Canada Day. Our communities came from St. Catharines, Fort Erie and Port Colborne to participate in this event.\r\n\r\nOn the musical side, the organization brought in the group Borelson, an African-born artist who sings an engaging rap, and whose music is very popular with the young audience. Then, a DJ took care of putting on Arab and African music to satisfy all the cultures represented at this activity.\r\n\r\n\"People who came were able to take a journey through the flavours of our communities and see that immigrants are an integral part of the cultural landscape of Welland. The reaction of the people showed the urgency of the community to the need to live together, to return to normalcy,\" concludes Ms. Kimpiobi.\r\n\r\nThe organization\'s next event will be the SOFIFRAN Mini Olympics for children on August 1st at Chippawa Park in Welland.', 'la-communaute-ethnoculturelle-de-welland-partage-ses-saveurs-exotiques', '1658769244.jpeg', '2022-07-25 15:14:05', '2022-07-25 15:14:05'),
(15, 'Sofifran rassemble la communauté immigrante du Niagara', 'Sofifran brings Niagara\'s immigrant community together', 'Au début du mois d\'août, Sofifran a organisé son barbecue annuel qui, cette année, s’est enrichi d’une variété de jeux pour les jeunes de la communauté. Ces derniers ont montré une nette préférence pour le soccer.\r\n\r\nLa journée a connu un grand succès avec la participation d’une soixantaine de personnes venues de St. Catharines, Niagara Falls, Hamilton et Welland et de représentants d’Épelle-moi Canada. Les bénévoles de Sofifran ont travaillé très fort pour assurer la réussite de l’activité.\r\n\r\nDes membres de diverses communautés immigrantes du Niagara ont participé à l’activité, notamment des communautés africaines et musulmanes.\r\n\r\nUne fois de plus, la communauté a répondu à ce rendez-vous annuel « à la fortune du pot » et plusieurs mets exotiques variés ont été partagés. Et pour compléter cette activité communautaire, le jeune DJ Mabonzo a agrémenté l’ambiance avec une belle sélection musicale représentant la diversité culturelle des personnes rassemblées pour cette occasion.\r\n\r\nSource : Le Régional', 'Earlier this August , Sofifran held its annual barbecue, which this year included a variety of games for the youth of the community. The youth showed a clear preference for soccer.\r\n\r\nThe day was a great success with approximately 60 people from St. Catharines, Niagara Falls, Hamilton, Welland and representatives from Spell Me Canada attending. Sofifran volunteers worked hard to ensure the success of the event.\r\n\r\nMembers of Niagara\'s diverse immigrant communities participated in the event, including the African and Muslim communities.\r\n\r\nOnce again, the community responded to this annual \"potluck\" event and a variety of exotic foods were shared. And to complete this community activity, the young DJ Mabonzo livened up the atmosphere with a nice musical selection representing the cultural diversity of the people gathered for this occasion.\r\n\r\nSource : Le Régional', 'sofifran-rassemble-la-communaute-immigrante-du-niagara', '1674157059.jpeg', '2023-01-19 19:48:38', '2023-01-19 18:48:38'),
(16, 'Une fin d\'année pour SOFIFRAN', 'A great year-end for SOFIFRAN', 'On peut dire que les dernières semaines de 2022 auront été occupées pour les employées et membres de SOFIFRAN dans le Niagara.\r\n\r\nLe mois de décembre a débuté avec une soirée intergénérationnelle présentée à l’église Holy Trinity de Welland. « Cette activité a permis à des jeunes et des personnes immigrantes plus âgées de notre communauté de se rencontrer et de discuter avec des nouveaux arrivants dans la région de leur nouvelle vie au Canada, de leur intégration, explique Fété Ngira-Batware Kimpiobi, directrice générale de l’organisme.\r\n\r\nD’anciens immigrants ont partagé leurs expériences avec eux, les ont conseillés à faire du bénévolat dans la communauté, et acquérir les connaissances et compétences nécessaires pour accélérer leur intégration au marché du travail canadien.\r\n\r\nPuis le 11 décembre, en partenariat avec l’Office national du film du Canada, SOFIFRAN a projeté le film À pleine voix dans la salle communautaire de l’Hôtel de ville de Welland. Ce film montrait les stéréotypes concernant la communauté musulmane, des témoignages de femmes suivi d’une discussion entre l’auditoire (une trentaine de personnes) et Alaa Hejji, une personnalité de la communauté musulmane de la région.\r\n\r\nEt pour bien terminer une année chargée pour l’organisme, le réveillon de SOFIFRAN est venu clore une programmation bien remplie. Lors de cet événement, le député provincial de Niagara-Centre, Jeff Burch, était présent pour annoncer que Sofifran avait reçu une subvention de la Fondation Trillium de l’Ontario (FTO), un octroi de 50 600 $ du programme des communautés résilientes. Cette subvention a permis à l’organisme d’acquérir des équipements audiovisuels de haute qualité visant à élargir sa visibilité sur les médias sociaux, sur le Web et ses services.\r\n\r\nCe rendez-vous festif a permis à une centaine d’enfants de familles immigrantes du Niagara de chacun recevoir de SOFIFRAN une carte-cadeau pour les Fêtes.\r\n\r\nRichard Caumartin', 'The last few weeks of 2022 have been busy for SOFIFRAN staff and members in Niagara.\r\n\r\nDecember began with an intergenerational evening at Holy Trinity Church in Welland. This event allowed young and older immigrants from our community to meet and talk with newcomers to the region about their new life in Canada and their integration,\" explains Fété Ngira-Batware Kimpiobi, Executive Director of the organization.\r\n\r\nFormer immigrants shared their experiences with them, advised them to volunteer in the community, and acquire the knowledge and skills necessary to accelerate their integration into the Canadian labour market.\r\n\r\nThen on December 11, in partnership with the National Film Board of Canada, SOFIFRAN screened the film Full Voice in the Welland City Hall Community Room. This film showed stereotypes about the Muslim community, testimonies of women followed by a discussion between the audience (about 30 people) and Alaa Hejji, a personality from the Muslim community in the region.\r\n\r\nAnd to end a busy year for the organization, SOFIFRAN\'s New Year\'s Eve party rounded out a busy program. At the event, Niagara Centre MPP Jeff Burch was on hand to announce that Sofifran had received a $50,600 grant from the Ontario Trillium Foundation (OTF) Resilient Communities Program. This grant enabled the organization to acquire high quality audio-visual equipment to expand its visibility on social media, the web and its services.\r\n\r\nThis festive event allowed approximately 100 children from immigrant families in Niagara to each receive a holiday gift card from SOFIFRAN.\r\n\r\nRichard Caumartin', 'une-fin-dannee-pour-sofifran', '1674157571.jpeg', '2023-01-19 18:46:11', '2023-01-19 18:46:11'),
(17, 'SOFIFRAN présente la diversité culturelle du Mali', 'SOFIFRAN presents the cultural diversity of Mali', 'Dans le cadre des activités du Mois de l’histoire des Noirs (MHN), SOFIFRAN, en collaboration avec l’Université Brock et le First Ontario Performing Arts Centre (FOPAC) de St. Catharines, présente l’exposition Esprit du Mali du 4 au 10 février. Une œuvre exceptionnelle réalisée par les plus grands maîtres maliens de l’art textile et de la sculpture sur bois.\r\n\r\n« L’exposition Esprit du Mali est le fruit d’une vision engagée de valorisation et de préservation de savoirs traditionnels. Plus que jamais, ce joyau de la culture malienne exprime la conscience d’une profonde sagesse et d’une riche spiritualité. Elle nous transmet la force de l’action solidaire, tisse la toile créatrice qui unit nos différences et nous rappelle l’importance de cultiver la paix seulement, pour faire place à la prospérité », explique l’artiste commissaire de l’exposition, Stève Viès.\r\n\r\nLe 4 février, le vernissage de l’exposition lançait également la 16e édition de Festiv’Ébène, festival annuel de SOFIFRAN animé par Justine Gogoua et ayant pour thème « De la Boue au Bogolan, une esthétique identitaire ».\r\n\r\nLa directrice générale de l’organisme, Fété Ngira-Batware Kimpiobi s’est entourée de partenaires importants pour réussir à amener ce chef-d’œuvre dans le Niagara, dont David Vivian, directeur du Centre des études des arts et cultures à l’Université Brock et son collègue, Jean Ntakirutimana, professeur en études françaises au Département des Langues modernes, littératures et cultures.\r\n\r\n« Nous avons collaboré avec Mme Kimpiobi pour organiser cette exposition et engagé des étudiants de Brock à travailler sur le projet, indique M. Vivian. Nous voulions encadrer Festiv’Ébène pour que ce projet fasse partie intégrante des activités du MHN à l’Université. Le FOPAC a été un grand collaborateur du projet dont la directrice générale, Colleen Smith qui en avait fait une priorité. Grâce à cette collaboration, les élèves des écoles secondaires pourront venir admirer l’exhibition cette semaine. »\r\n\r\nAu vernissage, Stève Viès a fait une brève description des œuvres exposées, l’environnement et le contexte de leurs réalisations, des anecdotes vécues et inspirations ressenties lors du processus créatif, ainsi qu’une multitude de liens intéresants pour en apprendre sur la riche diversité culturelle du Mali.\r\n\r\nLa soirée d’ouverture à St. Catharines s’est terminée avec un spectacle de l’artiste burkinabé Amadou Kiénou et ses musiciens. L’auditoire ne s’est pas fait prier pour danser sur les rythmes de ce virtuose du djembé.\r\n\r\nFestiv’Ébène se terminera le 25 février à l’école Saint-Jean-de-Brébeuf à Welland avec un spectacle mettant en vedette les artistes OKAN, Woodney Pierre et Sage Matuzolele.\r\n\r\nLe Régional', 'As part of Black History Month (BHM) activities, SOFIFRAN, in collaboration with Brock University and the First Ontario Performing Arts Centre (FOPAC) in St. Catharines, presents the exhibition Spirit of Mali from February 4 to 10. An exceptional work by the greatest Malian masters of textile art and woodcarving.\r\n\r\n\"The Esprit du Mali exhibition is the result of a committed vision to promote and preserve traditional knowledge. More than ever, this jewel of Malian culture expresses the awareness of a profound wisdom and rich spirituality. It conveys to us the strength of solidarity, weaves the creative web that unites our differences and reminds us of the importance of cultivating peace only, to make way for prosperity,\" explains the artist curator of the exhibition, Stève Viès.\r\n\r\nOn February 4, the opening of the exhibition also launched the 16th edition of Festiv\'Ébène, SOFIFRAN\'s annual festival hosted by Justine Gogoua and whose theme is \"From Mud to Bogolan, an aesthetic of identity\".\r\n\r\nThe organization\'s executive director, Fété Ngira-Batware Kimpiobi, surrounded herself with important partners to successfully bring this masterpiece to Niagara, including David Vivian, director of the Centre for Arts and Cultural Studies at Brock University, and his colleague, Jean Ntakirutimana, a professor of French Studies in the Department of Modern Languages, Literatures and Cultures.\r\n\r\nWe collaborated with Ms. Kimpiobi to organize this exhibition and engaged Brock students to work on the project,\" says Vivian. We wanted to frame Festiv\'Ébène so that this project would be an integral part of the MHN activities at the University. FOPAC has been a great collaborator on the project with Executive Director Colleen Smith making it a priority. Thanks to this collaboration, high school students will be able to come and view the exhibit this week.\"\r\n\r\nAt the opening, Stève Viès gave a brief description of the works on display, the environment and context in which they were created, anecdotes and inspirations from the creative process, as well as a multitude of interesting links to learn about the rich cultural diversity of Mali.\r\n\r\nThe opening night in St. Catharines ended with a performance by Burkinabe artist Amadou Kiénou and his musicians. The audience did not hesitate to dance to the rhythms of this djembe virtuoso.\r\n\r\nFestiv\'Ébène will end on February 25 at the Saint-Jean-de-Brébeuf school in Welland with a show featuring artists OKAN, Woodney Pierre and Sage Matuzolele.\r\n\r\nLe Régional', 'sofifran-presente-la-diversite-culturelle-du-mali', '1675976774.jpg', '2023-02-09 20:06:14', '2023-02-09 20:06:14'),
(18, 'Projet apprentissage', 'Learning project', 'Dans le cadre de notre projet Appren’TISSAGE en collaboration avec l’organisme SOFIFRAN et le Conseil scolaire Viamonde, nous avons vécu plusieurs activités regroupant nos écoles dans le but de créer des liens et un sentiment d’appartenance à notre communauté diversifiée. Nous avons reçu des ateliers de DJing à l’école l’Héritage, LaMarsh et Franco-Niagara secondaire et avons fait danser nos petits du côté Franco-Niagara Élémentaire. Ensuite, nous avons organisé plusieurs projets dans le cadre du mois de l’histoire des noirs comme un repas multiculturel, une parade d’habits traditionnels, un conte africain animé par Fété Kimpiobi de SOFIFRAN, la participation du Band de musique de l’école secondaire Franco-Niagara au Festiv’Ébène organisé annuellement par SOFIFRAN.\r\n\r\nDe plus, dans le cadre du mois de la sensibilisation au Trouble du Spectre de l’Autisme, nous avons reçu un pour l’école Franco-Niagara élémentaire et l’école Nouvel Horizon un spectacle de l’artiste Vincent Bishop qui nous a parlé de ses défis en tant qu’Asperger et nous a montré ses talents de multi-instrumentiste. Sans oublier les élèves de 10e année qui ont été invité à un concours de Français à l’université de Brock à St. Catharines dans le but de créer des liens avec les autres écoles de la région. On remercie la micro-subvention Vice Versa de nous avoir permis de vivre tous ces rassemblements incroyables dans le cadre de notre projet.', 'As part of our Appren\'TISSAGE project in collaboration with SOFIFRAN and the Viamonde School Board, we have experienced several activities that bring our schools together in order to create a sense of belonging to our diverse community. We hosted DJing workshops at École l\'Héritage, LaMarsh and Franco-Niagara Secondary and had our little ones dance at Franco-Niagara Elementary. Then, we organized several projects for Black History Month such as a multicultural meal, a traditional dress parade, an African storytelling animated by Fété Kimpiobi from SOFIFRAN, the participation of the Franco-Niagara High School Music Band at the annual Festiv\'Ébène organized by SOFIFRAN.\r\n\r\nIn addition, as part of Autism Awareness Month, we received a performance by the artist Vincent Bishop from Franco-Niagara Elementary and Nouvel Horizon schools. Vincent spoke about his challenges as an Asperger\'s person and showed us his talents as a multi-instrumentalist. Not to mention the grade 10 students who were invited to a French competition at Brock University in St. Catharines in order to create links with other schools in the region. We would like to thank the Vice Versa micro grant for allowing us to experience all these incredible gatherings as part of our project.', 'projet-apprentissage', '1683657080.jpg', '2023-05-09 18:31:20', '2023-05-09 16:31:20'),
(19, 'Projet ART\'ificie - Micro-subvention Passep\'ART', 'Project ART\'ificie - Micro-subvention Passep\'ART', 'Dans le cadre de notre projet « ART’ifice » en collaboration avec l’organisme SOFIFRAN et le Conseil scolaire Viamonde, nous avons vécu plusieurs activités regroupant nos écoles dans le but de créer des liens et un sentiment d’appartenance à notre communauté diversifiée. Nous avons reçu des ateliers de danse de rue à l’école Nouvel Horizon, LaMarsh et Franco-Niagara élémentaire et secondaire. De plus, nous avons fait participer nos jeunes de l’école élémentaire LaMarsh et Franco-Niagara secondaire au festival de musique « MONDE LE SON! ». Ensuite, nous avons organisé plusieurs projets dans le cadre\r\n\r\nDe plus, dans le cadre du projet, nous avons organisé une journée de rassemblement pour célébrer tous nos efforts en y invitant le spectacle de Bill Bestiole – Les créatures du Jurassique . Sans oublier les élèves de 1ère  à 8e année qui ont été invité à aider à l’organisation de cette fête champêtre le 1 juin dernier des écoles suivantes É.É. LaMarsh, É.É. L’Héritage, É.É. Nouvel Horizon, É.É. Franco-Niagara et É.S. Franco-Niagara. On remercie la micro-subvention Passep’ART de nous avoir permis de vivre toutes ces rassemblements incroyables dans le cadre de notre projet ART’ifice.', 'As part of our \"ART\'ifice\" project, in collaboration with SOFIFRAN and the Viamonde School Board, we enjoyed a number of activities that brought our schools together to create links and a sense of belonging to our diverse community. We hosted street dance workshops at Nouvel Horizon, LaMarsh and Franco-Niagara elementary and secondary schools. In addition, our young people from LaMarsh Elementary and Franco-Niagara Secondary participated in the \"MONDE LE SON! We also organized a number of projects as part of the \"MONDE LE SON!\r\n\r\nAnd as part of the project, we organized a day-long gathering to celebrate all our efforts, inviting Bill Bestiole - Les créatures du Jurassique to perform. And let\'s not forget the students from grades 1 to 8 who were invited to help organize this country fair on June 1 from the following schools É.É. LaMarsh, É.É. L\'Héritage, É.É. Nouvel Horizon, É.É. Franco-Niagara and É.S. Franco-Niagara. We\'d like to thank the Passep\'ART microgrant for making it possible for us to experience all these incredible gatherings as part of our ART\'ifice project.', 'projet-artificie-micro-subvention-passepart', '1686068558.jpg', '2023-06-06 14:22:38', '2023-06-06 14:22:38'),
(20, 'Les organisations francophones de la région de Niagara se félicitent des changements intervenus en matière d\'immigration', 'Niagara francophone organizations laud immigration change', 'Les groupes locaux accueillent favorablement la rationalisation du processus visant à permettre à un plus grand nombre d\'immigrants francophones d\'entrer au Canada, mais le gouvernement fédéral devra abaisser les barrières à l\'emploi une fois qu\'ils seront arrivés, affirment-ils.\r\n\r\n\"Nous avions l\'habitude de leur dire qu\'une fois que vous serez ici, vous devrez oublier qui vous étiez dans votre pays\", a déclaré Fété Ngira-Batware Kimpiobi, directrice exécutive de Sofi Fran, une agence basée à Welland qui aide les nouveaux arrivants francophones à s\'intégrer dans la vie au Canada. \"Si vous étiez médecin, vous devez retourner à l\'école. Ne vous attendez pas à ce que le jour où vous arrivez ici au Canada, vous commenciez à pratiquer votre médecine. C\'est impossible.\"\r\n\r\nElle conseille aux immigrants potentiels d\'examiner les compétences et les certifications dont ils peuvent avoir besoin dans leur profession actuelle pour poursuivre leur carrière ici avant de demander à venir au Canada.\r\n\r\n\"C\'est à vous de comprendre cela et, ensuite, d\'aller voir quels sont les besoins en termes de droit ou de travail au Canada et de voir si vous avez les compétences pour ce type de travail\".\r\n\r\nEmmanuel Mompongo, coordinateur des programmes de nutrition et de sport de Sofi Fran, est du même avis.\r\n\r\n\"Disons qu\'un médecin arrive d\'un autre pays pour devenir médecin. \"Il ne se rend pas compte qu\'il est très coûteux de devenir médecin ici. Ils viennent en pensant qu\'ils vont commencer à travailler en tant que médecin\".\r\n\r\nLe plus souvent, la personne accepte donc n\'importe quel emploi pour l\'aider à s\'établir.\r\n\r\n\"La question est de savoir si j\'accepte n\'importe quel emploi, si je commence à travailler et à subvenir aux besoins de ma famille et si, lorsqu\'ils obtiendront un emploi au salaire minimum ou un emploi subalterne, ils n\'auront pas les moyens de payer autant\", a-t-il déclaré.\r\nEn annonçant ce plan au début du mois, Ginette Petitpas Taylor, ministre des langues officielles, a déclaré que \"la langue française fait partie intégrante et historique du riche paysage culturel et linguistique du Canada\" et que les changements \"renforceront la vitalité des communautés à travers le Canada et répondront à leurs réalités uniques\".\r\n\r\nEn outre, elle a déclaré que cela aiderait à combler les pénuries de main-d\'œuvre qui soutiennent un objectif économique identifié en invitant les candidats ayant une expérience professionnelle spécifique ou des compétences linguistiques en français à demander la résidence permanente au Canada.\r\n\r\nSean Fraser, ministre de l\'immigration, des réfugiés et de la citoyenneté, a qualifié ces changements d\'\"étape importante\" dans le cadre de l\'engagement du gouvernement à promouvoir la diversité linguistique et l\'inclusion.\r\n\r\n\"En ouvrant de nouvelles voies et de nouvelles possibilités, nous ne renforçons pas seulement nos liens avec la francophonie mondiale, mais nous construisons également un Canada plus fort et plus dynamique pour tous\", a-t-il déclaré. \"La contribution de l\'immigration francophone est d\'autant plus importante qu\'elle enrichit le caractère unique des communautés francophones sur les plans linguistique, démographique et économique.\r\n\r\nDans un communiqué de presse concernant ce changement, le gouvernement a déclaré que la sélection par catégorie aide le Canada à attirer des \"talents mondiaux\" et qu\'elle l\'aidera à répondre à son besoin de travailleurs francophones et bilingues pour soutenir l\'économie.\r\n\r\nMais Béatrice Groux, présidente de la Maison de la culture francophone du Niagara, a déclaré que si c\'est une chose d\'encourager davantage de personnes à venir ici, c\'en est une autre lorsqu\'il s\'agit de les préparer à la réussite.\r\n\"Il y a des gens qui sont venus ici et qui ont mis six mois à obtenir un permis de travail\", dit-elle, ajoutant que la situation peut être plus difficile si la personne exerce une profession qui est réglementée au Canada.\r\n\r\nLe plus souvent, les gens ont dû renoncer à leur ancienne carrière. C\'est ce qu\'elle a elle-même vécu. Elle a dû trouver une nouvelle carrière en tant qu\'enseignante Montessori après avoir quitté la France pour le Canada il y a 33 ans. En France, elle était ingénieur horticole.\r\n\r\n\"Il est très courant pour les immigrants de commencer une seconde carrière\", dit-elle. \"Tout le monde n\'a pas les moyens financiers.', 'Streamlining the process to allow more French speaking immigrants into Canada is welcomed by local groups, but the federal government will need to lower employment barriers once they get here, they say.\r\n\r\n“We used to tell them that once you are here, you\'ll have to forget who you were in your country,” said Fété Ngira-Batware Kimpiobi, executive director of Sofi Fran, a Welland-based agency that help francophone newcomers integrate into life in Canada. “If you were a doctor, you have to go back to the school. Don\'t expect that the day you come here in Canada, you will start to practice your medicine. It\'s impossible.”\r\n\r\nIt is something that she advises potential immigrants to look at what skills and certifications they may need for their current profession to continue their career here before applying to come to Canada.\r\n\r\n“It’s up to you to understand that and then after, to go to look what are the needs in terms of law or work in Canada and to see if you have the skills for that kind of work.”\r\n\r\nEmmanuel Mompongo, co-ordinator for Sofi Fran’s nutrition and sports programs, agreed.\r\n\r\n“Let’s say it’s a doctor who comes here from another country come here to be a doctor,” he said. “He doesn\'t realize that it\'s very expensive to become a doctor here to do that. They come with the expectation they\'re going to start working as a doctor.”\r\n\r\nSo, what happens most often is the person will take any job to help them get established.\r\n\r\n“(The question is) do I get just any job now and start working and supporting my family and then when they get the minimum wage job or maybe just a low-level job, they will not be able to afford that much,” he said.\r\n\r\nIn announcing the plan earlier this month, Ginette Petitpas Taylor, minister of official languages said that “the French language is an integral and historic part of Canada’s rich cultural and linguistic landscape,” and that the changes would “strengthen the vitality of communities across Canada and respond to their unique realities.”\r\n\r\nAdditionally, she said it would help address labour shortages that support an identified economic goal by inviting candidates with specific work experience or French language ability to apply for permanent residency in Canada.\r\n\r\nSean Fraser, minister of immigration, refugees and citizenship, called the changes “a significant milestone” for the government’s commitment to promoting linguistic diversity and inclusivity.\r\n\r\n“By opening new pathways and opportunities, we are not only strengthening our ties with the global Francophonie, but also building a stronger and more vibrant Canada for all,” he said. “The contribution of francophone immigration is even more critical because it enriches the linguistic, demographic and economic uniqueness of Francophone communities.”\r\n\r\nIn a news release about the change, the government said category-based selection helps Canada attract “global talent” and that it will help Canada meet its need for French-speaking and bilingual workers to support the economy.\r\n\r\nBut Beatrice Groux, president of La Maison de la culture francophone du Niagara (The House of Francophone Culture in Niagara), said while it’s one thing to encourage more people to come here, it’s another thing all together when it comes to setting them up for success.\r\n\r\n“There are people who have come here, and it has taken six months to get a work permit,” she said, adding the situation can be more difficult if the individual is in a profession that is regulated in Canada.\r\n\r\nMore often than not, people have had to give up on their previous careers all together. That was her own experience. She had to find a new career as a Montessori teacher after coming to Canada from France 33 years ago. In France she had been a horticultural engineer.\r\n\r\n“It’s very common among immigrants to start a second career,” she said. “Not everyone has the financial means.”', 'les-organisations-francophones-de-la-region-de-niagara-se-felicitent-des-changements-intervenus-en-matiere-dimmigration', '1690827454.png', '2023-07-31 16:17:34', '2023-07-31 16:17:34'),
(21, 'Sensibilisation à la nutrition saine et aux activités physiques', 'Raising awareness of healthy nutrition and physical activity', 'Ce nouveau projet de Sofifran est financé par la Fondation Trillium de l’Ontario dans le cadre de son programme des communautés résilientes.\r\n\r\nGrâce à cette subvention, Sofifran va pouvoir renforcer sa résilience et sa viabilité en mettant en œuvre un programme de bien-être culturellement adapté aux femmes immigrantes du Niagara.\r\n\r\nLes activités du programme visent à promouvoir le bien-être par des activités physiques et d\'outiller les femmes pour faire des choix de vie saine dans leur alimentation afin de bénéficier des connaissances acquises lors de présentations pour elles et pour leurs familles.', 'This new Sofifran project is funded by the Ontario Trillium Foundation as part of its Resilient Communities Program.\r\n\r\nThanks to this grant, Sofifran will be able to strengthen its resilience and sustainability by implementing a culturally adapted wellness program for immigrant women in Niagara.\r\n\r\nThe program\'s activities aim to promote wellness through physical activity, and to equip women to make healthy lifestyle choices in their diet, so that they can benefit from the knowledge gained from the presentations for themselves and their families.', 'sensibilisation-a-la-nutrition-saine-et-aux-activites-physiques', '1690983066.jpeg', '2023-08-02 11:31:06', '2023-08-02 11:31:06'),
(22, 'COMMUNIQUÉ PRESSE  Pour diffusion immédiate  SOFIFRAN – BÉNÉFICIAIRE D’UNE SUBVENTION DE DÉVÉLOPPEMENT  ÉCONOMIQUE DE LA FONDATION CANADIENNE DES FEMMES', 'PRESS RELEASE  For immediate release   SOFIFRAN - RECIPIENT OF AN ECONOMIC DEVELOPMENT GRANT  GRANT FROM CANADIAN WOMEN\'S FOUNDATION', 'WELLAND, le 7 septembre 2023 – SOFIFRAN (Solidarité des femmes et familles interconnectées francophones du Niagara) a l’immense plaisir d’annoncer à la communauté l’octroi de la Fondation canadienne des femmes, d’une subvention de développement économique de 260,000.00 $, échelonnée sur une période de 4 ans. \r\n\r\nGrâce à cette subvention, Sofifran peut mettre en place un programme permettant aux femmes immigrantes de se lancer en entreprenariat dans le domaine des services de garde en milieu \r\nfamilial. Avec ce soutien financier les femmes pourront acquérir les connaissances, les outils et les capacités nécessaires pour gérer une entreprise et offrir des services de garde fiables, sécuritaires et abordables pour les familles du Niagara. \r\nDepuis sa création en 2007, SOFIFRAN oeuvre pour le renforcement des capacités des communautés issues de l\'immigration et vivant en situation linguistique minoritaire afin de favoriser leur épanouissement et leur intégration au sein de leurs collectivités d\'accueil dans la région du Niagara. Notre organisme est une plateforme francophone qui vise la promotion et la participation des immigrants dans les secteurs économique et social, tout en favorisant leur épanouissement sur le plan artistique et culturel pour une meilleure intégration au Canada.', 'WELLAND, September 7, 2023 - SOFIFRAN (Solidarité des femmes et familles interconnectées francophones du Niagara) is extremely pleased to announce to the community the awarding of a $260,000.00 economic development grant over a 4-year period from the Canadian Women\'s Foundation. \r\n\r\nThanks to this grant, Sofifran will be able to set up a program enabling immigrant women to become entrepreneurs in the field of family daycare services. \r\nservices. With this financial support, women will be able to acquire the knowledge, tools and skills they need to run a business and offer reliable, safe and affordable childcare services to Niagara families. \r\nSince its inception in 2007, SOFIFRAN has been working to build the capacity of immigrant and linguistic minority communities in Niagara, in order to foster their development and integration into their host communities. Our organization is a Francophone platform that promotes the economic and social participation of immigrants, while fostering their artistic and cultural development for better integration into Canada.', 'communique-presse-pour-diffusion-immediate-sofifran-beneficiaire-dune-subvention-de-developpement-economique-de-la-fondation-canadienne-des-femmes', '1694122919.png', '2023-09-07 19:41:59', '2023-09-07 19:41:59'),
(23, 'Émission de clôture', 'Closing issue', 'Mesdames, Messieurs, \r\n\r\nNous aimerions remercier chaleureusement tous ceux qui ont mis à l\'honneur la diversité des cultures francophones dans le cadre des célébrations du Mois de la francophonie. \r\n\r\nVeuillez cliquer sur le lien ci-dessous pour réécouter l\'émission de ce dimanche 31 mars 2024.\r\n\r\nhttps://www.potpourrishow.com/20240331.mp3\r\n\r\nUn immense merci à tous nos partenaires clés et invité.e.s :\r\nPre Aurélie Lacassagne, nouvelle rectrice de l’Université de Hearst \r\nFété Ngira-Batware Kimpiobi, directrice générale de Sofifran \r\nElie Bisalli, chargée des relations de presse et de la communication - Éditions Prise de parole \r\n\"La langue française, pour moi, c’est plus qu’une chanson que l’on fredonne, qu’un poème qui nous inspire, qu’un livre que l’on dévore, que des mots qui nous transportent, mais c’est surtout des millions d’interlocuteurs, un réseau universel de francophones et de francophiles, qui se retrouvent dans une langue qui a de la résonance.\" - Une auditrice de Toulouse, France', 'Ladies and Gentlemen, \r\n\r\nWe\'d like to extend our warmest thanks to all those who honored the diversity of French-speaking cultures as part of the Mois de la francophonie celebrations. \r\n\r\nPlease click on the link below to listen to the program from this Sunday, March 31, 2024.\r\n\r\nhttps://www.potpourrishow.com/20240331.mp3\r\n\r\nA huge thank you to all our key partners and guests:\r\nPre Aurélie Lacassagne, new Rector of Université de Hearst \r\nFété Ngira-Batware Kimpiobi, Managing Director of Sofifran \r\nElie Bisalli, Press Relations and Communications Manager - Éditions Prise de parole \r\n\"For me, the French language is more than a song we hum, a poem that inspires us, a book we devour, words that transport us, but above all it\'s millions of interlocutors, a universal network of francophones and francophiles, who find themselves in a language that resonates.\" - A listener from Toulouse, France \r\n\r\n\r\nTranslated with DeepL.com (free version)', 'emission-de-cloture', '1712150254.png', '2024-04-03 11:17:35', '2024-04-03 11:17:35'),
(24, 'Salon du livre des Francophonies du Niagara.', 'Niagara Francophonie Book Fair.', 'Chers auteurs, chères auteures, partenaires, professeurs, techniciens et bénévoles,\r\n\r\n \r\n\r\nJe vous invite à découvrir quelques clichés du Salon du livre des Francophonies du Niagara. \r\n\r\nJuste un léger souvenir du Safran pour évoquer les instants éphémères où la magie du mot, de la lettre et du livre a côtoyé la convivialité et la générosité. \r\n\r\nCes photos ont capturé  ces moments fugaces où la bonne humeur et la chaleur humaine ont brillé de mille feux, laissant une empreinte indélébile dans nos cœurs.\r\n\r\nMerci infiniment pour votre contribution et votre dévouement.\r\n\r\nÀ l\'année prochaine !', 'Dear authors, partners, teachers, technicians and volunteers,\r\n\r\n \r\n\r\nI invite you to discover a few snapshots of the Salon du livre des Francophonies du Niagara. \r\n\r\nI\'ve included just a few memories of Le Safran to evoke the fleeting moments when the magic of words, letters and books rubbed shoulders with conviviality and generosity. \r\n\r\nThese photos capture those fleeting moments when good humor and human warmth shone brightly, leaving an indelible imprint on our hearts.\r\n\r\nThank you so much for your contribution and dedication.\r\n\r\nUntil next year!', 'salon-du-livre-des-francophonies-du-niagara', '1712249825.jpg', '2024-04-04 14:57:05', '2024-04-04 14:57:05');
INSERT INTO `blogs` (`id`, `title_fr`, `title_en`, `description_fr`, `description_en`, `slug`, `image`, `created_at`, `updated_at`) VALUES
(25, 'Sofifran s’illustre au cours du Mois de l’histoire des Noirs', 'Sofifran shines during Black History Month', '« Nous voulons réduire la distance entre les peuples », proclame Fété Ngira-Batware Kimpiobi, directrice générale de Sofifran. C’est ainsi que l’organisme a planifié Festiv’Ébène, un festival annuel où de nombreuses activités musicales et d’excellentes performances se succèdent pour offrir à la communauté une expérience mémorable.\r\n\r\nLes célébrations ont débuté le 6 février, au Département de Langues modernes, Littérature et Culture de l’Université Brock. Mme Kimpiobi y a effectué une présentation de son organisme Sofifran : son histoire, sa mission, ses objectifs ainsi que le chemin parcouru depuis sa création. Elle a également évoqué un drame que subissent certaines personnes nées au Canada ou qui ont immigré ici dès leur jeune âge : « posséder la double nationalité mais avoir le sentiment de n’appartenir à aucun des deux peuples ».\r\n\r\nPuis le 10 février, au centre multiculturel Niagara Folk Arts de St. Catharines, et le lendemain à Hamilton, ont eu lieu plusieurs ateliers et spectacles dont De votre foyer au nôtre. Cette série part à la découverte des richesses culturelles des Franco-Ontariens de toutes origines par l’entremise de quatre artistes : Wandara Topzo, musicien d’origine centrafricaine jouant le djembé et autres instruments à cordes; Saïd Ben Youcef, ce conteur d’origine maghrébine a lu des contes des Mille et une nuits; Paul Lemelin, musicien et violoniste renommé, et Djennie Laguerre, conteuse qui a présenté des contes du patrimoine haïtien. « La beauté des contes est qu’ils ont tous une morale, mais c’est à chacun de l’interpréter à sa façon », relate Mme Kimpiobi.\r\n\r\nExposition\r\n\r\nUne exposition sous le thème L’écho des grands lacs africains : les voix et les voies du Rwanda a été présentée durant tout le mois à la bibliothèque de l’Université Brock. Elle est la première d’un projet de trois ans sur trois pays africains. Cette année, le Rwanda était à l’honneur par le biais d’artefacts, d’objets traditionnels et d’artisanat. « L’exposition a suscité de nombreuses questions auprès des jeunes et a levé un voile sur la culture », commente la directrice de Sofifran.\r\n\r\nUne journée spéciale\r\n\r\nL’école secondaire Franco-Niagara de Welland a organisé le 13 février une journée pour souligner le Mois de l’histoire des Noirs. Mme Kimpiobi y a donné un atelier sur les contes africains.\r\n\r\n« J’ai commencé par des énigmes et des devinettes du pays. Puis, j’ai raconté une histoire sur les divers comportements des gens face à l’argent, la richesse et les conséquences des décisions qu’ils ont prises. J’ai ensuite laissé les jeunes se faire leur propre moralité », poursuit-elle.\r\n\r\nUne soirée mémorable\r\n\r\nPour clôturer le mois en beauté, le 24 février a eu lieu, au centre multiculturel Niagara Folk Arts, une soirée avec des artistes renommés et de nouveaux venus.\r\n\r\nDes discours ont été prononcés avant que le repas préparé par un couple ghanéen soit servi. Diverses prestations musicales ont suivi. Des artistes de la relève ont ouvert le bal avec des danses modernes. Il y avait les Snowbirds, des jeunes âgés de 3 à 8 ans, et The Move, des ados de 13 à 18 ans.\r\n\r\n« C’est important de les mettre en valeur, de les reconnaître et de les encourager. Ils ont besoin d’avoir de l’estime de soi dans ce monde où règne l’instabilité Les participants aux activités du 6 février à l’Université Brock émotionnelle », ajoute-t-elle. D’autres artistes se sont démarqués tels que Borelson, un rappeur aux messages puissants pour stimuler le peuple noir; Abel Maxwell, chanteur qui a fait danser tous les participants grâce à son style musical; et Sérénade Mizik, la touche caraïbéenne de la soirée avec du Kompa et du Zouk. « De ce magnifique mois, je retiens deux grandes idées. Premièrement, les gens ont besoin de socialiser. Ils sont heureux de se regrouper et d’échanger alors Sofifran va organiser davantage de soirées. Deuxièmement, pour rassembler la diversité nous devons continuer de partager nos cultures respectives avec fierté. Chacun apporte sa valeur ajoutée et apprend des autres, c’est ainsi que nous réduirons la distance entre les peuples », ajoute la directrice de Sofifran.\r\n\r\nSalon du livre SAFRAN\r\n\r\nLe premier Salon du livre des francophonies du Niagara (SAFRAN) a eu lieu en 2020, juste avant le début de la pandémie. Cette année, Sofifran le relance pour sa deuxième édition, du 21 au 24 mars. « L’objectif de ce Salon est de mettre en lumière la littérature francophone du Niagara et plus largement celle de l’Ontario français, d’où le terme de francophonie plurielle, le Niagara possède beaucoup de cultures différentes et c’est l’occasion de mettre notre belle région en valeur », précise Mme Kimpiobi.\r\n\r\nL’ouverture du Salon se fera le 21 mars au First Ontario Performing Arts Centre de l’Université Brock. Le thème choisi est Les contradictions des lettres.\r\n\r\n« Nous aborderons cette dichotomie qui existe en chacun de nous. On pense, mais on dit autre chose; on planifie, mais on agit autrement. À l’aide de plusieurs tables rondes, nous discuterons des différents angles de cette contradiction, les conséquences qu’elle engendre et comment y faire face », poursuit-elle.\r\n\r\nLe comité directeur du SAFRAN, composé de membres de l’Université de Brock et de la communauté ayant pour la plupart été publiés, s’est réuni pour choisir les auteurs invités.\r\n\r\nAu total, une vingtaine d’auteurs et une quinzaine de maisons d’édition seront présents au Salon. Il y aura un accent particulier sur la jeunesse.\r\n\r\nDe plus, Fété Kimpiobi présentera elle-même son projet en cours : Le beignet africain. « Ce sera un beau Salon avec notre marque personnelle et notre originalité », conclut-elle.\r\n\r\nLe président d’honneur de la deuxième édition du SAFRAN sera Paul Savoie, originaire du Manitoba et vivant à Toronto et auteur d’une quarantaine de livres en français et en anglais, dans plusieurs genres littéraires.\r\n\r\nhttps://leregional.com/sofifran-sillustre-au-cours-du-mois-de-lhistoire-des-noirs/', '“We want to reduce the distance between people,” proclaims Fété Ngira-Batware Kimpiobi, general director of Sofifran. This is how the organization planned Festiv’Ébène, an annual festival where numerous musical activities and excellent performances follow one another to offer the community a memorable experience.\r\n\r\nThe celebrations began on February 6 at the Department of Modern Languages, Literature and Culture at Brock University. Ms. Kimpiobi made a presentation of her organization Sofifran: its history, its mission, its objectives as well as the path traveled since its creation. She also spoke of a tragedy experienced by certain people born in Canada or who immigrated here at a young age: “having dual nationality but having the feeling of not belonging to either people”.\r\n\r\nThen on February 10, at the Niagara Folk Arts multicultural center in St. Catharines, and the next day in Hamilton, several workshops and performances took place including From Your Home to Ours. This series explores the cultural riches of Franco-Ontarians of all origins through four artists: Wandara Topzo, a musician of Central African origin playing the djembe and other stringed instruments; Saïd Ben Youcef, this storyteller of North African origin, read tales from the Arabian Nights; Paul Lemelin, renowned musician and violinist, and Djennie Laguerre, storyteller who presented tales of Haitian heritage. “The beauty of tales is that they all have a moral, but it is up to each person to interpret it in their own way,” relates Ms. Kimpiobi.\r\n\r\nExposure\r\n\r\nAn exhibition under the theme The Echo of the Great African Lakes: The Voices and Ways of Rwanda was on display throughout the month at the Brock University Library. It is the first of a three-year project in three African countries. This year, Rwanda was in the spotlight through artifacts, traditional objects and crafts. “The exhibition raised many questions among young people and lifted the veil on culture,” comments the director of Sofifran.\r\n\r\nA special day\r\n\r\nThe Franco-Niagara secondary school in Welland organized a day on February 13 to mark Black History Month. Ms. Kimpiobi gave a workshop on African tales.\r\n\r\n“I started with riddles and riddles about the country. Then, I told a story about the various behaviors people have when it comes to money, wealth and the consequences of the decisions they make. I then let the young people form their own morality,” she continues.\r\n\r\nA memorable evening\r\n\r\nTo end the month in style, on February 24, an evening took place at the Niagara Folk Arts multicultural center with renowned artists and newcomers.\r\n\r\nSpeeches were made before the meal prepared by a Ghanaian couple was served. Various musical performances followed. Emerging artists opened the show with modern dances. There were the Snowbirds, young people aged 3 to 8, and The Move, teenagers aged 13 to 18.\r\n\r\n“It’s important to highlight them, recognize them and encourage them. They need to have self-esteem in this world where instability reigns. Participants in the February 6 activities at Brock University are emotional,” she adds. Other artists stood out such as Borelson, a rapper with powerful messages to stimulate black people; Abel Maxwell, singer who made all the participants dance with his musical style; and Sérénade Mizik, the Caribbean touch of the evening with Kompa and Zouk. “From this magnificent month, I remember two big ideas. First, people need to socialize. They are happy to get together and talk so Sofifran will organize more evenings. Second, to bring diversity together we must continue to share our respective cultures with pride. Everyone brings their added value and learns from others, this is how we will reduce the distance between people,” adds the director of Sofifran.\r\n\r\nSAFRAN Book Fair\r\n\r\nThe first Salon du livre des francophonies du Niagara (SAFRAN) took place in 2020, just before the start of the pandemic. This year, Sofifran is relaunching it for its second edition, from March 21 to 24. “The objective of this Salon is to highlight the Francophone literature of Niagara and more broadly that of French Ontario, hence the term plural Francophonie, Niagara has many different cultures and this is the opportunity to showcase our beautiful region,” explains Ms. Kimpiobi.\r\n\r\nThe Salon opens on March 21 at the First Ontario Performing Arts Center at Brock University. The chosen theme is The Contradictions of Letters.\r\n\r\n“We will address this dichotomy that exists in each of us. We think, but we say something else; we plan, but we act differently. With the help of several round tables, we will discuss the different angles of this contradiction, the consequences it generates and how to deal with it,” she continues.\r\n\r\nThe SAFRAN Steering Committee, comprised of mostly published members from Brock University and the community, met to select guest authors.\r\n\r\nIn total, around twenty authors and around fifteen publishing houses will be present at the Salon. There will be a particular emphasis on youth.\r\n\r\nIn addition, Fété Kimpiobi will herself present her current project: The African donut. “It will be a beautiful Salon with our personal brand and our originality,” she concludes.\r\n\r\nThe honorary president of the second edition of SAFRAN will be Paul Savoie, originally from Manitoba and living in Toronto and author of around forty books in French and English, in several literary genres.\r\n\r\nhttps://leregional.com/sofifran-sillustre-au-cours-du-mois-de-lhistoire-des-noirs/', 'sofifran-sillustre-au-cours-du-mois-de-lhistoire-des-noirs', '1712318835.jpeg', '2024-04-05 10:07:16', '2024-04-05 10:07:16'),
(26, 'Sofifran souligne l’apport des femmes dans sa communauté', 'Sofifran highlights the contribution of women in its community', 'Dans le cadre de la Journée internationale des droits des femmes, Sofifran recevait le 9 mars sa communauté féminine pour célébrer cette occasion importante à l’Hôtel Four Points Sheraton de Thorold.\r\n\r\nAu programme de la soirée animée par Justine Djoléi Gogoua, quelques témoignages, de nombreux partages entre femmes issues de communautés diverses, un souper aux saveurs exotiques préparé par la chef Yorly et une prestation du comédien et metteur en scène Said Benyoucef inspirée des Mille et une nuits.\r\n\r\nD’entrée de jeu, l’animatrice a fait le tour des tables pour que les participantes prennent un moment de réflexion sur leur réalité en tant que femmes et ressentent un sentiment de fierté. « Nous savons comment faire avancer les choses dans notre vie et dans la société la plupart du temps, dit-elle. La femme est la clé de tout. Sans elle, il n’y a rien! Et l’amour de soi est très important. »\r\n\r\nPar la suite, la présidente de Sofifran, Gina Isidore a pris la parole. « Cette Journée internationale des droits des femmes devrait se tenir 365 jours par année car nous, les femmes, nous ne chômons jamais, déclare-t-elle. Nous nous coiffons de plusieurs chapeaux, à la fois mère, épouse, enseignante et psychologue pour ne nommer que ceux-là. » Elle a ensuite remercié les commanditaires de la soirée et les nombreux partenaires de l’organisme.\r\n\r\nAprès son allocution, les dirigeantes ont rendu hommage et exprimé leur gratitude à l’ancienne présidente de Sofifran de 2018 à 2021, Nyarayi Kapisavanhu. Cette dernière occupe notamment la vice-présidence du conseil d’administration du Niagara Region Police Service Board, où elle a été la première femme noire élue en mars 2023. Elle préside aussi le Niagara District Council of Women et siège au conseil d’administration de Brock University.\r\n\r\nElle a initié, il y a sept ans, un programme de mentorat destiné aux jeunes Noirs, visant à améliorer l’économie, l’éducation et le bien-être des communautés marginalisées à travers des actions locales, en Europe et en Afrique australe. Mme Kapisavanhu a remercié Fété Ngira-Batware Kimpiobi, la directrice générale de Sofifran.\r\n\r\n« Maman Fété a toujours été là pour moi et m’a toujours encouragée de croire en moi, raconte la présidente sortante. Souvent, ce n’est pas facile de croire en tes possibilités surtout quand il y a des gens dans ton entourage qui ne croient pas en toi. Merci Fété pour m’avoir donné l’opportunité de servir la communauté sous l’égide de Sofifran et c’est cette expérience qui m’a fait comprendre ce qu’est une communauté, et que j’ai appris à naviguer au travers des différents services et organismes du Niagara. Mon parcours a été influencé par ma rencontre avec maman Fété et c’est avec humilité que je reçois cet hommage de vous. »\r\n\r\nUn buffet a ensuite été servi pour permettre à l’auditoire d’échanger et de réseauter. Après le repas, Said Benyoucef a lu un texte tiré de Shahrazade démissionne, une parodie loufoque qu’il a créée et présentée dans le cadre du Festival du monde arabe de Montréal il y a quelques années. L’histoire symbolise le combat de la femme décrit sous la forme des traditions des Mille et une nuits avec « l’imaginaire, les mots, l’humour et les convictions » de l’auteur.\r\n\r\nAprès toutes ces émotions, les femmes ont envahi la piste de danse et célébré jusqu’à minuit.\r\n\r\nhttps://leregional.com/sofifran-souligne-lapport-des-femmes-dans-sa-communaute/', 'As part of International Women\'s Day, Sofifran hosted its female community on March 9 to celebrate this important occasion at the Four Points Sheraton Hotel in Thorold.\r\n\r\nOn the program for the evening hosted by Justine Djoléi Gogoua, some testimonies, numerous sharings between women from diverse communities, a dinner with exotic flavors prepared by chef Yorly and a performance by actor and director Said Benyoucef inspired by the Thousand and One nights.\r\n\r\nFrom the outset, the facilitator went around the tables so that the participants took a moment to reflect on their reality as women and feel a sense of pride. “We know how to get things done in our lives and in society most of the time,” she says. The woman is the key to everything. Without it, there is nothing! And self-love is very important. »\r\n\r\nSubsequently, the president of Sofifran, Gina Isidore spoke. “This International Women’s Day should be held 365 days a year because we, women, are never idle,” she declares. We wear many hats: mother, wife, teacher and psychologist to name a few. » She then thanked the sponsors of the evening and the organization’s many partners.\r\n\r\nAfter her speech, the leaders paid tribute and expressed their gratitude to the former president of Sofifran from 2018 to 2021, Nyarayi Kapisavanhu. The latter notably holds the vice-president of the board of directors of the Niagara Region Police Service Board, where she was the first black woman elected in March 2023. She also chairs the Niagara District Council of Women and sits on the board of directors of Brock University.\r\n\r\nSeven years ago, she initiated a mentoring program for young black people, aimed at improving the economy, education and well-being of marginalized communities through local actions, in Europe and southern Africa. Ms. Kapisavanhu thanked Fété Ngira-Batware Kimpiobi, the general director of Sofifran.\r\n\r\n“Mama Fété was always there for me and always encouraged me to believe in myself,” says the outgoing president. Often, it\'s not easy to believe in your possibilities, especially when there are people around you who don\'t believe in you. Thank you Fété for giving me the opportunity to serve the community under the aegis of Sofifran and it was this experience that made me understand what a community is, and that I learned to navigate through the different services and organizations in Niagara. My journey was influenced by my meeting with Maman Fété and it is with humility that I receive this tribute from you. »\r\n\r\nA buffet was then served to allow the audience to discuss and network. After the meal, Said Benyoucef read a text from Shahrazade resigns, a crazy parody that he created and presented as part of the Montreal Arab World Festival a few years ago. The story symbolizes the woman\'s struggle described in the form of the traditions of the Arabian Nights with the author\'s “imaginary, words, humor and convictions”.\r\n\r\nAfter all these emotions, the women invaded the dance floor and celebrated until midnight.\r\n\r\nhttps://leregional.com/sofifran-souligne-lapport-des-femmes-dans-sa-communaute/', 'sofifran-souligne-lapport-des-femmes-dans-sa-communaute', '1712319645.jpeg', '2024-04-05 10:20:45', '2024-04-05 10:20:45'),
(27, 'LE SALON DU LIVRE DU NIAGARA PERMET DE RETROUVER SON AME D’ENFANT', 'The Niagara Book Fair allows you to find your child\'s soul', 'ALEXIA GROUSSON\r\n	Pour une deuxième année consecutive, Sofifran a présenté le Salon du livre Francophone du Niagara (SAFRAN), du 21 au 24 mars a l’Université Brock de St Catharines. L’évément littéraire avait pour thème “Les contradiction de l’Etre ”, inspiré de la citation de Paul Valéry « Nos contradictions font la substance de notre activité d’esprit »\r\n	En avant-première et pour souligner la Journée mondiale de la marionnette, la Maison de la culture francophone du Niagara (MCFN) avait invité la troupe Québecoise Le chemin qui marche, spécialisée dans les arts de la marionnette à travers les courtes-formes sur tables sans parole. Ils ont presentés deux de leurs spectacles – Inukshuk et Arbre – au First Ontario Performing Arts Centre.\r\n	« Le théâtre d’objets, dit ke 11e art est peu répandu dans la région. C’était donc la parfait occasion de l’exposer et ouvrir les horizons ddes participants en leur donnant accès a cette expérience culturelle enrichissante. Le lien avec la nature et les matières premières est different en fonction de nos cultures mais le pouvoir de l’art, c’est de nous rassembler francophones et francophiles en une communauté unie », Commente Stéphanie Filippi, présidente de la MCFN,\r\n	Le SAFRAN a été divisé en plusieurs catégories : ateliers, tables rondes, discussion, foire aux éditeurs, lectures de conte et lectures-spectacles. \r\nAteliers, discussions et lectures\r\n	Beaucoup d’ateliers étaient consacrés à la jeunesse. Ils portaient sur la creation de robot et drones ou encore sur la géographie des Grand Lacs d’Amérique par rapport à ceux d’Afrique. Khadydja Ndoye, autrice du Monde de Sabbih, était l’animatrice des STEM interactifs pour les jeunes. Son livre traite du parcours de la jeunesse Sabbih qui veut devenir ingénieure en robotique.\r\n	Les ateliers créatifs intergénérationnels, organisés par Mélina Seymour et Chloé Gardel, étaients basés sur des sujets tels que l’intelligence artificielle, la technologie et l’afro culturisme. Enfin, un atelier d’auteurs a eu lieu avec Paul Savoie, président d’honneur du Salon et Nicholas Hauck. Une dizaine d’écrivains y ont participés. \r\n	Les discusions ont été divisées en catégories. Les tables rondes ont arbordés differents sujets liés au thème principal.\r\n	« Nous avons arbordé plusieurs domaines contradictoires de l’écriture. Par exemple, nous avons essayés de comprendre les histoires anciennes et modernes à travers différent point de vue et évoqué les perspectives d’un historien, d’un écrivain ou d’un lecteur, mais aussi les differences qui existent entre l’endroit où l’on se trouve et la periode dans laquelle on vit. Une personne du Moyen-âge en Europe ne verra pas l’histoire de la meme façon qu’une autre en Afrique dans les années 2000 », explique Nafée Faîgou, présidente du SAFRAN.\r\n	D’autres contradictions, telles que l’espoir et le désespoir, le corsp et l’esprit ou encore nature et plastique, ont été soulévées.\r\n	Deux grandes discussions ont également eu lieu le vendredi et le samedi. La première, tenue par Fété Kimpiobi, Directrice Générale de Sofifran, arbordait la francophonie plurielle en Ontario,\r\n	La seconde par Mme Faîgou, portais sur la croyance en soi et en autrui.\r\n	Une lecture de conte pour enfant avec devinettes a eu lieu le Dimanche avec Karim Sigéré, Papa raconte, Fété Kimpiobi et Nyote. Une lecture-spectacle s’est tenu le Dimanche avec Gaton Mabaya, Kalambayi Kalula, Aristote Kavungu et Amadou Ba. \r\n	De plus, une foire aux éditeurs était présentée chaque jour. Ces derniers avaient l’occasion de montrer leurs livres, de discuter avec les visiteurs et d’expliquer leur vision du monde de l’écriture.\r\n	« Ce salon était merveilleux, Nous avons retrouvé notre âme d’enfant pendant quelques jours. Les artistes, écrivains, illustrateurs, éditeurs, libraires, enseignants et participants ont été fabuleux », conclut Nafée Faîgou.', 'Alexia Grousson\r\nFor a second consecutive year, Sofifran presented the French -speaking Book Fair in Niagara (Safran), from March 21 to 24 at Brock University in St Catharines. The theme of \"the contradiction of Being\", inspired by the quote from Paul Valéry \"our contradictions, have the substance of our spirit activity\"\r\nIn preview and to highlight the World Puppet Day, the Maison de la Culture Francophone du Niagara (MCFN) had invited the Quebec Troupe Le Chemin which walks, specializing in the puppet arts through the short-tables on tables without speaking. They presented two of their shows - Inukshuk and Tree - at First Ontario Performing Arts Center.\r\n\"The theater of objects,\" said Ke 11th Art is not widespread in the region. It was therefore the perfect opportunity to exhibit it and open the horizons of participating by giving them access to this enriching cultural experience. The link with nature and raw materials is different according to our cultures, but the power of art is to bring us together Francophones and Francophiles into a united community, \"comments Stéphanie Filippi, president of the MCFN,\r\nThe saffron has been divided into several categories: workshops, round tables, discussion, publishers, tale readings and spectacles.\r\nWorkshops, discussions and readings\r\nMany workshops were devoted to youth. They focused on the creation of robot and drones or to the geography of the great lakes of America compared to those of Africa. Khadydja Ndoye, author of the Sabbih world, was the animator of interactive STEMs for young people. His book deals with the Sabbih youth journey which wants to become a robotics engineer.\r\nIntergenerational creative workshops, organized by Mélina Seymour and Chloé Gardel, state -based statements such as artificial intelligence, technology and Afro bodybuilding. Finally, an authors\' workshop took place with Paul Savoie, honorary president of the show and Nicholas Hauck. A dozen writers participated.\r\nThe discusions were divided into categories. The round tables have different subjects linked to the main theme.\r\n\"We have armed several contradictory areas of writing. For example, we have tried to understand the old and modern stories through different point of view and evoked the perspectives of a historian, a writer or a reader, but also the differences that exist between the place where the \'We are and the period in which we live. A person from the Middle Ages in Europe will not see the history of the same way as another in Africa in the 2000s, \"said Nafée Faîgou, president of the saffron.\r\nOther contradictions, such as hope and despair, corsp and spirit or nature and plastic, have been relieved.\r\nTwo major discussions also took place on Friday and Saturday. The first, held by Fété Kimpioobi, Managing Director of Sofifran, arrested the plural Francophonie in Ontario,\r\nThe second by Mrs. Faîgou, carried on belief in itself and in others.\r\nA storytelling for children with riddles took place on Sunday with Karim Sigéré, Dad tells, Fité Kimpioobi and Nyote. A reading-show was held on Sunday with Gaton Mabaya, Kalambayi Kalula, Aristotle Kavungu and Amadou Ba.\r\nIn addition, a publisher\'s fair was presented every day. The latter had the opportunity to show their books, to chat with visitors and to explain their vision of the world of writing.\r\n\"This living room was wonderful, we found our child\'s soul for a few days. The artists, writers, illustrators, publishers, booksellers, teachers and participants were fabulous, ”concludes Nafée Faîgou.', 'le-salon-du-livre-du-niagara-permet-de-retrouver-son-ame-denfant', '1712334403.jpeg', '2024-04-05 14:26:43', '2024-04-05 14:26:43'),
(28, 'CROIX-ROUGE CANADA', 'RED CROSS CANADA', 'CROIX-ROUGE CANADA', 'RED CROSS CANADA', 'croix-rouge-canada', '1713541458.jpeg', '2024-04-19 13:44:18', '2024-04-19 13:44:18'),
(29, 'CELEBRATION DE LA FETE DES MERES', 'CELEBRATION OF MOTHERS DAY', 'CELEBRATION DE LA FETE DES MERES', 'CELEBRATION OF MOTHERS DAY', 'celebration-de-la-fete-des-meres', '1713541503.jpeg', '2024-04-19 13:45:03', '2024-04-19 13:45:03'),
(30, 'Rapport final de projet Vice Versa / D52541 École élémentaire LaMarsh', 'Final report of project Vice Versa / D52541 École élémentaire LaMarsh', 'Dans le but de promouvoir le leadership des élèves, les élèves ont créé un projet à long terme sur le mieux-être général en lien avec la justice social. L\'école a reçu des experts dans le domaine de la santé mentale, de sensibilisation contre le racisme offert en français de The Get Real Movement inc. Cet atelier a donné la chance aux élèves d’augmenter leur capacité à identifier, désapprendre et combattre les préjugés raciaux et la discrimination au travers de la danse et des conversations qui ont été encourues par l’artiste.  De plus, les élèves ont eu la chance de parler des sujets comme l\'intimidation, la communauté LGBTQAI2+S et développer leurs connaissances sur divers sujets.\r\n\r\nCe projet a été créé en collaboration avec l’organisme SOFIFRAN, le conseil scolaire Viamonde et grâce à la subvention Vice Versa.', 'To promote student leadership, the students created a long-term project on general wellness and social justice. The school welcomed experts in the field of mental health, anti-racism awareness offered in French by The Get Real Movement inc. This workshop gave students the chance to increase their ability to identify, unlearn and combat racial prejudice and discrimination through dance and conversations that were encouraged by the artist.  In addition, students had the chance to talk about topics such as bullying, the LGBTQAI2+S community and develop their knowledge on various subjects.\r\n\r\n\r\n\r\nThis project was created in collaboration with the SOFIFRAN organization, the Viamonde school board and thanks to the Vice Versa grant.\r\n\r\nTranslated with DeepL.com (free version)', 'rapport-final-de-projet-vice-versa-d52541-ecole-elementaire-lamarsh', '1718106306.jpg', '2024-06-11 09:45:06', '2024-06-11 09:45:06'),
(31, 'Rapport final de projet Vice Versa / D52541 École élémentaire LaMarsh', 'Final report of project Vice Versa / D52541 École élémentaire LaMarsh', 'Dans le but de promouvoir le leadership des élèves, les élèves ont créé un projet à long terme sur le mieux-être général en lien avec la justice social. L\'école a reçu des experts dans le domaine de la santé mentale, de sensibilisation contre le racisme offert en français de The Get Real Movement inc. Cet atelier a donné la chance aux élèves d’augmenter leur capacité à identifier, désapprendre et combattre les préjugés raciaux et la discrimination au travers de la danse et des conversations qui ont été encourues par l’artiste.  De plus, les élèves ont eu la chance de parler des sujets comme l\'intimidation, la communauté LGBTQAI2+S et développer leurs connaissances sur divers sujets.\r\n\r\nCe projet a été créé en collaboration avec l’organisme SOFIFRAN, le conseil scolaire Viamonde et grâce à la subvention Vice Versa.', 'To promote student leadership, the students created a long-term project on general wellness and social justice. The school welcomed experts in the field of mental health, anti-racism awareness offered in French by The Get Real Movement inc. This workshop gave students the chance to increase their ability to identify, unlearn and combat racial prejudice and discrimination through dance and conversations that were encouraged by the artist.  In addition, students had the chance to talk about topics such as bullying, the LGBTQAI2+S community and develop their knowledge on various subjects.\r\n\r\n\r\n\r\nThis project was created in collaboration with the SOFIFRAN organization, the Viamonde school board and thanks to the Vice Versa grant.\r\n\r\nTranslated with DeepL.com (free version)', 'rapport-final-de-projet-vice-versa-d52541-ecole-elementaire-lamarsh', '1718106348.jpg', '2024-06-11 09:45:48', '2024-06-11 09:45:48'),
(32, 'Fête de la St Jean: Visite de  MPP/Députée provinciale de Mississauga Centre', 'St. John\'s Day: MPP/Mississauga Centre MPP visit', 'Dimanche 23 juin, les francophones de Welland ont célébré la fête de la St. Jean à l\'Auberge Richelieu. Photo : Mme Natalia Kusendova-Bashta, MPP/Députée provinciale de Mississauga Centre avec Maman Fété Ngira-Batware Kimpiobi, directrice générale de Sofifran.', 'On Sunday June 23, Welland\'s francophones celebrated St. John\'s Day at Auberge Richelieu. Photo: Mrs. Natalia Kusendova-Bashta, MPP/Mississauga Centre with Maman Fété Ngira-Batware Kimpiobi, Sofifran General Manager.', 'fete-de-la-st-jean-visite-de-mppdeputee-provinciale-de-mississauga-centre', '1719436915.jpg', '2024-06-26 19:21:56', '2024-06-26 19:21:56'),
(33, 'Sofifran Canada 2024', 'Sofifran Canada 2024', 'Sofifran Canada 2024', 'Sofifran Canada 2024', 'sofifran-canada-2024', '1720027828.jpg', '2024-07-03 15:30:28', '2024-07-03 15:30:28'),
(34, 'Sofifran Canada 2024', 'Sofifran Canada 2024', 'Sofifran Canada 2024', 'Sofifran Canada 2024', 'sofifran-canada-2024', '1720027916.jpg', '2024-07-03 15:31:56', '2024-07-03 15:31:56'),
(35, 'Sofifran célèbre la fête des Pères', 'Sofifran celebrates Father\'s Day', 'Ayant célébré avec succès la fête des Pères en 2023, Sofifran a choisi de réitérer l’expérience le 15 juin au parc Memorial à Welland. Une soixantaine de personnes provenant essentiellement de Niagara, Welland, St. Catharines et Thorold se sont retrouvées au parc pour honorer leurs pères.\r\n\r\nIl faisait très beau et chaud. Les enfants se sont amusés en jouant au soccer et, tout au long de la journée, ont profité d’un repas fourni par l’organisme et de la musique. Les jeunes filles ont partagé de tendres moments en dansant avec leurs papas.\r\n\r\n« Nous avions organisé des transports groupés par Uber pour permettre aux familles des alentours de participer au pique-nique. Six bénévoles, dont quatre envoyés par le Centre de santé communautaire Hamilton/Niagara, ont apporté leur aide pour veiller au bon déroulement de l’activité, de la distribution de la nourriture et des jus. Nous avons fait cuire du poulet, du maïs et des hamburgers sur le barbecue. Tout le monde a bien mangé, il ne restait plus rien », s’est exclamé Emmanuel Mompongo, coordinateur de projet.\r\n\r\nÀ un moment précis de la journée, 10 enfants âgés de 3 à 15 ans ont spontanément remercié leurs pères en leur dédiant des messages de reconnaissance. « Les enfants sont venus remercier leurs papas pour tout ce qu’ils font chaque jour. L’un d’eux a parlé des sacrifices que son père a fait pour lui permettre de faire des activités sportives et pour l’accompagner », ajoute M. Mompongo. Les pères étaient très émus d’entendre les enfants leur faire des éloges.\r\n\r\nPour mettre de l’ambiance en fin de journée, un DJ a joué de la musique internationale pour faire danser petits et grands. Les participants, y compris des nouveaux arrivants francophones, se sont bien amusés.\r\n\r\n« Nous sommes vraiment contents que tout se soit bien passé. Nous avons tendance à fêter les pères en toute discrétion, c’est pourquoi il était essentiel qu’ils se sentent reconnus dans un système où les hommes ont l’impression d’être marginalisés et de perdre leur rôle d’époux et de pères, conclut Fété Ngira-Batware Kimpiobi, directrice générale de Sofifran.\r\n\r\n« Nous espérons que les commanditaires pourront nous soutenir l’année prochaine pour offrir des petits cadeaux aux papas, tout comme nous avons l’habitude de le faire pour les mamans. Il faut qu’on continue de célébrer la fête des Pères, cela renforce les liens familiaux. »\r\n\r\nPhoto (Sofifran) : Ce papa était très ému de vivre ce moment avec son fils.', 'Having successfully celebrated Father\'s Day in 2023, Sofifran decided to repeat the experience on June 15 at Memorial Park in Welland. Around 60 people from Niagara, Welland, St. Catharines and Thorold gathered at the park to honor their fathers.\r\n\r\nThe weather was warm and sunny. The children enjoyed a game of soccer and, throughout the day, a meal provided by the organization and live music. The girls shared tender moments dancing with their dads.\r\n\r\n\"We had organized group transportation via Uber to enable families from the surrounding area to take part in the picnic. Six volunteers, including four sent by the Hamilton/Niagara Community Health Centre, helped to ensure the smooth running of the event, food and juice distribution. We cooked chicken, corn and hamburgers on the barbecue. Everyone ate well, and there was nothing left,\" exclaimed project coordinator Emmanuel Mompongo.\r\n\r\nAt one point during the day, 10 children aged from 3 to 15 spontaneously thanked their fathers by dedicating messages of gratitude to them. \"The children came to thank their dads for everything they do every day. One of them spoke of the sacrifices his father made to enable him to take part in sporting activities and to accompany him,\" adds Mr. Mompongo. The fathers were very moved to hear the children praise them.\r\n\r\nTo set the mood at the end of the day, a DJ played international music to keep young and old dancing. Participants, including French-speaking newcomers, had a great time.\r\n\r\n\"We\'re really pleased that everything went so well. We tend to celebrate fathers discreetly, so it was essential that they felt recognized in a system where men feel marginalized and lose their role as husbands and fathers,\" concludes Fété Ngira-Batware Kimpiobi, Sofifran\'s General Manager.\r\n\r\n\"We hope that sponsors will be able to support us next year to offer small gifts to dads, just as we used to do for moms. We must continue to celebrate Father\'s Day, as it strengthens family ties.\"\r\n\r\nPhoto (Sofifran): This father was very moved to share this moment with his son.', 'sofifran-celebre-la-fete-des-peres', '1720722855.jpeg', '2024-07-11 16:34:15', '2024-07-11 16:34:15'),
(36, 'Festival FestivÉbène 2025 – Une 18eme édition sous le signe de l’« Afrique Éternelle »', 'FestivÉbène 2025 Festival - 18th edition under the banner of “Eternal Africa', 'La 18eme édition du festival FestivÉbène a marqué un tournant dans la célébration de la diversité et de la richesse des cultures africaines. Placé sous le thème « Afrique Éternelle : Passé, Présent, Futur », l’événement a offert une immersion artistique et culturelle unique, où tradition et modernité se sont entrelacées avec élégance. Un lancement prestigieux avec une exposition sous la direction du commissaire Mélina Seymour, a transporté les visiteurs à travers un voyage visuel et sensoriel mettant en lumière l’histoire, l’évolution et l’avenir du continent africain. Grâce à son regard artistique aiguisé et son engagement envers la préservation du patrimoine afrodescendant, elle a su créer une expérience inoubliable, mêlant peinture, sculpture et installations contemporaines. L’événement a été sublimé par l’animation chaleureuse et humoristique de Justine Gogoua, qui a su captiver le public avec son énergie communicative et son sens du partage, rendant cette inauguration encore plus mémorable.\r\n\r\nLe lancement officiel du 8 février 2025 s’est déroulé en présence de nombreuses personnalités influentes, témoignant de l’importance et de la reconnaissance grandissante du festival FestivÉbène. Parmi les invités d’honneur et les dignitaires présents :\r\n\r\n- Prof. Nicholas Hauck, MLL\r\n- Prof. Linda Carreiro, MIWSFPA\r\n- Prof. Brad Clarke, Vice-Président Associé,Brock University\r\n- Mme Colleen Smith, Directrice du FirstOntario Performing Arts Centre\r\n- MP Vance Badawey,\r\n- M. Mat Siscoe, Maire de St. Catharines\r\n- M. Adam Moote, Conseiller du Vice-Maire de Welland\r\n- Mme Melinda Chartrand, représentante du Centre communautaire Le Griffon et du Conseil scolaire MonAvenir\r\n- M. Eric Keunne, représentant du Conseil scolaire Viamonde\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nLe festival a également été honoré par la prestation musicale de l’artiste Amadou Kiénou, qui a apporté une ambiance immersive et vibrante à cette ouverture.\r\n\r\nLe festival FestivÉbène ne pourrait exister sans le soutien essentiel de nos nombreux partenaires. Nous tenons à exprimer notre profonde gratitude à :\r\n\r\n- Bailleurs de fonds\r\nPatrimoine Canada\r\nConseil des arts de l’Ontario\r\n\r\n- Commanditaires\r\nLa Ville de St. Catharines\r\nLe Centre communautaire Le Griffon\r\nLe Conseil scolaire Viamonde\r\nLe Conseil scolaire MonAvenir\r\n\r\n- Partenaires communautaires\r\n\r\nNous remercions également nos partenaires communautaires, dont :\r\nLa Ville de Welland\r\nFirstOntario Performing Arts Centre\r\nABC Communautaire\r\nVia Casa\r\n\r\nSans oublier Pot pourri Show, la Maison de la culture francophone du Niagara engagés dans cette aventure culturelle\r\n\r\nNe manquez pas la soirée de clôture du 14 février à 18h ! \r\n\r\nNous vous donnons rendez-vous le 14 février à 18h pour une soirée de clôture exceptionnelle qui viendra célébrer la fin de cette magnifique exposition. Une occasion unique de revenir sur les moments forts du festival et de partager une dernière immersion artistique.\r\n\r\nRejoignez-nous aussi pour la soirée spectacle du 15 février ! \r\n\r\nLe festival FestivÉbène 2025 se poursuit avec une soirée spectacle inédite le 15 février, réunissant des talents tels que Klasik-O et Cloclo Clodel. Cet événement marquera la clôture d’une édition exceptionnelle où l’art et la culture africaine auront été mis à l’honneur comme jamais auparavant.\r\n\r\n- Suivez-nous sur nos réseaux sociaux pour ne rien manquer !\r\n- www.sofifran.org\r\n\r\n- Merci à toutes celles et ceux qui contribuent à faire rayonner le festival FestivÉbène !', 'The 18th edition of the FestivÉbène festival marked a turning point in the celebration of the diversity and richness of African cultures. Under the theme “Eternal Africa: Past, Present, Future”, the event offered a unique artistic and cultural immersion, where tradition and modernity were elegantly intertwined. A prestigious launch with an exhibition curated by Mélina Seymour, took visitors on a visual and sensory journey highlighting the history, evolution and future of the African continent. With her keen artistic eye and commitment to the preservation of Afro-descendant heritage, she created an unforgettable experience, blending painting, sculpture and contemporary installations. The event was enhanced by the warm and humorous animation of Justine Gogoua, who captivated the audience with her communicative energy and sense of sharing, making this inauguration even more memorable.\r\n\r\nThe official launch on February 8, 2025 was attended by many influential personalities, testifying to the growing importance and recognition of the FestivÉbène festival. Among the guests of honor and dignitaries present:\r\n\r\nTranslated with DeepL.com (free version)\r\n\r\n- Prof. Nicholas Hauck, MLL\r\n- Prof. Linda Carreiro, MIWSFPA\r\n- Prof. Brad Clarke, Associate Vice-President,Brock University\r\n- Ms. Colleen Smith, Director, FirstOntario Performing Arts Centre\r\n- MP Vance Badawey,\r\n- Mr. Mat Siscoe, Mayor of St. Catharines\r\n- Mr. Adam Moote, Advisor to the Vice-Mayor of Welland\r\n- Ms Melinda Chartrand, representative of Centre communautaire Le Griffon and Conseil scolaire MonAvenir\r\n- Mr. Eric Keunne, representing the Viamonde School Board\r\n\r\nThe festival was also honored by the musical performance of artist Amadou Kiénou, who brought an immersive and vibrant atmosphere to the opening.\r\n\r\nThe FestivÉbène festival could not exist without the essential support of our many partners. We would like to express our deepest gratitude to :\r\n\r\n- Funders\r\nCanadian Heritage\r\nOntario Arts Council\r\n\r\n- Sponsors\r\nCity of St. Catharines\r\nLe Griffon Community Centre\r\nViamonde School Board\r\nMonAvenir School Board\r\n\r\n- Community partners\r\n\r\nWe would also like to thank our community partners, including\r\nCity of Welland\r\nFirstOntario Performing Arts Centre\r\nABC Communautaire\r\nVia Casa\r\n\r\nAnd of course, Pot pourri Show and Maison de la culture francophone du Niagara, who are committed to this cultural adventure.\r\n\r\nDon\'t miss the closing party on February 14 at 6pm! \r\n\r\nWe look forward to seeing you on February 14 at 6pm for an exceptional closing evening to celebrate the end of this magnificent exhibition. A unique opportunity to look back on the highlights of the festival and share a final artistic immersion.\r\n\r\nJoin us for the evening show on February 15! \r\n\r\nThe FestivÉbène 2025 festival continues with a unique evening show on February 15, featuring talents such as Klasik-O and Cloclo Clodel. This event will mark the close of an exceptional edition in which African art and culture will have been honored as never before.\r\n\r\n- Follow us on our social networks to make sure you don\'t miss a thing!\r\n- www.sofifran.org\r\n\r\n- Thank you to all those who contribute to making the FestivÉbène festival shine!', 'festival-festivebene-2025-une-18eme-edition-sous-le-signe-de-l-afrique-eternelle', '1739535477.jpeg', '2025-02-14 12:29:43', '2025-02-14 12:29:43');
INSERT INTO `blogs` (`id`, `title_fr`, `title_en`, `description_fr`, `description_en`, `slug`, `image`, `created_at`, `updated_at`) VALUES
(37, 'Sofifran initie les nouveaux arrivants au vivre-ensemble canadien', 'Sofifran introduces newcomers to Canadian living together', 'L’organisme Sofifran a organisé, comme chaque année, un événement festif pour renforcer les liens entre les communautés francophones et les nouveaux arrivants du Niagara. Au programme : cadeaux pour les enfants, animations et moments de partage qui illustrent l’esprit de solidarité et d’intégration propre à la région.\r\n\r\nOlaïsha Francis, IJL – Réseau.Presse – Le Régional\r\n\r\nComme chaque année, Sofifran a réitéré ses traditions de fin d’année en organisant un événement pour rassembler les familles francophones et les nouveaux arrivants de la région du Niagara. L’occasion de célébrer ensemble, mais aussi de distribuer des cartes-cadeaux aux enfants immigrants, un geste apprécié par 137 jeunes cette année.\r\n\r\n« Le réveillon est un événement clé, ouvert à toutes les communautés francophones. Nous en profitons pour offrir des cadeaux aux enfants, ce qui est toujours un grand plaisir », explique Fété Ngira-Batware Kimpiobi, directrice générale de Sofifran.\r\n\r\nLes nouveaux arrivants ont également partagé leurs impressions sur cette soirée qui a eu lieu dans la salle paroissiale du Sacré-Cœur à Welland.\r\n\r\nAka Effoli, récemment arrivée de Côte d’Ivoire, a salué l’opportunité d’échanger avec d’autres. « Ici, nous apprenons à nous ouvrir aux différences et à nous adapter. Dans mon pays, on reste souvent centré sur notre propre culture, mais ici, tout est plus ouvert », confie-t-elle. Pour Roseline Mbaca, venue du Cameroun, l’événement a été une expérience « enrichissante » qui lui a permis de découvrir de nouvelles manières de célébrer. « D’où je viens, tout le monde se connaît et les fêtes se terminent plus tard. Mais ici, c’est une belle occasion de créer des liens et d’échanger. »\r\n\r\nL’esprit des Fêtes, c’est aussi une question de perception, qu’il s’agisse de moments partagés avec ses proches, de décorations illuminant les maisons ou de repas conviviaux. Pour certains, cette magie se ressent dans la musique ou la lecture, mais elle prend, avant tout, une forme personnelle et s’adapte aux traditions de chacun.\r\n\r\nAu cours de la soirée, l’artiste locale Suzanne Leclerc a animé un programme destiné aux enfants et aux parents, avec des contes, des devinettes, des chansons et des danses. Son interaction avec les enfants a marqué les esprits. Cet événement a également permis de recueillir les avis des participants sur les activités proposées, un moyen de mieux répondre aux attentes de la communauté.\r\n\r\nLes festivités se sont poursuivies avec de la musique et un repas préparé par une membre de la communauté. Tout au long de la soirée, les participants ont dansé, et nombreux étaient ceux qui se sont joints à l’événement, y compris des membres de la communauté peu présents lors des autres activités.\r\n\r\n« Bien que rassembler la communauté puisse parfois être un défi, ce type d’événement montre que notre programme est bien adapté aux besoins de notre clientèle. C’est un réel plaisir de contribuer à cette initiative qui soutient le vivre-ensemble, une priorité pour le gouvernement canadien », conclut Fété Ngira-Batware Kimpiobi.\r\n\r\nDans un pays comme le Canada, où l’autonomie est souvent la norme, des événements réunissant des personnes d’origines culturelles diverses sont essentiels pour encourager l’inclusion et renforcer les liens sociaux.\r\n\r\nPhoto : Le réveillon de Sofifran est toujours une activité rassembleuse. (Crédit : Sofifran)', 'As it does every year, the Sofifran organization organized a festive event to strengthen ties between Francophone communities and newcomers to Niagara. On the program: gifts for children, activities and moments of sharing that illustrate the spirit of solidarity and integration specific to the region.\r\n\r\nOlaïsha Francis, IJL – Réseau.Presse – Le Régional\r\n\r\nAs it does every year, Sofifran reiterated its end-of-year traditions by organizing an event to bring together Francophone families and newcomers to the Niagara region. It was an opportunity to celebrate together, but also to distribute gift cards to immigrant children, a gesture appreciated by 137 young people this year.\r\n\r\n“New Year’s Eve is a key event, open to all Francophone communities. We take the opportunity to offer gifts to children, which is always a great pleasure,” explains Fété Ngira-Batware Kimpiobi, Executive Director of Sofifran.\r\n\r\nNewcomers also shared their impressions of the evening, which took place in the Sacré-Cœur parish hall in Welland.\r\n\r\nAka Effoli, who recently arrived from Côte d’Ivoire, welcomed the opportunity to interact with others. “Here, we learn to be open to differences and adapt. In my country, we often stay focused on our own culture, but here, everything is more open,” she said. For Roseline Mbaca, who came from Cameroon, the event was an “enriching” experience that allowed her to discover new ways of celebrating. “Where I come from, everyone knows each other and the holidays end later. But here, it’s a great opportunity to create connections and exchange.”\r\n\r\nThe holiday spirit is also a question of perception, whether it’s moments shared with loved ones, decorations lighting up homes or convivial meals. For some, this magic is felt in music or reading, but it is, above all, personal and adapted to each person’s traditions.\r\n\r\nDuring the evening, local artist Suzanne Leclerc hosted a program for children and parents, with stories, riddles, songs and dances. Her interaction with the children left a lasting impression. This event also provided an opportunity to gather feedback from participants on the proposed activities, a way to better meet the community’s expectations.\r\n\r\nThe festivities continued with music and a meal prepared by a member of the community. Throughout the evening, participants danced, and many joined in the event, including members of the community who were rarely present during other activities.\r\n\r\n“While bringing the community together can sometimes be a challenge, this type of event shows that our program is well adapted to the needs of our clientele.” It is a real pleasure to contribute to this initiative that supports living together, a priority for the Canadian government,” concludes Fété Ngira-Batware Kimpiobi.\r\n\r\nIn a country like Canada, where autonomy is often the norm, events that bring together people from diverse cultural backgrounds are essential to encourage inclusion and strengthen social ties.\r\n\r\nPhoto: Sofifran’s New Year’s Eve is always a unifying activity. (Credit: Sofifran)', 'sofifran-initie-les-nouveaux-arrivants-au-vivre-ensemble-canadien', '1740058574.jpg', '2025-02-20 13:36:15', '2025-02-20 13:36:15'),
