INSERT INTO `categorie_activities` (`id`, `image`, `titre_fr`, `titre_en`, `description_fr`, `description_en`, `slug`, `created_at`, `updated_at`) VALUES
(1, 'social.jpg', 'Social', 'Social', 'Le volet social de SOFIFRAN soutient les personnes immigrantes francophones du Niagara pour favoriser leur bien-être et leur intégration.  Il propose des activités et services inclusifs afin de briser l’isolement et renforcer les liens communautaires.  Ce volet vise à bâtir des réseaux solides et accessibles à tous.  Il s’inscrit dans la mission globale de SOFIFRAN en contribuant à une société plus équitable et solidaire.', 'SOFIFRAN\'s social component supports Francophone immigrants in Niagara to promote their well-being and integration.  It offers inclusive activities and services to break isolation and strengthen community ties.  This component aims to build solid networks that are accessible to all.  It is part of SOFIFRAN\'s overall mission to contribute to a more equitable and supportive society.', 'social', '2025-06-25 16:12:42', '0000-00-00 00:00:00'),
(2, 'economique.jpg', 'Économique', 'Economic', 'Le volet économique de SOFIFRAN soutient l’intégration socio-économique des personnes immigrantes en favorisant leur autonomie financière.  Il propose des ateliers et formations pratiques pour développer les compétences entrepreneuriales.  Une attention particulière est portée aux femmes immigrantes et aux communautés noires du Niagara.  Des projets ciblés encouragent la création d’entreprises, notamment dans le secteur des services de garde en milieu familial.', 'SOFIFRAN\'s economic component supports the socio-economic integration of immigrants by promoting their financial independence.  It offers workshops and practical training to develop entrepreneurial skills.  Special attention is paid to immigrant women and Niagara\'s Black communities.  Targeted projects encourage business start-ups, particularly in the family daycare sector.', 'economique', '2025-06-25 16:42:36', '0000-00-00 00:00:00'),
(3, 'educatif.jpg', 'Éducatif', 'Educative', 'Le volet éducatif de SOFIFRAN accompagne les communautés immigrantes dans leur intégration par des activités pratiques et enrichissantes.  Des ateliers abordent des thèmes essentiels comme la gestion du budget, l’alimentation saine, le code de la famille et l’intégration communautaire.  Le programme encourage aussi le bénévolat et les activités sportives pour favoriser l’engagement social.  Ces initiatives renforcent les compétences des participants et facilitent leur adaptation à la société d’accueil.', 'SOFIFRAN\'s educational component supports immigrant communities in their integration through practical, enriching activities.  Workshops cover essential topics such as budget management, healthy eating, family codes and community integration.  The program also encourages volunteering and sports activities to foster social involvement.  These initiatives strengthen participants\' skills and facilitate their adaptation to the host society.', 'educatif', '2025-06-25 16:55:42', '0000-00-00 00:00:00'),
(4, 'culturel.jpg', 'Culturel', 'Cultural', 'Le volet culturel de SOFIFRAN célèbre la diversité des communautés immigrantes à travers des événements inclusifs et rassembleurs.  Il valorise les traditions, la musique, la gastronomie et la littérature francophone par le biais de festivals, d’ateliers et du Salon du livre SAFRAN.  Ces activités renforcent les liens interculturels et permettent aux communautés de préserver et partager leur héritage.  Parmi les actions phares : Festiv\'Ébène, le Festival Niagara Folk Arts, la Journée canadienne du multiculturalisme et la Fête du Canada.', 'SOFIFRAN\'s cultural program celebrates the diversity of immigrant communities through inclusive and unifying events.  It promotes Francophone traditions, music, gastronomy and literature through festivals, workshops and the SAFRAN Book Fair.  These activities strengthen intercultural ties and enable communities to preserve and share their heritage.  Highlights include Festiv\'Ébène, the Niagara Folk Arts Festival, Canadian Multiculturalism Day and Canada Day.  Translated with DeepL.com (free version)', 'culturel', '2025-06-25 16:18:43', '0000-00-00 00:00:00');
