INSERT INTO `mandats` (`id`, `titre_en`, `titre_fr`, `contenu_en`, `contenu_fr`, `created_at`, `updated_at`) VALUES
(1, 'Mandates', 'Mandats', '<ul>\r\n              <li>Provide support services to at-risk black youth;</li>\r\n              <li>To develop activities and awareness programs for prevention aimed at at-risk black youth and the black community;</li>\r\n              <li>Creatively identify and seek potential financial support at the municipal, provincial and federal levels (as well as foundations) to develop and sustain the program ;</li>\r\n              <li>Promote self-expression through music, arts, sports; </li>\r\n              <li>Pair youth with mentors from the Black community (positive role models); </li>\r\n              <li>Strengthen the mental well-being, resilience to addiction and community leadership capacity of Black youth; </li>\r\n              <li>Develop and provide resources to support at-risk Black youth and their mentors in the educational system; </li>\r\n              <li>Provide a space to share their stories so that they can be transformed and become an inspiration to others;</li>\r\n              <li>Initiate a dialogue on racism, anti-black racism in particular and the oppression that affects all public institutions, including the criminal justice system.</li>\r\n          </ul>', '<ul>\r\n              <li>Donner des services d’accompagnement aux jeunes noirs à risque ;</li>\r\n              <li>Développer des activités, et programmes de sensibilisation pour la prévention, destinés aux jeunes noirs à risque et à la communauté noire</li>\r\n              <li>Identifier de manière créative et rechercher un soutien financier potentiel aux niveaux municipal, provincial et fédéral (ainsi que des fondations) afin de développer et soutenir le programme.</li>\r\n              <li>Promouvoir l’expression de soi à travers la musique, les arts, les sports ;</li>\r\n              <li>Jumeler les jeunes avec des mentors, issus de la communauté noire (modèles identitaires positifs) ;</li>\r\n              <li>Renforcer le bien-être mental, la résilience à la dépendance et la capacité d’encadrement communautaire des jeunes noirs;</li>\r\n              <li>Développer et fournir des ressources pour soutenir les jeunes noirs à risque et ceux qui les encadrent dans le système éducatif ;</li>\r\n              <li>Fournir un espace de partage de leurs histoires afin qu’ils se transforment et deviennent une source d’inspiration pour les autres.</li>\r\n              <li>Entamer un dialogue sur le racisme, le racisme anti-noir en particulier et l\'oppression qui touche toutes les institutions publiques, y compris le système pénal.</li>\r\n          </ul>', '2021-01-31 19:59:12', '0000-00-00 00:00:00');
