INSERT INTO `missions` (`id`, `titre_en`, `titre_fr`, `contenu_en`, `contenu_fr`, `created_at`, `updated_at`) VALUES
(1, 'Mission', 'Mission', 'Youth Anchorage Point is a bilingual organization that promotes equality and leadership for at-risk Black youth in Ontario by enabling them to find their place in Canadian society. Through a stronger identity reconstruction, to prevent at-risk black youth from slipping or returning to crime through the prevention and early intervention and support of families in the criminal justice and psychosocial system.', 'Point Ancrage Jeunesse est un organisme bilingue qui promeut l’égalité et le leadership aux jeunes noirs à risque de l’Ontario en leur permettant de se retrouver dans la société canadienne. À travers une reconstruction identitaire plus forte, empêcher les jeunes noirs à risque de basculer ou de retomber dans la criminalité par la prévention et l’intervention précoce.', '2021-01-17 15:36:51', '0000-00-00 00:00:00');
