INSERT INTO `popups` (`id`, `titre`, `image`, `contenu`, `start`, `end`, `created_at`, `updated_at`) VALUES
(1, 'La nouvelle infolettre de SOFIFRAN', '1785942603_6a73524b7c942.jpeg', 'La nouvelle infolettre de SOFIFRAN est maintenant disponible !\r\nDécouvrez les nouvelles de la communauté, les activités récentes, les projets en cours et les événements à venir.\r\nConsultez l’infolettre dès maintenant.', '2026-03-26', '2026-08-25', '2026-08-05 15:10:03', '2026-08-05 15:10:03');
INSERT INTO `projets` (`id`, `titre_fr`, `titre_en`, `objectif`, `image`, `description_fr`, `description_en`, `slug`, `ended`, `created_at`, `updated_at`) VALUES
(1, 'Projet de revitalisation pour les communautés noires du Niagara', 'Niagara Black Community Revitalization Project', NULL, '1652649465.jpg', '<div>Avec l’octroi de ce programme, Sofifran pourra rénover ses espaces actuels de bureaux afin d’offrir un milieu convivial et adéquat pour la tenue de plusieurs activités et services qui relèvent des quatre secteurs de son mandat tout en respectant les mesures de distanciation sociale recommandée.&nbsp; Dans cette optique, Sofifran compte accroitre l’espace avec une salle jouxtant ses bureaux pour des rencontres sociales, culturelles, des ateliers éducatifs, des activités intergénérationnelles, l’artisanat, le club de lecture pour les plus petits, etc.&nbsp; Afin d’atteindre cet objectif, des travaux de rénovation seront entrepris pour moderniser son espace communautaire et acquérir du mobilier de bureau et des équipements informatique et ménager.</div><div><br></div><div>Ce projet est financé par : Emploi et Développement social Canada – Programme d’appui aux communautés noires du Canada (ACNC)</div>', '<p>With the granting of this program, Sofifran will be able to renovate its current office spaces in order to provide a friendly and adequate environment for the holding of several activities and services that fall under the four sectors of its mandate while respecting the recommended social distancing measures. . With this in mind, Sofifran intends to increase the space with a room adjoining its offices for social and cultural meetings, educational workshops, intergenerational activities, crafts, the book club for the little ones, etc. In order to achieve this objective, renovation work will be undertaken to modernize its community space and acquire office furniture and computer and household equipment.</p><p><br></p><p>This project is funded by: Employment and Social Development Canada – Support Program for Black Communities in Canada (ACNC)</p>', 'projet-de-revitalisation-pour-les-communautes-noires-du-niagara', 'yes', '2022-05-23 11:15:26', '2022-05-23 09:15:26'),
(2, 'FONDS POUR LES COMMUNAUTÉS RÉSILIENTES', 'RESILIENT COMMUNITIES FUND', NULL, '1652539112.jpg', '<p>Grâce au financement de la fondation Trillium de l’Ontario (FTO) pour les communautés résilientes, notre organisme se rétablira et se reconstruira par suite des impacts de la COVID-19 en achetant de l’équipement numérique afin d’offrir du contenu en ligne et embaucher des consultants responsables pour élaborer un plan stratégique, renforcer notre capacité de travailler en ligne et offrir de la formation au personnel et aux bénévoles.<br></p>', '<p>With funding from the Ontario Trillium Foundation (OTF) for Resilient Communities, our organization will recover and rebuild from the impacts of COVID-19 by purchasing digital equipment to deliver content online and hire responsible consultants to develop a strategic plan, build our capacity to work online, and provide training to staff and volunteers.<br></p>', 'fonds-pour-les-communautes-resilientes', 'yes', '2022-05-23 11:15:19', '2022-05-23 09:15:19'),
(3, 'PLUS EN SECURITÉ ET PLUS FORTES', 'SAFER AND STRONGER', NULL, '1652649891.jpg', '<p>À travers ce projet, Sofifran veut offrir du soutien, de l’accompagnement et de la représentation aux personnes se trouvant impliquée dans les démarches en lien avec une situation de violence fondée sur le genre. C’est notamment le cas pour : la violence conjugale, le harcèlement psychologique au travail et les agressions sexuelles. Les activités du projet permettront d’identifier et d’évaluer les besoins des victimes, d’offrir une écoute active, du soutien moral, de l’information, ainsi que d’accompagner et de référer les victimes aux services de soutien, le cas échéant, de les aider à naviguer dans les systèmes sociaux et judiciaires.</p><p><br></p><p>Ce projet est financé par la : <b>Fondation canadienne des femmes</b></p>', '<p>Through this project, Sofifran wants to offer support, accompaniment and representation to people who find themselves involved in procedures related to a situation of gender-based violence. This is particularly the case for: domestic violence, psychological harassment at work and sexual assault. The project\'s activities will make it possible to identify and assess the needs of victims, offer active listening, moral support, information, as well as accompany and refer victims to support services, if necessary. where appropriate, to help them navigate the social and legal systems.</p><p><br></p><p>This project is funded by: <b>Canadian Women\'s Foundation</b></p>', 'plus-en-securite-et-plus-fortes', 'yes', '2022-05-23 11:15:14', '2022-05-23 09:15:14'),
(4, 'Collier de sagesse, une perle à la fois', 'Necklace of wisdom, one bead at a time', NULL, '1652650074.jpg', '<p>En ces temps particuliers où la société lutte contre la pandémie de la COVID-19, ce projet arrive bien à propos. Son objectif vise à initier les ainés à une série de nouvelles activités qui les aident à maintenir une vie active et à rester connectés entre eux. Cela passe par l’apprentissage des nouvelles applications de communications qui répondent à leurs besoins spécifiques actuels et qui sont adaptées aux normes sociales de sécurité. À travers ce projet, les ainés sont régulièrement informés sur les mises à jour relatives à la pandémie ou sur tout autre information pertinente. Des bénévoles parlant créole, lingala, swahili et arabe participent aux discussions sur divers sujets de connaissances culturelles, artistiques et artisanales ainsi que de leurs us et coutumes. Le but ultime est de donner la parole aux ainés afin qu’ils partagent leurs expériences et leurs connaissances.</p><p><br></p><p>Ce projet est financé par : <b>Programme Nouveaux Horizons pour les ainés (PNHA)</b></p>', '<p>In these particular times when society is fighting the COVID-19 pandemic, this project is timely. Its goal is to introduce seniors to a series of new activities that help them maintain an active life and stay connected to each other. This involves learning about new communications applications that meet their current specific needs and that are adapted to social security standards. Through this project, seniors are regularly informed about pandemic updates or any other relevant information. Volunteers speaking Creole, Lingala, Swahili and Arabic participate in discussions on various topics of cultural, artistic and craft knowledge as well as their habits and customs. The ultimate goal is to give seniors a voice to share their experiences and knowledge.</p><p><br></p><p>This project is funded by: <b>New Horizons for Seniors Program (NHSP)</b></p>', 'collier-de-sagesse-une-perle-a-la-fois', 'yes', '2022-05-23 11:15:06', '2022-05-23 09:15:06'),
(5, 'Sofifran pique la curiosité avec son programme d’entrepreneuriat au féminin', 'Sofifran arouses curiosity with its female entrepreneurship program', NULL, '1652651398.jpg', '<p>« L’événement d’aujourd’hui est extrêmement important parce que nous célébrons la Journée de la femme et en plus nous avons voulu conclure avec le dernier atelier du projet EntrePrend. » Ainsi parlait Fété Kimpiobi, directrice générale de Sofifran, dans la salle communautaire de l’hôtel de ville de Welland devant une assistance composée de quelques dizaines de femmes de toutes origines.</p><p>En effet, en ce dimanche 8 mars, l’organisme parachevait son programme EntrePrend qui, débuté en octobre dernier, avait pour objectif de renforcer les compétences entrepreneuriales des femmes désireuses de se lancer en affaires. Par le biais d’une série d’ateliers dispensés par deux intervenantes de la Société économique de l’Ontario (SÉO) – Siham Chakrouni, conseillère en employabilité et en entrepreneuriat, et Adra Berezintsev, gestionnaire du programme Mentorat aux nouveaux arrivants –, chacune des participantes s’est familiarisée aux principes généraux de la gestion d’entreprise dans le but de créer sa propre compagnie.</p><p>En guise d’atelier final, les participantes devaient présenter leur projet d’entreprise à un jury composé de Mmes Chakrouni et Berezintsev et Yvette Plentai, agente de développement économique à la SÉO. La formule adoptée était similaire à ce qui peut être vu dans l’émission Dans l’oeil du dragon (Dragon’s Den) à Radio-Canada, les quatre participantes présentant leur produit ou service pour ensuite répondre à quelques questions des juges.</p><p>Après s’être ainsi livrées, devant l’assistance et les trois intervenantes de la SÉO, à cet exercice de communication, les participantes n’avaient plus qu’à attendre les résultats.</p><p>Ceux-ci se sont déclinés comme suit. La 1re place est allée à Junise Dorvil pour son entreprise Junica Bio-beauté Fascinante, spécialisée dans la coiffure et les produits de beauté naturels. La 2e place est revenue, ex aequo, à Sherlyne Jean Charles pour son service de garde bilingue Home Away From Home et à Tanya Dorvil pour son service de traiteur Dorvil’s Kitchen. La 3e place a été occupée par Kettia Zéphir et son Ketou Gala Store, qui sera consacré à la vente de produits de beauté et de perruques pour femme.</p><p>Ce classement était cependant symbolique et chacune des participantes a reçu une bourse de 150 $.</p><p>La balle est désormais dans le camps de ces femmes pour qu’elles mènent à bien leur projet entrepreneurial.</p>', '<p>“Today’s event is extremely important because we are celebrating Women’s Day and in addition we wanted to conclude with the last workshop of the EntrePrend project. So spoke Fété Kimpiobi, CEO of Sofifran, in the community hall of Welland City Hall in front of an audience made up of a few dozen women of all origins.</p><p>Indeed, on this Sunday, March 8, the organization completed its EntrePrend program which, started last October, aimed to strengthen the entrepreneurial skills of women wishing to start a business. Through a series of workshops given by two workers from the Société économique de l\'Ontario (SÉO) – Siham Chakrouni, employability and entrepreneurship advisor, and Adra Berezintsev, manager of the Mentoring program for newcomers – each of the participants became familiar with the general principles of business management in order to create her own company.</p><p>As a final workshop, the participants had to present their business project to a jury made up of Ms. Chakrouni and Berezintsev and Yvette Plentai, economic development officer at the SÉO. The formula adopted was similar to what can be seen in the program Dans l\'oeil du dragon (Dragon\'s Den) on Radio-Canada, the four participants presenting their product or service and then answering a few questions from the judges.</p><p>After having engaged in this communication exercise, in front of the audience and the three SÉO workers, the participants only had to wait for the results.</p><p>These were broken down as follows. 1st place went to Junise Dorvil for her company Junica Bio-beauté Fascinante, specializing in hairdressing and natural beauty products. Second place went, tied, to Sherlyne Jean Charles for her bilingual childcare service Home Away From Home and to Tanya Dorvil for her catering service Dorvil’s Kitchen. Third place was taken by Kettia Zéphir and her Ketou Gala Store, which will be dedicated to the sale of beauty products and wigs for women.</p><p>However, this ranking was symbolic and each of the participants received a $150 scholarship.</p><p>The ball is now in the court of these women so that they carry out their entrepreneurial project.</p>', 'sofifran-pique-la-curiosite-avec-son-programme-dentrepreneuriat-au-feminin', 'yes', '2022-05-23 11:15:01', '2022-05-23 09:15:01'),
(6, 'Sofifran offre un soutient alimentaire aux familles dans le besoin', 'Sofifran offers food support to families in need', NULL, '1652651854.jpg', '<p>En ces temps difficiles où même les organismes sans but lucratif sont souvent contraints de sabrer dans leurs activités, la Croix-Rouge a mis en place une aide d’urgence qui leur est destinée. La raison d’être de ce programme est de faire en sorte que les Canadiens qui, pour toutes sortes de raisons, dépendent des interventions de ces organismes ne soient pas pénalisés davantage par les aléas imposés par la COVID-19.</p><p>À la fin juillet, l’organisme Sofifran a reçu des fonds de la Croix-Rouge pour offrir une aide alimentaire à des familles en situation de précarité et issues des communautés noires et arabes francophones de la région du Niagara.</p><p>« On avait commencé, déjà, à aider des familles de façon informelle », relate la directrice générale Fété Kimpiobi. En effet, la Fondation canadienne des femmes et l’Ontario Council of Agencies Serving Immigrants avaient, au cours des derniers mois, donné un coup de pouce financier à Sofifran pour ses efforts à ce chapitre. « Avec le financement de la Croix-Rouge, ça permet d’organiser à grande échelle une campagne de nourriture santé qui s’adresse aux plus vulnérables », poursuit Mme Kimpiobi.</p><p>L’équipe de Sofifran prévoyait au départ aider 50 familles mais, considérant les besoins dans la région, ce sera sans doute plus. L’organisme privilégie les familles nombreuses mais n’écarte pas pour autant les personnes seules, handicapées, etc., en gros tous ceux qui ont des difficultés socioéconomiques que la pandémie n’a fait qu’amplifier.</p><p>Ce sont, en fonction des circonstances, des repas préparés ou des provisions qui sont remis à ceux qui sont admissibles à cette aide et Sofifran se fixe chaque fois pour objectif d’offrir des aliments sains. La nourriture peut également être livrée au domicile de ceux qui ne peuvent se déplacer.</p><p>« Tout ce qui relève de la préparation, comme l’emballage et l’identification par famille, se fait sous la supervision de Sofifran qui a fait appel à un sous-traitant de la communauté », explique Fété Kimpiobi. Plusieurs bénévoles issus de partout dans la péninsule du Niagara se sont mis de la partie pour mener à bien ce programme qui se poursuivra jusqu’à la fin-novembre.</p><p>S’il y a un organisme qui connaît bien la diversité culturelle francophone du Niagara, c’est bien Sofifran. Soutenir ses initiatives qui se basent sur son réseau de contacts au sein de la population relevait donc du bon sens pour la Croix-Rouge.</p>', '<p>In these difficult times when even non-profit organizations are often forced to cut back on their activities, the Red Cross has set up emergency aid for them. The purpose of this program is to ensure that Canadians who, for all kinds of reasons, depend on the interventions of these organizations are not further penalized by the hazards imposed by COVID-19.</p><p>At the end of July, the Sofifran organization received funds from the Red Cross to provide food aid to families in precarious situations and from black and Francophone Arab communities in the Niagara region.</p><p>“We had already started to help families informally,” says general manager Fété Kimpiobi. Indeed, the Canadian Women\'s Foundation and the Ontario Council of Agencies Serving Immigrants had, in recent months, given a financial boost to Sofifran for its efforts in this regard. “With funding from the Red Cross, it makes it possible to organize a large-scale healthy food campaign aimed at the most vulnerable,” continues Ms. Kimpiobi.</p><p>The Sofifran team initially planned to help 50 families but, considering the needs in the region, it will undoubtedly be more. The organization favors large families but does not exclude single people, disabled people, etc., basically all those who have socio-economic difficulties that the pandemic has only amplified.</p><p>Depending on the circumstances, prepared meals or provisions are given to those who are eligible for this aid and Sofifran sets itself the goal each time of offering healthy food. Food can also be delivered to the homes of those who cannot travel.</p><p>“Everything related to preparation, such as packaging and identification by family, is done under the supervision of Sofifran, who has called on a subcontractor from the community,” explains Fété Kimpiobi. Several volunteers from all over the Niagara Peninsula have joined in to carry out this program, which will continue until the end of November.</p><p>If there is one organization that knows the Francophone cultural diversity of Niagara well, it is Sofifran. Supporting its initiatives based on its network of contacts within the population was therefore common sense for the Red Cross.</p>', 'sofifran-offre-un-soutient-alimentaire-aux-familles-dans-le-besoin', 'yes', '2022-05-23 11:14:52', '2022-05-23 09:14:52'),
(7, 'Formation pour les Femmes en Entrepreunariat', 'Training for Women in Entrepreneurship', NULL, '1652652073.jpg', '<p>Le mercredi 2 octobre, Sofifran accueillait, dans les bureaux de l’ABC Communautaire, les participantes au programme EntrePrend. Il s’agissait de la première session – et donc du lancement officiel – de cette nouvelle initiative de l’organisme qui vise à renforcer les compétences entrepreneuriales des femmes désireuses de se lancer en affaires. Financée par l’Assemblée de la francophonie de l’Ontario dans le cadre du programme Effet multiplicateur, cette série d’ateliers est animée par des intervenantes de la Société économique de l’Ontario (SEO).</p><p>Les participantes ont d’ailleurs pu rencontrer Siham Chakrouni, conseillère en employabilité et en entrepreneuriat, et Adra Berezintsev, gestionnaire du programme Mentorat aux nouveaux arrivants. Les deux employées de la SEO ont passé près de deux heures à dispenser le premier volet d’une formation qui s’échelonnera en tout sur six sessions jusqu’au début du printemps. La formation est conçue pour passer graduellement du général au particulier et sera tant soit peu personnalisée en fonction des participantes.</p><p>Celles-ci ont d’ailleurs été invitées, dès la première séance, à partager, en quelques mots, leurs idées et projets d’entreprise. Alors que certaines ont déjà une expérience en la matière et veulent faire grandir leurs affaires ou se relancer, d’autres sont des novices et désirent tenter cette expérience pour simplement gagner en autonomie financière. Dans les deux cas, Mmes Chakrouni et Berezintsev avaient conseils et recommandations à dispenser.</p><p>La première session a servi à brosser un portrait général de ce que comporte la mise sur pied et l’administration d’une entreprise. Analyse de la pertinence d’une idée d’entreprise, compréhension des coûts, connaissance du marché, plan d’affaires, vente et marketing, enregistrement, permis, licences, règlementation, etc. : tout y a passé. Après ce premier jet, les participantes se pencheront progressivement sur les détails au cours des prochains mois.</p><p>L’ABC Communautaire, qui fournit ses locaux pour la bonne marche de ce projet, a profité des circonstances pour promouvoir deux de ses formations susceptibles d’être utiles aux participantes, l’une touchant aux applications informatiques en administration et l’autre plus précisément Microsoft Excel. Les apprenties entrepreneures auront en effet fort à faire car, au-delà du rêve, tout projet d’affaires en bonne et due forme requiert une grande charge de travail et un éventail de connaissances spécialisées.</p><p><br></p><p><b>PHOTO </b>: Les sessions ont lieu dans les bureaux de l’ABC Communautaire.</p>', '<p>On Wednesday, October 2, Sofifran welcomed the participants in the EntrePrend program to the ABC Communautaire offices. This was the first session – and therefore the official launch – of this new initiative of the organization which aims to strengthen the entrepreneurial skills of women wishing to start a business. Funded by the Assemblée de la francophonie de l’Ontario as part of the Multiplier Effect program, this series of workshops is led by speakers from the Société économique de l’Ontario (SEO).</p><p>The participants were also able to meet Siham Chakrouni, employability and entrepreneurship counsellor, and Adra Berezintsev, manager of the Mentoring program for newcomers. The two SEO employees spent nearly two hours providing the first part of a training course that will span a total of six sessions until early spring. The training is designed to move gradually from the general to the specific and will be somewhat personalized according to the participants.</p><p>These were also invited, from the first session, to share, in a few words, their ideas and business projects. While some already have experience in this area and want to grow their business or relaunch, others are novices and want to try this experience simply to gain financial autonomy. In both cases, Ms. Chakrouni and Berezintsev had advice and recommendations to offer.</p><p>The first session served to paint a general picture of what is involved in setting up and running a business. Analysis of the relevance of a business idea, understanding of costs, knowledge of the market, business plan, sales and marketing, registration, permits, licenses, regulations, etc. : everything happened. After this first draft, the participants will gradually work on the details over the next few months.</p><p>The ABC Communautaire, which provides its premises for the smooth running of this project, took advantage of the circumstances to promote two of its training courses likely to be useful to the participants, one relating to computer applications in administration and the other more specifically Microsoft Excel. Apprentice entrepreneurs will indeed have a lot to do because, beyond the dream, any business project in due form requires a heavy workload and a range of specialized knowledge.</p><p><br></p><p><b>PHOTO</b>: The sessions take place in the offices of the ABC Communautaire.</p>', 'formation-pour-les-femmes-en-entrepreunariat', 'yes', '2022-05-23 11:14:44', '2022-05-23 09:14:44'),
(8, 'Bilan Positif pour la Jeunesse', 'Positive Report for Youth', NULL, '1652652255.jpg', '<p>Le champ d’action de Sofifran s’est encore élargi cette année avec l’offre d’un camp d’été, une première pour l’organisme. Du 2 juillet au 2 août, une vingtaine d’enfants ont vécu une expérience axée sur les arts de toutes disciplines avec une touche multiculturelle.</p><p>« C’était, de l’avis des parents, assez original comme camp », confie Fété Kimpiobi, directrice générale de Sofifran. Conçues pour les jeunes de 5 à 12 ans, les activités se déroulaient du lundi au vendredi et étaient à ce point appréciées que les enfants inscrits pour une semaine ont demandé – avec succès – à leurs parents de les inscrire à nouveau pour le reste du camp. Plusieurs parents ont d’ailleurs suggéré que ce programme soit offert pour la semaine de relâche en mars et ont manifesté le désir d’y inscrire leurs enfants à nouveau l’été prochain si l’occasion se présente.</p><p>Ce camp d’été s’est donc avéré un succès incontestable qui doit être crédité non seulement au personnel de Sofifran, mais aussi à son partenaire dans le cadre de ce programme : l’organisme Unik. Dirig</p><p>é par Justine Gogoua, Unik était responsable des activités qui se sont avérées des plus diversifiées. Les jeunes se sont adonnés à la peinture, au dessin, à la danse, à l’improvisation théâtrale, à la musique, etc. Il ne s’agissait pas seulement d’une initiation à ces disciplines puisqu’en quatre semaines, le progrès des uns et des autres étaient visibles, d’autant plus que chaque participant était orienté en fonction de son potentiel et de ses intérêts.</p><p>« Il y avait cette liberté de créer qui leur était offerte », commente Mme Kimpiobi. Cette autonomie a incité les enfants à s’investir avec encore plus de passion dans leurs créations, notamment l’exposition et le spectacle qui clôturaient chaque semaine et auxquels les parents étaient invités. C’est en cette occasion que la valeur et le bien-fondé de ce camp d’été brillaient le plus.</p><p>Y aura-t-il une suite à ce projet pilote? Difficile de l’affirmer pour le moment mais ils sont nombreux, du plus petit au plus grand, à le souhaiter.</p><p><b>PHOTO (Crédit photo : Sofifran)</b> – Les jeunes ont eu l’occasion de créer des spectacles théâtraux et musicaux.</p>', '<p>Sofifran\'s scope of action was further expanded this year with the offer of a summer camp, a first for the organization. From July 2 to August 2, about twenty children lived an experience centered on the arts of all disciplines with a multicultural touch.</p><p>\"It was, in the opinion of the parents, quite original as a camp\", confides Fété Kimpiobi, general manager of Sofifran. Designed for young people aged 5 to 12, the activities took place from Monday to Friday and were so popular that children registered for one week asked – successfully – their parents to register them again for the rest of the camp. . Several parents have also suggested that this program be offered for spring break in March and have expressed a desire to enroll their children in it again next summer if the opportunity arises.</p><p>This summer camp has therefore proved to be an undeniable success which must be credited not only to the staff of Sofifran, but also to its partner in the context of this program: the organization Unik. directed</p><p>ed by Justine Gogoua, Unik was responsible for the activities which turned out to be very diversified. The young people devoted themselves to painting, drawing, dancing, theatrical improvisation, music, etc. It was not just an introduction to these disciplines since in four weeks, everyone\'s progress was visible, especially since each participant was guided according to their potential and interests.</p><p>“There was this freedom to create that was offered to them,” comments Ms. Kimpiobi. This autonomy encouraged the children to invest themselves with even more passion in their creations, in particular the exhibition and the show which closed each week and to which the parents were invited. It was on this occasion that the value and merits of this summer camp shone brightest.</p><p>Will there be a sequel to this pilot project? It\'s hard to say for the moment, but there are many of them, from the youngest to the oldest, who want it.</p><p><b>PHOTO (Photo credit: Sofifran)</b> – Young people had the opportunity to create theatrical and musical performances.</p>', 'bilan-positif-pour-la-jeunesse', 'yes', '2022-05-23 11:14:34', '2022-05-23 09:14:34'),
(9, 'ENTREPREND', 'UNDERTAKES', NULL, '1652654373.jpg', '<p>Monter son entreprise, le rêve pour beaucoup d’entre nous ! Oui, mais comment ? Les craintes, les démarches, les financements peuvent être bien intimidants vue de l’extérieur.&nbsp;<span style=\"font-size: 1rem;\">C’est pourquoi Sofifran a mis en place le projet ”EntrePrend” qui prépare et accompagne les participantes à lancer et à réussir la vie d’entrepreneure.</span></p><p>Ce projet, aux côtés de 3 partenaires actifs : SÉO, SADDEC, et YPMD Consulting, est réparti en ateliers jusqu’au mois de Mars 2020, afin de former, d’aider et d’accompagner toute femme francophone désireuse de s’établir à son compte. Nos Partenaires prennent en charge des ateliers qui abordent chacun un angle important du processus entrepreneurial et préparent les participantes à la réalité de la vie d’affaires.</p><ul><li>YPMD Consulting : présentation de l’atelier sur « La culture entrepreneuriale au Canada vs pays d’origine ». Objectif : comprendre et assimiler les différences entre les deux pratiques et la nécessité d’envisager autrement l’entrepreneuriat au Canada.</li><li>La SÉO : une série d’ateliers comprenant six sessions dont le premier a pour titre « Lance ton affaire ». Objectif : fournir aux participantes les outils et le coaching indispensables à l’aboutissement et à la réussite de son entreprise.</li><li>La SADDEC : atelier « Fais le grand saut en confiance et relève le défi entrepreneurial » modèle de réussite, partage d’expériences et de savoir-faire entrepreneuriaux.</li></ul><p>Inscrivez-vous par courriel en cliquant ou par téléphone au <b>905-714-7333</b></p>', '<p>Starting a business is a dream for many of us! Yes but how ? Fears, procedures, funding can be very intimidating from the outside.&nbsp;<span style=\"font-size: 1rem;\">This is why Sofifran has set up the “EntrePrend” project which prepares and supports participants to launch and succeed in the life of an entrepreneur.</span></p><p>This project, alongside 3 active partners: SÉO, SADDEC, and YPMD Consulting, is divided into workshops until March 2020, in order to train, help and support any French-speaking woman wishing to settle in its account. Our Partners run workshops that each address an important angle of the entrepreneurial process and prepare participants for the reality of business life.</p><ul><li>YPMD Consulting: presentation of the workshop on “Entrepreneurial culture in Canada vs. country of origin”. Objective: to understand and assimilate the differences between the two practices and the need to consider entrepreneurship in Canada differently.</li><li>The SÉO: a series of workshops comprising six sessions, the first of which is entitled “Launch your business”. Objective: to provide participants with the tools and coaching essential to the success of their business.</li><li>La SADDEC: workshop “Take the leap in confidence and take up the entrepreneurial challenge” model of success, sharing of experiences and entrepreneurial know-how.</li></ul><p>Register by email by clicking or by phone at <b>905-714-7333</b></p>', 'entreprend', 'yes', '2022-05-23 11:14:24', '2022-05-23 09:14:24'),
(10, 'EMERGENCE', 'EMERGENCY', NULL, '1652654542.jpg', 'À travers cette étude, SOFIFRAN collabore avec des institutions scolaires et parascolaires, des garderies, des institutions décisionnelles publiques et privées pour évaluer sous l’angle systémique si leurs politiques actuelles d’accès aux services de garde se basent sur les besoins spécifiques et réels des femmes.En amont, l’étude examine les lacunes et les faiblesses des rapports des rencontres ayant motivé les conditions et déterminé les décisions actuelles d’accès aux services de garde. Elle identifie en aval les obstacles et les défis pour les femmes, de même que leurs impacts économiques et sociaux dans leur vie.Pour atteindre les objectifs poursuivis par le projet, l’étude est menée avec un groupe focus de femmes de la région prises dans chaque communauté de différentes villes.Une analyse comparative sur l’angle du genre est menée au niveau des institutions afin de déterminer l’impact de cette barrière pour le développement économique et social des femmes. L’étude s’appuie sur la concertation, la collaboration, le partenariat. Elle est réalisée avec des organismes clés de la région ainsi que des institutions privées provinciales, ayant une expérience positive à partager et qui ont manifesté un intérêt sincère pour le projet. ÉMERGENCE PLUS, POUR SÉCURISER L’ÉCONOMIE DES FEMMES DU NIAGARA est financé par Condition Féminine Canada, réalisé par Sofifran en partenariat avec : Cerf Niagara, Caisse Populaire Sud-Ouest Ontario, La Boîte à Soleil, Niagara Region, Université Brock, Le Conseil scolaire catholique MonAvenir, Le Conseil scolaire Viamonde.', '<p>Through this study, SOFIFRAN is collaborating with educational and extracurricular institutions, day care centres, public and private decision-making institutions to assess from a systemic perspective whether their current policies for access to child care services are based on the specific and real needs of women.</p><p>Upstream, the study examines the gaps and weaknesses in the reports of the meetings that motivated the conditions and determined the current decisions on access to childcare services. It identifies downstream barriers and challenges for women, as well as their economic and social impacts in their lives.</p><p>To achieve the objectives pursued by the project, the study is conducted with a focus group of women from the region taken from each community in different cities.</p><p>A comparative analysis on the angle of gender is carried out at the level of the institutions in order to determine the impact of this barrier for the economic and social development of women. The study is based on consultation, collaboration and partnership. It is carried out with key organizations in the region as well as private provincial institutions, with positive experience to share and who have shown a sincere interest in the project.</p><p><b>EMERGENCE PLUS, TO SECURE NIAGARA\'S WOMEN\'S ECONOMY</b> is funded by Status of Women Canada, produced by Sofifran in partnership with: Cerf Niagara, Caisse Populaire Sud-Ouest Ontario, La Boîte à Soleil, Niagara Region, Brock University, Le Conseil scolaire Catholic MonAvenir, The Viamonde School Board.<br></p>', 'emergence', 'yes', '2025-08-10 12:06:51', '2022-05-19 12:50:55'),
(11, 'REG’ARTS', 'REG’ARTS', NULL, '1652807391.jpg', 'De la Culture, de l’Art et du Patrimoine, pour, par et avec les jeunes immigrants et les jeunes francophones âgés de 13 à 18+ ans.À travers la création d’une oeuvre scénique, de ses prémisses à sa représentation sur scène, les jeunes s’adonneront à l’écriture de la pièce, la création des costumes, des décors, l’habillage lumineux, sonore et musical, et bien plus encore.Le projet REG’Arts a pour objectifs d’enrichir la vie des jeunes francophones par le biais des arts, de la culture et du patrimoine.Le projet leur offre l’accès à des possibilités d’apprentissage et l’opportunité de vivre des expériences artistiques, culturelles et patrimoniales significatives. Les idées forces porteront sur le développement de la sensibilité artistique incorporée dans un processus de création d’une œuvre scénique complète et intégrée par la découverte des différents corps de métiers y afférant.Le projet est pour, par et avec les jeunes sous le mentorat de deux artistes professionnels de renommée : Said Benyoucef et Mosbah Abdelamid.Un comité aviseur composé de cinq jeunes a été mis en place au lancement du projet.Pour toutes inscriptions et informations concernant les ateliers, veuillez nous contacter au 905-714-7333. Vous pouvez aussi vous référer au Calendrier en cliquant pour les prochaines rencontres.<br>Lieu des Ateliers:École Sacré-Coeur 310, rue Fitch, Welland, ON, L3C 4W5 <br>Contact: 905.341.0564 ou 613.413.6595 <br>Une collation est servie à chaque rencontre.', 'Culture, Art and Heritage, for, by and with young immigrants and young Francophones aged 13 to 18+.Through the creation of a scenic work, from its premises to its performance on stage, young people will devote themselves to writing the play, creating costumes, sets, lighting, sound and musical dressing, and even more.The REG’Arts project aims to enrich the lives of young Francophones through arts, culture and heritage.The project offers them access to learning opportunities and the opportunity to live meaningful artistic, cultural and heritage experiences. The key ideas will focus on the development of artistic sensitivity incorporated into a process of creating a complete and integrated scenic work through the discovery of the various related trades.The project is for, by and with young people under the mentorship of two renowned professional artists: Said Benyoucef and Mosbah Abdelamid.An advisory committee made up of five young people was set up when the project was launched.For all registration and workshop information, please contact us at 905-714-7333.You can also refer to the Calendar by clicking for the next meetings.<br>Location of the Workshops:Sacred Heart School 310 Fitch Street, Welland, ON, L3C 4W5<br>Contact: 905.341.0564 or 613.413.6595 <br>A snack is served at each meeting.', 'regarts', 'yes', '2025-08-10 12:10:48', '2022-05-23 09:14:17'),
(12, 'Initiative Émergence Plus pour les Femmes', 'Emergence Plus Initiative for Women', NULL, '1652807061.jpg', '<p>La météo des dernières semaines n’a pas épargné Sofifran : l’organisme cherchait à réunir les divers intervenants impliqués dans le projet Émergence Plus mais les conditions hivernales contrecarraient constamment ses plans. C’est finalement le mardi 12 février que Sofifran a officiellement dévoilé le logo de cette initiative et qu’une première réunion en a rassemblé les partenaires, par vidéoconférence il est vrai.</p><p>Qu’est-ce qu’Émergence Plus? Il faut remonter à avril 2018 pour trouver les origines de ce projet de conciliation travail-famille. C’est sous le nom de Sécuriser les femmes du Niagara que l’idée avait alors été soumise à Condition féminine Canada et finalement acceptée quelques mois plus tard.</p><p>Avec un financement du gouvernement fédéral de 270 000 $ sur trois ans, Sofifran avait dès lors les coudées franches pour, dans un premier temps, mener une étude sur les défis rencontrés par les immigrantes de la région lorsqu’il est question de transports et de services de garde. Avec ces données en main, l’organisme et ses partenaires se pencheront ensuite sur les solutions les plus appropriées et développeront des pratiques qui non seulement répondront à un besoin dans la Péninsule, mais pourraient fort bien devenir un modèle pour d’autres régions.</p><p>Au-delà des territoires, c’est aussi le profil des bénéficiaires potentielles qui est varié : « C’est un projet de société, rappelle Fété Kimpiobi, directrice générale de Sofifran. Ses résultats vont s’appliquer à toutes les femmes, toutes les familles qui sont aux prises avec ce problème ».</p><p>En effet, plusieurs se reconnaîtront dans ces difficultés aussi bien financières que logistiques, où se trouver un moyen de transport qui s’accorde avec les heures d’ouverture de la garderie et l’horaire de travail ou des cours postsecondaires devient un insoluble casse-tête. Il arrive souvent que des femmes aient alors à sacrifier leur carrière pour s’occuper de leurs enfants, ce qui précarise inévitablement leur autonomie financière et leur développement socioprofessionnel. Cette situation est encore plus problématique pour les nouvelles arrivantes dont le statut complexifie parfois l’accès au marché du travail et à certains programmes.</p><p>C’est pourquoi Sofifran, fidèle à son mandat, a décidé l’année dernière d’épauler ces femmes afin qu’elle puisse non seulement être « sécurisées » au plan monétaire et professionnel comme le rappelait le nom originel de cette initiative, mais maintenant « émerger » à une vie nouvelle, plus pratique, moins stressante et plus apte à favoriser leur épanouissement. Le logo d’Émergence Plus, fait de trois papillons, illustre cette transition.</p><p>La réunion du 12 février dernier a mis en contact les membres du comité aviseur, composé de représentants des milieux économique, politique et éducatif représentatifs du Niagara, dans leurs premières démarches pour dégager des stratégies. Pour appuyer ce comité dans ses travaux, un groupe-cible a été mis sur pied, composé de femmes qui ont vécu ou vivent encore cette problématique à laquelle Sofifran tente de trouver une solution. Il est possible que le cercle de participants soit agrandi en fonction des besoins et des possibilités.</p><p>« Je ne pense pas que l’on puisse trouver une solution en claquant des doigts », concède Mme Kimpiobi. N’empêche, Émergence Plus constitue un grand pas dans la bonne direction.</p>', '<p>The weather of the past few weeks has not spared Sofifran: the organization was seeking to bring together the various stakeholders involved in the Émergence Plus project, but the winter conditions constantly thwarted its plans. It was finally on Tuesday February 12 that Sofifran officially unveiled the logo of this initiative and that a first meeting brought together the partners, by videoconference it is true.</p><p>What is Emergence Plus? We have to go back to April 2018 to find the origins of this work-family balance project. It was under the name of Securing Niagara Women that the idea was then submitted to Status of Women Canada and finally accepted a few months later.</p><p>With funding from the federal government of $270,000 over three years, Sofifran therefore had free rein to, as a first step, conduct a study on the challenges faced by immigrant women in the region when it comes to transportation and daycare services. With this data in hand, the organization and its partners will then look at the most appropriate solutions and develop practices that will not only meet a need in the Peninsula, but could very well become a model for other regions.</p><p>Beyond the territories, it is also the profile of potential beneficiaries that is varied: “It is a social project, recalls Fété Kimpiobi, CEO of Sofifran. Its results will apply to all women, all families who are struggling with this problem.”</p><p>Indeed, many will recognize themselves in these difficulties, both financial and logistical, where finding a means of transportation that fits with the opening hours of the daycare and the work schedule or post-secondary courses becomes an insoluble headache. head. It often happens that women then have to sacrifice their careers to take care of their children, which inevitably jeopardizes their financial autonomy and their socio-professional development. This situation is even more problematic for newcomers whose status sometimes complicates access to the labor market and certain programs.</p><p>This is why Sofifran, faithful to its mandate, decided last year to support these women so that they could not only be \"secured\" financially and professionally, as the original name of this initiative reminded us, but now \"emerge\" to a new life, more practical, less stressful and more likely to promote their development. The Émergence Plus logo, made of three butterflies, illustrates this transition.</p><p>The meeting on February 12 brought together the members of the advisory committee, made up of representatives of economic, political and educational circles representative of Niagara, in their first steps to identify strategies. To support this committee in its work, a target group has been set up, made up of women who have experienced or are still experiencing this problem for which Sofifran is trying to find a solution. It is possible that the circle of participants will be enlarged according to needs and possibilities.</p><p>\"I don\'t think we can find a solution by snapping our fingers,\" concedes Ms. Kimpiobi. Nevertheless, Emergence Plus is a big step in the right direction.</p>', 'initiative-emergence-plus-pour-les-femmes', 'yes', '2022-05-23 11:14:07', '2022-05-23 09:14:07'),
(13, 'Les Ateliers Culinaires de Sofifran', 'The Culinary Workshops of Sofifran', NULL, '1652807312.jpg', '<p>L’association Solidarité des femmes et familles immigrantes francophones du Niagara (SOFIFRAN) a fait d’une pierre deux coups, le dimanche 11 mars à Welland, en célébrant la Journée internationale de la femme et, surtout, en clôturant sa série d’ateliers Cuisine saine.</p><p>En bon élève, chacun a apporté un plat appris au cours de l’une de ces rencontres afin de le partager avec la communauté. Riz aux fèves, gratin de pâtes, salades composées et soupe au giraumon – qui se mange traditionnellement chaque 1er janvier pour fêter l’indépendance d’Haïti, première république noire de l’histoire – ont garni la table, alors qu’aux fourneaux, le chef Guy Dongué confectionnait une surprise : des rouleaux de printemps végétariens. Le tout donnait une bonne idée des enseignements retenus tout au long de l’année.</p><p>Ayant réalisé le meilleur plat, Geralda Augustin aura le privilège de recevoir le chef qui cuisinera à son domicile. Tout comme elle, l’ensemble des participants se sont vus remettre un certificat d’ambassadeur en santé.</p><p>Ces ateliers intergénérationnels animés depuis le printemps 2017 par le traiteur torontois et son équipe ont permis à plusieurs familles de se rencontrer dans la cuisine de l’église Trinity, pour apprendre à préparer des plats simples et diététiques.</p><p>« Autour de menus thématiques organisés deux fois par mois, j’ai fait découvrir aux gens des produits que l’on trouve au Canada et que l’on n’a pas l’habitude de cuisiner lorsque l’on vient d’Afrique », raconte M. Dongué, tout en surveillant la cuisson des légumes coupés en julienne qui vont servir de garniture à la pâte phyllo.</p><p>« On a adapté la réalité des immigrants dans leurs pays d’origine à la réalité locale en fusionnant les deux cultures pour que personne ne perde ses repères, tout en mangeant de façon équilibrée, poursuit-il. L’obésité est un phénomène inquiétant. La malbouffe est à chaque coin de rue. J’essaye de contribuer à la combattre, surtout chez les francophones qui ne sont pas assez informés et sensibilisés dans leur langue. »</p><p>Éviter de manger trop salé, trop sucré, trop gras, bannir les cubes de bouillon et autres produits chargés d’additifs aura été l’inlassable message véhiculé par le chef. « On peut tout faire soi-même sans dépenser plus d’argent, affirme-t-il. Il faut prendre le temps, savoir magasiner au bon moment, au bon endroit et préférer les légumes de saison que l’on trouve dans les marchés. »</p><p>Les participants se sont ainsi familiarisés avec des légumes comme l’artichaut ou le fenouil qu’ils ne savaient pas comment cuisiner et des plats qui ne sont pas dans leurs habitudes alimentaires comme la soupe. Les enfants ont plus particulièrement été sensibilisés sur la boîte à lunch, en préparant en septembre dernier des mets sains.</p><p>Alors que l’après-midi s’est conclue par des échanges sur la place des femmes immigrantes dans la société canadienne et le féminisme, l’équipe de SOFIFRAN est d’ores et déjà à pied d’œuvre pour chercher un nouveau financement qui permettra de poursuivre ces ateliers, vecteur de lien social et de saine alimentation.</p>', '<p>The Solidarity of Francophone Immigrant Women and Families of Niagara (SOFIFRAN) association killed two birds with one stone, on Sunday, March 11 in Welland, by celebrating International Women\'s Day and, above all, by closing its series of workshops Healthy cooking.</p><p>As a good student, everyone brought a dish learned during one of these meetings in order to share it with the community. Bean rice pasta gratin mixed salads and pumpkin soup – which is traditionally eaten every January 1 to celebrate the independence of Haiti<span style=\"font-size: 1rem;\">, the first black republic in history – garnished the table, while in the kitchen, Chef Guy Dongué made a surprise:</span></p><p>Having made the best dish, Geralda Augustin will have the privilege of receiving the chef who will cook at her home. Like her, all of the participants received a health ambassador certificate.</p><p>These intergenerational workshops, led since the spring of 2017 by the Toronto caterer and his team, have allowed several families to meet in the kitchen of Trinity Church, to learn how to prepare simple and healthy dishes.</p><p>\"Around thematic menus organized twice a month, I introduced people to products that are found in Canada and that you are not used to cooking when you come from Africa\" , says Mr. Dongué, while supervising the cooking of the julienned vegetables that will serve as a filling for the phyllo dough.</p><p>“We adapted the reality of immigrants in their countries of origin to the local reality by merging the two cultures so that no one lost their bearings, while eating a balanced diet,” he continues. Obesity is a worrying phenomenon. Junk food is around every corner. I try to help fight it, especially among French speakers who are not sufficiently informed and aware of their language. »</p><p>Avoiding eating too salty, too sweet, too fatty, banishing bouillon cubes and other products laden with additives has been the tireless message conveyed by the chef. “You can do everything yourself without spending more money,” he says. You have to take the time, know how to shop at the right time, in the right place and prefer the seasonal vegetables found in the markets. »</p><p>The participants thus became familiar with vegetables such as artichokes or fennel that they did not know how to cook and dishes that are not in their dietary habits such as soup. Children were particularly made aware of the lunch box, by preparing healthy meals last September.</p><p>While the afternoon ended with discussions on the place of immigrant women in Canadian society and feminism, the SOFIFRAN team is already hard at work looking for new funding that will allow us to continue these workshops, a vector of social ties and healthy eating.</p><p><span style=\"font-size: 1rem;\"></span><br></p>', 'les-ateliers-culinaires-de-sofifran', 'yes', '2022-05-23 11:13:57', '2022-05-23 09:13:57');
INSERT INTO `projets` (`id`, `titre_fr`, `titre_en`, `objectif`, `image`, `description_fr`, `description_en`, `slug`, `ended`, `created_at`, `updated_at`) VALUES
(14, 'Entrepreneuriat pour les femmes immigrantes du Niagara - Garderie en milieu familial', 'Entrepreneurship for Immigrant Women in Niagara - Home Day Care', NULL, '1691757703.png', '<p>Le projet « Entrepreneuriat pour les femmes immigrantes du Niagara » est financé par la Fondation Canadienne des Femmes pour une période de quatre années.</p><p>Après le succès du projet « Sécuriser l’économie des femmes du Niagara », financé en son temps par le ministère de Femmes et Égalité de Genre Canada (FEGC), notre intention, à travers le présent projet, est de mettre en place un programme qui permettrait aux femmes immigrantes de se lancer en entreprenariat dans le domaine des services de garde en milieu familial. En collaboration avec les services de la petite enfance du Niagara, Sofifran offrira des séances d\'informations spéciales et spécifiques en français avec des groupes cibles de femmes pour la mise sur pied de leur propre garderie. Avec le soutien de ce projet, les femmes pourront acquérir les connaissances, les outils et les capacités nécessaires pour gérer une entreprise et offrir des services de garde fiables, sécuritaires et abordables pour les familles du Niagara.</p>', '<p>The \"Entrepreneurship for Immigrant Women in Niagara\" project is funded by the Canadian Women\'s Foundation for a four-year period.</p><p><span style=\"font-size: 1rem;\">Following the success of the \"Securing the Niagara Women\'s Economy\" project, funded in its time by the Ministry of Women and Gender Equality Canada (WGGEC), our intention, through the present project, is to set up a program that would enable immigrant women to launch themselves into entrepreneurship in the field of family childcare. In collaboration with Niagara\'s Early Childhood Services, Sofifran will offer special and specific information sessions in French with targeted groups of women to help them set up their own daycare center. With the support of this project, women will gain the knowledge, tools and skills to run a business and provide reliable, safe and affordable childcare for Niagara families.</span><br></p>', 'canada-en-fetes', 'no', '2025-08-11 16:33:01', '2023-08-11 10:41:44'),
(15, 'Fondation canadienne des femmes - Des ateliers centrés sur la femme', 'Canadian Women\'s Foundation - Woman-centered workshops', NULL, '1691036338.jpeg', '<p>Ce projet est une suite Avec les fonds de la Fondation canadienne des femmes, nous avons mis en place un service d\'intervenante communautaire pour soutenir les femmes et les familles affectées par la violence familiale. Le programme permet d\'offrir du soutien et de l\'accompagnement, des outils et des informations culturellement adaptés aux besoins femmes et filles immigrantes francophones dans la région du Niagara afin de les sensibiliser sur l\'impact de la violence familiale et comment y remédier.<br></p>', '<p>With funding from the Canadian Women\'s Foundation, we have set up a community outreach service to support women and families affected by domestic violence. The program provides support and accompaniment, as well as culturally adapted tools and information, to Francophone immigrant women and girls in the Niagara region, to raise awareness of the impact of domestic violence and how to deal with it.<br></p>', 'fondation-trillium-de-lontario-programme-du-fonds-pour-les-communautes-resilientes', 'yes', '2025-08-10 12:12:07', '2025-08-10 12:12:07');
INSERT INTO `projets` (`id`, `titre_fr`, `titre_en`, `objectif`, `image`, `description_fr`, `description_en`, `slug`, `ended`, `created_at`, `updated_at`) VALUES
(16, 'Communaute de pratique en entrepreneuriat  pour les communautés noires', 'Community of entrepreneurship in entrepreneurship for black communities', NULL, '1653308020.jpg', '<p>Le projet consiste à développer et à mettre en place une communauté de pratique permettant aux jeunes entrepreneurs noirs de développer\r\nleur capacité organisationnelle et d’accéder à des services de conseils afin\r\nd’accroitre leur rendement. Ils vont mettre en commun leurs difficultés, leurs\r\nexpériences dans un domaine particulier et ce, dans le but d’approfondir leurs\r\nconnaissances et développer de nouveaux savoirs liés à leur pratique\r\nprofessionnelle.<o:p></o:p></span></p><p style=\"margin-top: 0cm; text-align: justify;\">\r\n\r\n<span style=\"box-sizing: border-box\"></span></p><p style=\"margin-top:0cm;text-align:justify\"><span style=\"font-family:&quot;Source Sans Pro&quot;,sans-serif;\r\ncolor:black\">Les activités du projet comprennent: du mentorat, des mini\r\nrencontres virtuelles de réseautage, des presentation de modèles de réussite.\r\nDes outils favorisant l’accès au E-commerce pour la promotion, la vente des\r\nproduits, la bonne gestion financière et l’utilisation des réseaux sociaux pour\r\nla publicité et visibilité de leurs entreprises afin d’élargir leurs réseaux et\r\nnouer des occasions d’affaires.<u1:p style=\"box-sizing: border-box;\"></u1:p></span><o:p></o:p></p><p style=\"margin-top: 0cm; text-align: justify;\"><span style=\"text-align: left; font-size: 11pt; line-height: 107%; font-family: &quot;Source Sans Pro&quot;, sans-serif;\">Ce projet est piloté par Sofifran, cependant, il\r\nvise tout entrepreneur.e francophone noir.e résidant le Sud de l’Ontario (voir\r\nla liste ci-dessous).&nbsp;</span><span style=\"font-size: 1rem; text-align: left;\">&nbsp;Les résultats anticipés sont de\r\npromouvoir l’égalité des genres en favorisant la participation des femmes\r\nentrepreneures et d’appuyer les entrepreneurs en fournissant des outils pour\r\naccroitre leur rendement. Nous comptons encourager 60 entreprises pendant une\r\npériode de 36 mois</span><span style=\"text-align: left; font-size: 21.3333px;\"><b>.</b></span></p><p style=\"margin-top:0cm;text-align:justify\"><span style=\"font-family: &quot;Source Sans Pro&quot;, sans-serif;\">Vous êtes un entrepreneur noir ou une entrepreneure noire ou vous envisagez de le\r\ndevenir mais vous ignorez par où démarrer ? </span><span style=\"font-family: &quot;Source Sans Pro&quot;, sans-serif;\">Cliquez sur ce lien pour vous inscrire :&nbsp;<a href=\"https://form.jotform.com/220824268786062\" target=\"_blank\" style=\"font-size: 1rem;\"><span style=\"color: rgb(0, 86, 179); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">form.jotform.com</span></a><o:p></o:p></span></p><p style=\"margin-top: 0cm; text-align: justify;\"><img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"font-size: 1rem; text-align: left; width: 761.5px;\"><br></p>', '<p style=\"text-align: justify; \">The project consists of developing and implementing a community of practice that will allow young black entrepreneurs to develop their organizational capacity and access consulting services in order to increase their performance. They will share their challenges and experiences in a particular field in order to deepen their knowledge and develop new skills related to their professional practice.</p><p style=\"text-align: justify;\">Project activities include: mentoring, virtual mini networking meetings, and presentations of success stories. E-commerce tools for promotion, product sales, financial management and the use of social networks for advertising and visibility of their businesses to expand their networks and develop business opportunities.</p><p style=\"text-align: justify;\">This project is led by Sofifran, however, it is aimed at any Black Francophone entrepreneur residing in Southern Ontario (see list below).&nbsp; The anticipated outcomes are to promote gender equality by encouraging the participation of women entrepreneurs and to support entrepreneurs by providing tools to increase their performance. We plan to support 60 businesses over a 36-month period.</p><p style=\"text-align: justify;\">Are you a Black entrepreneur or considering becoming one but don\'t know where to start? Click on this link to sign up:&nbsp;<a href=\"https://form.jotform.com/220824268786062\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255); font-size: 1rem; text-align: left;\">form.jotform.com</a></p><p><a href=\"https://form.jotform.com/220824268786062\"></a></p><p><img src=\"data:image/png;base64,\" style=\"width: 761.5px;\" data-filename=\"image.png\"><br></p>', 'communaute-de-pratique-en-entrepreneuriat-pour-les-communautes-noires', 'yes', '2025-05-19 18:14:14', '2025-05-19 18:14:14');
INSERT INTO `projets` (`id`, `titre_fr`, `titre_en`, `objectif`, `image`, `description_fr`, `description_en`, `slug`, `ended`, `created_at`, `updated_at`) VALUES
(21, 'Chaîne de Télévision Communautaire Sofifran', 'Sofifran Community Television Channel', NULL, '1741876351.png', '<p>WELLAND, le 1er novembre 2024 – SOFIFRAN (Solidarité des femmes et familles interconnectées francophones du Niagara) est honorée&nbsp d’annoncer avoir obtenu une subvention de 95 800,00 $ de la Fondation Trillium de l’Ontario, dans le cadre du programme du fonds de démarrage. Ce financement stratégique permettra à l\'organisme de mettre en œuvre plusieurs initiatives marquantes visant à renforcer la participation et la visibilité de la communauté francophone du Niagara. Grâce à cette subvention, SOFIFRAN pourra entreprendre les actions suivantes :<br>- Élaborer un plan stratégique pour la création d’une chaîne de télévision communautaire visant à promouvoir la diversité culturelle et à favoriser l’inclusion des francophones au sein de programmes accessibles en ligne.<br> - Concevoir et produire trois capsules vidéo pilotes, servant de base aux contenus futurs de la chaîne, conformément à la mise en œuvre de ce plan stratégique. Ce projet constitue une étape essentielle pour renforcer les capacités de l’organisme à répondre aux besoins de la communauté francophone du Niagara, tout en intégrant les évolutions actuelles en matière de communication numérique.</p><p>Depuis plus de 17 ans, SOFIFRAN œuvre activement en offrant une gamme de services sociaux, culturels, éducatifs et économiques à la population immigrante francophone et francophile du Niagara. L’organisme joue un rôle fondamental en tant que catalyseur de cohésion sociale facilitant les échanges interculturels et collaborant&nbsp;avec de nombreux&nbsp partenaires communautaires. La Fondation Trillium de l’Ontario (FTO) est une institution gouvernementale provinciale de premier plan, soutenant des projets communautaires visant à améliorer la qualité de vie en Ontario. Lors de l\'exercice 2023-2024, elle a alloué environ 110 millions de dollars pour soutenir plus de 1 000 projets communautaires à travers l’Ontario dans des domaines variés, tels que les services sociaux, l’art, la culture, les sports et les loisirs, l’environnement durable et le développement économique. Pour en savoir plus sur la Fondation Trillium de l’Ontario, visitez leur site web à l\'adresse <a href=\"http://www.otf.ca.\" target=\"_blank\">otf.ca.</a> Pour davantage d’informations sur SOFIFRAN et ses projets, consultez notre site web à l’adresse www.sofifran.org</p>', '<p>WELLAND, November 1, 2024 - SOFIFRAN (Solidarité des femmes et familles interconnectées francophones du Niagara) is honoured to announce that it has received a grant of $95,800.00 from the Ontario Trillium Foundation, as part of the Seed Fund program. This strategic funding will enable the organization to implement several significant initiatives aimed at strengthening the participation and visibility of Niagara\'s francophone community. Thanks to this grant, SOFIFRAN will be able to undertake the following actions:</p><p>- Develop a strategic plan for the creation of a community television channel aimed at promoting cultural diversity and fostering the inclusion of Francophones in online programming.</p><p>- Design and produce three pilot video vignettes to serve as the basis for the channel\'s future content, in line with the implementation of this strategic plan. This project is an essential step in strengthening the organization\'s ability to meet the needs of Niagara\'s francophone community, while integrating current developments in digital communication.<br><span style=\"font-size: 1rem;\">For over 17 years, SOFIFRAN has been actively involved in providing a range of social, cultural, educational and economic services to Niagara\'s Francophone and Francophile immigrant population. The organization plays a fundamental role as a catalyst for social cohesion, facilitating cross-cultural exchanges and collaborating with a wide range of organizations.</span></p><p><span style=\"font-size: 1rem;\">The Ontario Trillium Foundation (OTF) is a leading provincial government institution, supporting community projects to improve the quality of life in Ontario. In fiscal year 2023-2024, it has allocated approximately $110 million to support more than 1,000 community projects across Ontario in areas as diverse as social services, arts, culture, sports and recreation, environmental sustainability and economic development. To find out more about the Ontario Trillium Foundation, visit their website at otf.ca. For more information on SOFIFRAN and its projects, visit our website at www.sofifran.org.</span></p>', 'sensibilisation-a-la-nutrition-saine-et-aux-activites-physiques', 'yes', '2026-01-07 19:13:26', '2026-01-07 19:13:26'),
(22, 'Rêve d’hier pour toute une communauté, devenu une réalité aujourd’hui', 'Awareness of healthy nutrition and physical activities', NULL, '1741875672.png', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size: 1rem;\">C\'est avec une immense fierté et un profond honneur que SOFIFRAN vous présente le livre de recettes de beignet, un projet conçu, élaboré et réalisé grâce à la collaboration des femmes immigrantes francophones du Niagara.</span></p><p class=\"MsoNormal\" style=\"text-align:justify\">Ce livre témoigne du talent, de la créativité et de la résilience des femmes qui, par leur savoir-faire et leur passion, ont su allier traditions culinaires et échanges interculturels. Il incarne non seulement un hommage à leurs racines, mais aussi à la richesse de la diversité qui fait notre force.</p><p class=\"MsoNormal\" style=\"text-align:justify\">SOFIFRAN tient à exprimer sa sincère gratitude envers le programme FACC de Patrimoine canadien pour son soutien financier indispensable à la réalisation de ce projet. Nous remercions également la maison d’édition L’Empreinte du Passant pour son expertise, les participantes qui ont généreusement partagé leurs recettes et leurs histoires, ainsi que les nombreux collaborateurs sans lesquels ce projet n’aurait pas vu le jour.</p><p class=\"MsoNormal\" style=\"text-align:justify\">Nous vous souhaitons à toutes et à tous une belle découverte de ces saveurs et de ces récits, fruits d’une aventure collective unique. Bonne lecture !</p><p class=\"MsoNormal\" style=\"text-align: center;\"><a href=\"https://heyzine.com/flip-book/34a04d3506.html#page/1\" target=\"_blank\">CLIQUEZ ICI POUR VOIR UN EXTRAIT</a></p><p class=\"MsoNormal\" style=\"text-align:justify\">NB : le livre est disponible chez Sofifran depuis le 22 décembre au coût de 30$.</p>', '<p>It is with immense pride and deep honor that SOFIFRAN presents the beignet cookbook, a project conceived, developed, and produced thanks to the collaboration of Francophone immigrant women in Niagara.</p><p>This book is a testament to the talent, creativity, and resilience of the women who, through their expertise and passion, have combined culinary traditions and intercultural exchanges. It embodies not only a tribute to their roots, but also to the richness of diversity that is our strength.</p><p>SOFIFRAN would like to express its sincere gratitude to the Canadian Heritage FACC program for its essential financial support for this project. We also thank the publishing house L’Empreinte du Passant for its expertise, the participants who generously shared their recipes and stories, and the many collaborators without whom this project would not have seen the light of day.</p><p>We wish you all a wonderful discovery of these flavors and stories, the fruits of a unique collective adventure. Enjoy reading!</p><p style=\"text-align: center; \"><a href=\"https://heyzine.com/flip-book/34a04d3506.html#page/1\" target=\"_blank\">CLICK HERE FOR SEE A MORE</a></p><p>Note: The book has been available from Sofifran since December 22nd for $30.</p><p>Envoyer des commentaires</p><p>Panneaux latéraux</p><p>Historique</p><p>Enregistrées</p><p>Afficher le dictionnaire</p>', 'le-beignet-africain', 'yes', '2025-08-07 19:03:37', '2025-08-07 19:03:37'),
(23, 'Lutte contre le racisme', 'Fighting racism', NULL, '1747516109.jpg', '<p>Le projet « Lutte contre le racisme » représente un engagement solide et durable pour combattre toutes les formes de racisme, en particulier le racisme systémique qui touche en général les immigrants et en particuliers les femmes immigrantes spécialement francophones.&nbsp;</p><p>&nbsp; L\'objectif de ce projet est d\'éduquer, de sensibiliser et d\'engager des personnes et des communautés à reconnaître, déconstruire et lutter contre les structures et comportements racistes présents dans différents domaines de la société.&nbsp; Nous nous engageons à lutter contre des injustices cachées qui persistent au sein de normes, des lois, d\'institutions et d\'attitudes.&nbsp; Le but est de construire un cadre où la diversité est valorisée et où l\'on lutte courageusement contre les inégalités raciales, religieuses, culturelles, de genre, etc.</p><p>&nbsp; Le projet « Antiracisme Systémique » répond à une nécessité urgente de combattre les inégalités raciales, religieuses, culturelles, de genre, ou autres, toujours présentes dans nos sociétés.&nbsp; La formation est un outil efficace pour stimuler les réflexions, instruire et promouvoir un changement de mentalité durable et importante.&nbsp; Elle fournit à chaque participant les outils nécessaires pour déceler les processus racistes dans son cadre de vie personnel et professionnel, et pour y réagir de façon anticipée.</p><p>&nbsp;Par le biais de cette formation, notre objectif est de consolider la cohésion sociale, de favoriser l\'égalité des droits et d\'établir une communauté où le respect réciproque et la diversité sont valorisés et honorés.</p>', '<p>The “<span style=\"font-size: 1rem;\">Fighting racism</span><span style=\"font-size: 1rem;\">” project represents a solid and lasting commitment to combat all forms of racism, in particular systemic racism, which affects immigrants in general and immigrant women in particular, especially French-speaking women.</span></p><p>&nbsp; The aim of this project is to educate, raise awareness and engage individuals and communities in recognizing, deconstructing and combating racist structures and behaviors present in different areas of society.&nbsp; We are committed to fighting hidden injustices that persist within norms, laws, institutions and attitudes.&nbsp; The aim is to build a framework in which diversity is valued, and in which racial, religious, cultural, gender and other inequalities are courageously combated.</p><p>&nbsp; The “Systemic Anti-Racism” project responds to an urgent need to combat the racial, religious, cultural, gender and other inequalities still present in our societies.&nbsp; Training is an effective tool for stimulating reflection, educating and promoting a lasting and significant change in mentality.&nbsp; It provides each participant with the necessary tools to detect racist processes in his or her personal and professional environment, and to react to them in a proactive manner.</p><p>Through this training, our aim is to consolidate social cohesion, promote equal rights and establish a community where mutual respect and diversity are valued and honored.</p>', 'lutte-contre-lantiracisme-systemique', 'yes', '2026-07-15 21:30:02', '2026-07-15 21:30:02');
INSERT INTO `projets` (`id`, `titre_fr`, `titre_en`, `objectif`, `image`, `description_fr`, `description_en`, `slug`, `ended`, `created_at`, `updated_at`) VALUES
(24, 'Renforcement des capacités pour répondre aux besoins des femmes de niagara', 'Capacity building to meet the needs of women in Niagara', NULL, '1747678700.png', 'Welland, le 15 février 2025 – SOFIFRAN a le plaisir d’annoncer qu’elle est le récipiendaire d’un financement de 362 391 $ dans le cadre du Programme de promotion de la femme du ministère des Femmes et Égalité des genres du Canada. Ce soutien financier permettra à notre organisme de mettre en œuvre le projet « Renforcement des capacités pour répondre aux besoins des femmes du Niagara ». Ce projet de 18 mois vise à renforcer la capacité de SOFIFRAN à promouvoir l’égalité des genres et à aborder les défis spécifiques auxquels font face les femmes immigrantes francophones dans la région du Niagara. Il s’articulera autour de plusieurs axes : une recherche approfondie, une analyse externe, ainsi que des consultations communautaires pour mieux comprendre les enjeux vécus par ces femmes et identifier les actions prioritaires à entreprendre selon une approche ACS+. Parmi les activités clés du projet, il y aura l’élaboration d’un plan stratégique, le développement de partenariats et la formation de l’équipe de SOFIFRAN, notamment en matière de santé mentale, d’outils numériques et de logiciels informatiques. Une évaluation rigoureuse sera également menée pour mesurer l’impact du projet et en assurer le suivi. SOFIFRAN tient à exprimer sa sincère gratitude au gouvernement du Canada et au ministère des Femmes et Égalité des genres Canada pour leur soutien financier, essentiel à la réalisation de cette initiative. Pour plus de renseignements sur SOFIFRAN, visitez www.sofifran.org. <img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 672.457px;\"><span lang=\"FR-CA\" style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Bookman Old Style&quot;,serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-bidi-font-family:&quot;Times New Roman&quot;;\r\nmso-font-kerning:0pt;mso-ligatures:none\"><o:p></o:p></span>', '<p>Welland, February 15, 2025 - SOFIFRAN is pleased to announce that it is the recipient of $362,391 in funding from the Women\'s Program of the Canadian Ministry of Women and Gender Equality. This financial support will enable our organization to implement the “Capacity Building to Meet the Needs of Women in Niagara” project.</p><p>This 18-month project aims to strengthen SOFIFRAN\'s capacity to promote gender equality and address the specific challenges faced by French-speaking immigrant women in the Niagara region. It will focus on in-depth research, external analysis and community consultations to better understand the issues faced by these women and identify priority actions to be undertaken using a GBA+ approach.</p><p>Key project activities will include drawing up a strategic plan, developing partnerships and training the SOFIFRAN team, particularly in mental health, digital tools and computer software. A rigorous evaluation will also be carried out to measure and monitor the project\'s impact.</p><p>SOFIFRAN would like to express its sincere gratitude to the Government of Canada and the Department of Women and Gender Equality Canada for their financial support, essential to the realization of this initiative.</p><p>For more information on SOFIFRAN, visit <a href=\"http://www.sofifran.org.\" target=\"_blank\">sofifran.org.</a></p><p><img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 672.457px;\"><br></p>', 'renforcement-des-capacites-pour-repondre-aux-besoins-des-femmes-de-niagara', 'no', '2025-08-12 11:27:19', '2025-08-12 11:27:19');
INSERT INTO `projets` (`id`, `titre_fr`, `titre_en`, `objectif`, `image`, `description_fr`, `description_en`, `slug`, `ended`, `created_at`, `updated_at`) VALUES
(26, 'Projet de garderie en milieu familial', 'Home-based daycare project', NULL, '1760701151_68f22adfb85b2.jpg', '<p>Un programme de mentorat pour renforcer l’autonomie et la réussite des femmes francophones</p><p>Le projet de garderie en milieu familial de SOFIFRAN s’inscrit dans une vision globale de soutien à l’entrepreneuriat féminin et à la qualité des services à la petite enfance dans la région du Niagara.</p><p>Ce programme vise à accompagner, former et outiller les femmes francophones désireuses d’offrir un service de garde à domicile répondant aux normes de qualité, de sécurité et de bien-être des enfants.</p><p>Objectif du projet</p><p>L’objectif principal du projet est de favoriser l’autonomie économique des femmes francophones tout en répondant aux besoins croissants en matière de services de garde en français dans la région.</p><p>À travers un programme de mentorat structuré, les participantes reçoivent un accompagnement personnalisé leur permettant de :</p><p>comprendre les exigences liées à l’ouverture d’une garderie en milieu familial ;</p><p>acquérir les notions essentielles en pédagogie, santé et sécurité ;</p><p>apprendre à gérer efficacement leur entreprise de garde ;</p><p>s’inspirer des meilleures pratiques grâce à des témoignages et ateliers interactifs.</p><p>3eme cohorte – Ateliers de mentorat</p><p>La 3eme cohorte du projet débute sa phase de mentorat le 7 octobre 2025, avec un atelier chaque mardi à 18h30 offert en ligne.</p><p>Vanessa Aubourg et Clarice Djuikouo partageront leur expertise lors des rencontres hebdomadaires et aborderont des thèmes variés, allant de la gestion quotidienne d’une garderie à la planification d’activités éducatives, en passant par la relation avec les parents et la communauté.</p><p>Partenaires et financement</p><p>Ce projet est réalisé en collaboration avec la Région du Niagara et financé par la Fondation canadienne des femmes.</p><p>Grâce à leur soutien, SOFIFRAN poursuit sa mission de promouvoir la solidarité, l’action et l’innovation au sein de la communauté francophone.</p><p>Une initiative porteuse d’avenir</p><p>Au-delà de la formation, ce projet représente un levier d’inclusion et d’autonomisation pour les femmes francophones, leur permettant de concilier vie familiale, engagement communautaire et développement professionnel.</p><p>SOFIFRAN croit fermement que chaque femme a le potentiel d’être une actrice du changement dans sa communauté — et ce programme lui en donne les moyens.</p>', '<p>A mentoring program to empower Francophone women and help them succeed</p><p>SOFIFRAN\'s home daycare project is part of a broader vision to support female entrepreneurship and high-quality early childhood services in the Niagara region.</p><p>This program aims to support, train, and equip Francophone women who want to offer home-based childcare services that meet standards of quality, safety, and child welfare.</p><p>Project objective</p><p>The main objective of the project is to promote the economic independence of Francophone women while meeting the growing need for French-language childcare services in the region.</p><p>Through a structured mentoring program, participants receive personalized support that enables them to:</p><p>understand the requirements for opening a home daycare center;</p><p>learn the basics of education, health, and safety;</p><p>learn how to effectively manage their childcare business;</p><p>draw inspiration from best practices through testimonials and interactive workshops.</p><p>3rd cohort – Mentoring workshops</p><p>The project\'s third cohort will begin its mentoring phase on October 7, 2025, with a weekly workshop offered online every Tuesday at 6:30 p.m.</p><p>Vanessa Aubourg and Clarice Djuikouo will share their expertise during weekly meetings and address a variety of topics, ranging from the day-to-day management of a daycare center to planning educational activities and building relationships with parents and the community.</p><p>Partners and funding</p><p>This project is being carried out in collaboration with the Niagara Region and funded by the Canadian Women\'s Foundation.</p><p>Thanks to their support, SOFIFRAN is continuing its mission to promote solidarity, action, and innovation within the Francophone community.</p><p>An initiative with a promising future</p><p>Beyond training, this project is a catalyst for inclusion and empowerment for French-speaking women, allowing them to balance family life, community involvement, and professional development.</p><p>SOFIFRAN firmly believes that every woman has the potential to be an agent of change in her community—and this program gives her the means to do so.</p>', 'projet-de-garderie-en-milieu-familial', 'no', '2025-10-17 11:42:58', '2025-10-17 11:42:58'),
(28, 'Renforcer les capacités pour des services équitables aux réfugiés et nouveaux arrivants', 'Strengthening Capacities for Equitable Services for Refugees and Newcomers.', NULL, '1784150960_6a57fbb01baf5.jpg', '<p>SOFIFRAN annonce le lancement du projet « Renforcer les capacités pour des services équitables aux réfugiés et nouveaux arrivants », une initiative visant à favoriser l’inclusion, l’autonomisation et le leadership des femmes au bénéfice des familles et des communautés.<br><br>Ce projet a pour objectif de renforcer les capacités communautaires afin d’offrir des services plus équitables, sécuritaires et bienveillants aux réfugiés et aux nouveaux arrivants. Il met l’accent sur l’accès aux ressources, le développement des compétences, la confiance en soi, l’entraide et la solidarité.<br><br>SOFIFRAN remercie chaleureusement Immigration, Réfugiés et Citoyenneté Canada ainsi qu’OCASI, pour leur appui financier et leur confiance. Leur soutien rend possible la mise en œuvre de cette initiative importante pour les femmes, les familles et les communautés francophones issues de la diversité.<br><br>Ensemble, nous poursuivons notre engagement pour une communauté plus inclusive, équitable et solidaire.</p>', '<p>SOFIFRAN is pleased to announce the launch of the project “Strengthening Capacities for Equitable Services for Refugees and Newcomers.” This initiative aims to promote inclusion, empowerment, and women’s leadership for the benefit of families and communities.<br><br>The project seeks to strengthen community capacity in order to provide more equitable, safe, and welcoming services to refugees and newcomers. It focuses on access to resources, skills development, self-confidence, mutual support, and solidarity.<br><br>SOFIFRAN warmly thanks Immigration, Refugees and Citizenship Canada, as well as OCASI, for their financial support and trust. Their contribution makes it possible to implement this important initiative for women, families, and diverse Francophone communities.<br><br>Together, we continue our commitment to building a more inclusive, equitable, and supportive community.</p>', 'renforcer-les-capacites-pour-des-services-equitables-aux-refugies-et-nouveaux-arrivants', 'no', '2026-07-15 21:29:20', '2026-07-15 21:29:20');
