INSERT INTO `temoignages` (`id`, `name`, `content_fr`, `content_en`, `activite_id`, `image`, `created_at`, `updated_at`) VALUES
(1, 'Sonneja Desrosiers', 'Je voudrais témoigner de mon expérience avec SOFIFRAN. L’organisme m’a offert l’opportunité de faire deux stages qui m’ont permis de concilier mes habiletés théoriques à la réalité du milieu du travail.\r\nSofifran a pour mission de favoriser la promotion et l’épanouissement sociaux, économiques, éducatifs et culturels des nouveaux arrivants et des immigrants de la région du Niagara. J’ai largement bénéficié du professionnalisme et des encouragements du personnel. L’esprit de convivialité et la disponibilité qui caractérise l’équipe de Sofifran favorisent la solidarité et la cohésion du groupe.\r\n\r\nPour ces raisons, je suis reconnaissante envers Sofifran et exprime ma gratitude envers sa  belle équipe.', 'would like to talk about my experience with SOFIFRAN. The organization offered me the opportunity to do two internships that allowed me to reconcile my theoretical skills with the reality of the workplace.\r\n\r\nSofifran\'s mission is to foster the social, economic, educational and cultural development of newcomers and immigrants in the Niagara region. I have benefited greatly from the professionalism and encouragement of the staff. The spirit of friendliness and availability that characterizes the Sofifran team fosters solidarity and group cohesion.\r\n\r\nFor these reasons, I am grateful to Sofifran and express my gratitude to its great team.', NULL, '1653672097.png', '2022-05-27 20:26:06', '2022-05-27 18:26:06'),
(2, 'Marie-Sherlyne Jean-Charles', 'Pour moi, \'Sofifran est ma famille! J\'y ai trouvé l\'aide qui m\'a permise de progresser socialement, économiquement, et dans la réussite de l\'intégration de mes enfants et de moi-même. Leur soutien est constant. Merci Sofifran!', 'For me, \'Sofifran is my family! I have found the help that has allowed me to progress socially, economically, and in the successful integration of my children and myself. Their support is constant. Thank you Sofifran!', NULL, '1653683216.jpg', '2022-05-27 18:26:56', '2022-05-27 18:26:56');
