INSERT INTO `valeurs` (`id`, `titre_en`, `titre_fr`, `contenu_en`, `contenu_fr`, `created_at`, `updated_at`) VALUES
(1, 'Values', 'Valeurs', '<ul>\r\n              <li>Dignity</li> <br>\r\n              <li>Equity, accessibility, anti-oppression and inclusion</li>\r\n              <li>Pride of belonging to this black community</li>\r\n              <li>The youth at the centre of our actions</li> <br>\r\n              <li>Use of evidence and relevant information to guide all aspects of the work.</li> <br>\r\n              <li>Collaboration and respectful partnership</li> <br>\r\n              <li>Self-respect and respect for others</li> <br>\r\n              <li>Rebuilding a new black identity</li> <br>\r\n              <li>Responsibility - to youth and the Black community</li> <br>\r\n              <li>Intersectionality guides all work - considering a complex and diverse community - race, gender, sexual orientation, religion, health status, etc. </li>\r\n          </ul>', '<ul>\r\n              <li>Unité</li> <br>\r\n              <li>Équité, accès, anti-oppression et inclusion</li>\r\n              <li>Utilisation de données probantes et pertinentes pour guider tous les aspects du travail</li>\r\n              <li>Collaboration et partenariat respectueux</li> <br>\r\n              <li>Respect de soi et des autres</li> <br>\r\n              <li>Reconstruire une nouvelle identité noire</li> <br>\r\n              <li>Fierté d’appartenance à cette communauté noire</li> <br>\r\n              <li>Le jeune au cœur de nos actions</li> <br>\r\n              <li>Responsabilité - envers les jeunes et la communauté noire</li> <br>\r\n              <li>L’intersectionnalité guide l\'ensemble du travail – tenant compte d\'une communauté complexe et diverse - race, sexe, orientation sexuelle, religion, état de santé, etc.</li>\r\n          </ul>', '2021-01-17 15:43:42', '0000-00-00 00:00:00');
