INSERT INTO `visions` (`id`, `titre_en`, `titre_fr`, `contenu_en`, `contenu_fr`, `created_at`, `updated_at`) VALUES
(1, 'Vision', 'Vision', 'Rebuild and restore a new African Canadian identity where African Canadian youth will be rooted in their dignity and heritage and will have the same opportunities for justice. Giving a voice to black youth at risk in the criminal justice system.', 'Reconstruire et restituer une nouvelle identité afro-canadienne où les jeunes noirs à risque se retrouveront. Donner une voix plus forte aux jeunes noirs à risque dans le système pénal.', '2021-01-17 15:34:46', '0000-00-00 00:00:00');
